class InputReader {
private:
    std::istream& stream;
    std::string buffer;
    size_t pos;

public:
    InputReader(std::istream& is) : stream(is), pos(0) {}

    int read() {
        if (buffer.empty() || pos >= buffer.size()) {
            std::string line;
            if (std::getline(stream, line)) {
                buffer = line + "\n";
                pos = 0;
            } else {
                return -1;
            }
        }
        return static_cast<unsigned char>(buffer[pos++]);
    }

    int peek() {
        if (buffer.empty() || pos >= buffer.size()) {
            std::string line;
            if (std::getline(stream, line)) {
                buffer = line + "\n";
                pos = 0;
            } else {
                return -1;
            }
        }
        if (pos >= buffer.size()) return -1;
        return static_cast<unsigned char>(buffer[pos]);
    }

    void skip(int x) {
        while (x-- > 0) read();
    }

    int nextInt() {
        return std::stoi(next());
    }

    long nextLong() {
        return std::stol(next());
    }

    std::string nextString() {
        return next();
    }

    std::string next() {
        int c = read();
        while (c != -1 && std::isspace(c)) {
            c = read();
        }
        std::string res;
        while (c != -1 && !std::isspace(c)) {
            res += static_cast<char>(c);
            c = read();
        }
