        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }
        if (a[0] % 2 == 1)
            odd[0] = 1;
        else odd[0]--;
        for (int i = 1; i < n; i++) {
            if (a[i] % 2 == 1)
                odd[i] = odd[i - 1] + 1;
            else odd[i] = odd[i - 1] - 1;
        }
        for (int i = 0; i < n - 1; i++) {
            price[i] = abs(a[i + 1] - a[i]);
        }
        ArrayList<Integer> prices = new ArrayList<>();
        for (int i = 1; i < n - 1; i++) {
            if (odd[i] == 0) {
                prices.add(price[i]);
            }
