        prefixOdd[0] = (arr[0] % 2 == 1) ? 1 : -1;
        for (int i = 1; i < n; i++) {
            prefixOdd[i] = prefixOdd[i - 1] + ((arr[i] % 2 == 1) ? 1 : -1);
