        if (value % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }

        if (oddCount == evenCount) {
            int nextValue = values[i + 1];
            int cost = std::abs(nextValue - value);
            cutCosts.push_back(cost);
        }
    }

    std::sort(cutCosts.begin(), cutCosts.end());

    for (int cost : cutCosts) {
        if (coins >= cost) {
            coins -= cost;
            maxCuts++;
        } else {
            break;
        }
    }

    std::cout << maxCuts << std::endl;

    return 0;
}

