    }

    int readInteger() {
        return std::stoi(nextToken());
    }

    long long readLong() {
        return std::stoll(nextToken());
    }
};

class OutputHandler {
private:
    std::ostream& writer;

public:
    OutputHandler(std::ostream& stream) : writer(stream) {}

    void write(int value) {
        writer << value << std::endl;
    }

    void close() {
        writer.flush();
    }
};

class UnstoppableAlgorithm {
public:
    void compute(InputHandler& in, OutputHandler& out) {
        int n = in.readInteger();
        long long budget = in.readLong();
        std::vector<int> data(n);
        std::vector<int> parity(n);

        for (int idx = 0; idx < n; idx++) {
            data[idx] = in.readInteger();
            parity[idx] = (data[idx] % 2 == 0) ? 1 : -1;
        }

        std::vector<int> validDifferences;
        long long cumulative = 0;

        for (int i = 0; i < n - 1; i++) {
            cumulative += parity[i];
            if (cumulative == 0) {
                validDifferences.push_back(std::abs(data[i] - data[i + 1]));
            }
        }

        std::sort(validDifferences.begin(), validDifferences.end());
        long long spent = 0;
        int selectedCount = 0;

        for (int diff : validDifferences) {
            if ((spent += diff) <= budget) {
                selectedCount++;
            } else {
                break;
            }
        }

        out.write(selectedCount);
    }
};

class Main {
public:
    void runProgram() {
        InputHandler input(std::cin);
        OutputHandler output(std::cout);

        UnstoppableAlgorithm algo;
        algo.compute(input, output);

        output.close();
    }
};

int main() {
    Main mainInstance;
    mainInstance.runProgram();
    return 0;
}

