struct Transition {
    int cost;
    int index;

    Transition(int c, int idx) : cost(c), index(idx) {}

    bool operator<(const Transition& other) const {
        if (cost != other.cost) {
            return cost > other.cost; // Min-heap behavior
        }
        return index > other.index;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, k;
    std::cin >> n >> k;

    std::vector<int> sequence(n);
    std::vector<int> prefixParity(n);

    for (int i = 0; i < n; i++) {
        std::cin >> sequence[i];
        if (i == 0) {
            prefixParity[i] = ((sequence[i] & 1) == 0) ? 1 : -1;
        } else {
            prefixParity[i] = prefixParity[i-1] + (((sequence[i] & 1) == 0) ? 1 : -1);
        }
    }

    std::priority_queue<Transition> pq;
    for (int i = 0; i < n-1; i++) {
        int diff = std::abs(sequence[i+1] - sequence[i]);
        pq.push(Transition(diff, i));
    }

    int operations = 0;
    while (!pq.empty()) {
        Transition t = pq.top();
        pq.pop();
        if (k >= t.cost && prefixParity[t.index] == 0) {
            k -= t.cost;
            operations++;
        }
    }

    std::cout << operations << std::endl;

    return 0;
}

