public:
    string line;
    int pos;
    Reader() : pos(0) {}

    string next() {
        while (true) {
            if (pos >= line.size()) {
                if (!getline(cin, line)) throw runtime_error("EOF");
                pos = 0;
                continue;
            }
            while (pos < line.size() && line[pos] == ' ') pos++;
            if (pos >= line.size()) continue;
            int start = pos;
            while (pos < line.size() && line[pos] != ' ') pos++;
            return line.substr(start, pos - start);
        }
