    private static final int MOD = (int)1e9+7;
    private static InputReader reader;
    private static PrintWriter writer;

    public static void main(String[] args) {
        reader = new InputReader(System.in);
        writer = new PrintWriter(System.out);

        int n = reader.nextInt();
        int budget = reader.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = reader.nextInt();
        }

        List<Integer> validDifferences = new ArrayList<>();
        int evens = 0, odds = 0;

        for (int i = 0; i < n - 1; i++) {
            if (arr[i] % 2 == 0) evens++;
            else odds++;

            if (evens == odds) {
                validDifferences.add(Math.abs(arr[i] - arr[i+1]));
            }
        }

        Collections.sort(validDifferences);

        int cost = 0;
        int count = 0;
        for (int diff : validDifferences) {
            if (cost + diff > budget) break;
            cost += diff;
            count++;
        }

        writer.println(count);
        writer.flush();
        writer.close();
        reader.close();
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 13];
        private int ptr = 0, len = 0;

        public InputReader(InputStream stream) {
            in = stream;
        }

        private int read() {
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException("Invalid number");
                val = val * 10 + c - '0';
                c = read();
            } while (c > 32);
            return val * sign;
        }

        public void close() {
            try { in.close(); } catch (IOException ignored) {}
        }
    }
}

