#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <string>
#include <sstream>
#include <stdexcept>

class FastScanner {
private:
    std::istream& is;
    std::string buffer;
    size_t pos;

public:
    FastScanner(std::istream& input) : is(input), pos(0) {}

    std::string next() {
        while (true) {
            if (buffer.empty() || pos >= buffer.size()) {
                if (!std::getline(is, buffer)) {
                    throw std::runtime_error("No more input");
                }
                pos = 0;
            }

            while (pos < buffer.size() && std::isspace(buffer[pos])) {
                pos++;
            }

            if (pos >= buffer.size()) {
                buffer.clear();
                continue;
            }

            size_t start = pos;
            while (pos < buffer.size() && !std::isspace(buffer[pos])) {
                pos++;
            }

            return buffer.substr(start, pos - start);
        }
    }

    int nextInt() {
        std::string token = next();
        try {
            return std::stoi(token);
        } catch (...) {
            throw std::runtime_error("Invalid integer: " + token);
        }
    }

    void close() {
        // Nothing to close for standard streams
    }
};

int main() {
    FastScanner fs(std::cin);
    int n = fs.nextInt();
    int B = fs.nextInt();
    std::vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        arr[i] = fs.nextInt();
    }

    std::vector<int> candidateDiffs;
    int evenCount = 0, oddCount = 0;

    for (int i = 0; i < n - 1; i++) {
        if (arr[i] % 2 == 0) evenCount++;
        else oddCount++;

        if (evenCount == oddCount) {
            candidateDiffs.push_back(std::abs(arr[i] - arr[i + 1]));
        }
    }

    std::sort(candidateDiffs.begin(), candidateDiffs.end());

    int spent = 0;
    int selected = 0;
    for (int diff : candidateDiffs) {
        if (spent + diff > B) break;
        spent += diff;
        selected++;
    }

    std::cout << selected << std::endl;

    return 0;
}

