class Cutting {
public:
    vector<int> strToIntArr(string s) {
        vector<int> retArr;
        stringstream ss(s);
        string item;
        while (ss >> item) {
            retArr.push_back(stoi(item));
        }
        return retArr;
    }

    bool checkSub(const vector<int>& aArr, int splitInd) {
        int nEven = 0;
        int nOdd = 0;
        for (int i = 0; i <= splitInd; i++) {
            int el = aArr[i];
            if ((el % 2) == 0) {
                nEven++;
            } else {
                nOdd++;
            }
        }
        return (nEven == nOdd);
    }

    int getMinAvailInd(const vector<int>& aArr, int nCoins, unordered_map<int, bool>& cutUsed) {
        int len = aArr.size();
        int minInd = -1;
        int minCost = nCoins + 1;

        for (int i = 1; i < (len - 1); i++) {
            int cost = abs(aArr[i] - aArr[i + 1]);
            if (cost < minCost) {
                if (checkSub(aArr, i)) {
                    if (cutUsed.find(i) == cutUsed.end()) {
                        minCost = cost;
                        minInd = i;
                    }
                }
            }
        }
        return minInd;
    }

