    FastScanner(istream& input) : in(&input), buffer(""), pos(0) {}

    string nextLine() {
        string line;
        if (getline(*in, line)) {
            return line;
        }
        return "";
    }

    string next() {
        while (true) {
            if (buffer.empty() || pos >= buffer.size()) {
                if (!getline(*in, buffer)) {
                    return "";
                }
                pos = 0;
            }

            while (pos < buffer.size() && isspace(buffer[pos])) {
                pos++;
            }

            if (pos >= buffer.size()) {
                buffer = "";
                continue;
            }

            size_t start = pos;
            while (pos < buffer.size() && !isspace(buffer[pos])) {
                pos++;
            }
            return buffer.substr(start, pos - start);
        }
    }

    int nextInt() {
        string token = next();
        return stoi(token);
    }

    long nextLong() {
        string token = next();
        return stol(token);
    }

    double nextDouble() {
        string token = next();
        return stod(token);
    }
};

