class FastScanner {
private:
    istream* in;
    string line;
    int pos;

public:
    FastScanner(istream& input) : in(&input), line(""), pos(0) {}

    string nextLine() {
        if (!getline(*in, line)) {
            return "";
        }
        pos = 0;
        return line;
    }

    string next() {
        while (true) {
            if (pos >= line.length()) {
                if (!getline(*in, line)) {
                    return "";
                }
                pos = 0;
            }

            // Skip whitespace
            while (pos < line.length() && isspace(line[pos])) {
                pos++;
            }

            if (pos >= line.length()) {
                continue;
            }

            // Read token
            string token;
            while (pos < line.length() && !isspace(line[pos])) {
                token += line[pos];
                pos++;
            }
            return token;
        }
    }

    int nextInt() {
        return stoi(next());
