int findLCA(vector<int>& match, vector<int>& base, vector<int>& parent, int a, int b) {
    vector<bool> visited(match.size(), false);
    while (true) {
        a = base[a];
        visited[a] = true;
        if (match[a] == -1) break;
        a = parent[match[a]];
    }
    while (true) {
        b = base[b];
        if (visited[b]) return b;
        b = parent[match[b]];
    }
}

void tracePath(vector<int>& match, vector<int>& base, vector<bool>& blossom, vector<int>& parent, int u, int lcaNode, int child) {
    for (; base[u] != lcaNode; u = parent[match[u]]) {
        blossom[base[u]] = true;
        blossom[base[match[u]]] = true;
        parent[u] = child;
        child = match[u];
    }
}

int findAugmentingPath(vector<vector<int>>& graph, vector<int>& match, vector<int>& parent, int root) {
    fill(parent.begin(), parent.end(), -1);
    int n = graph.size();
    vector<int> base(n);
    iota(base.begin(), base.end(), 0);

    vector<bool> visited(n, false);
    vector<int> queue(n);
    int head = 0, tail = 0;

    visited[root] = true;
    queue[tail++] = root;

    while (head < tail) {
        int u = queue[head++];
        for (int v : graph[u]) {
            if (base[u] == base[v] || match[u] == v) continue;

            if (v == root || (match[v] != -1 && parent[match[v]] != -1)) {
                int lcaNode = findLCA(match, base, parent, u, v);
                vector<bool> blossom(n, false);
                tracePath(match, base, blossom, parent, u, lcaNode, v);
                tracePath(match, base, blossom, parent, v, lcaNode, u);

                for (int i = 0; i < n; i++) {
                    if (blossom[base[i]]) {
                        base[i] = lcaNode;
                        if (!visited[i]) {
                            visited[i] = true;
                            queue[tail++] = i;
                        }
                    }
                }
            } else if (parent[v] == -1) {
                parent[v] = u;
                if (match[v] == -1) {
                    return v;
                }
                v = match[v];
                visited[v] = true;
                queue[tail++] = v;
            }
        }
    }
    return -1;
}

int computeMaxMatching(vector<vector<int>>& graph) {
    int n = graph.size();
    vector<int> match(n, -1);
    vector<int> parent(n);

    for (int start = 0; start < n; start++) {
        if (match[start] == -1) {
            int endpoint = findAugmentingPath(graph, match, parent, start);
            while (endpoint != -1) {
                int prev = parent[endpoint];
                int prevPrev = match[prev];
                match[endpoint] = prev;
                match[prev] = endpoint;
                endpoint = prevPrev;
            }
        }
    }

    return count(match.begin(), match.end(), -1) == n ? 0 : 
           (int)count_if(match.begin(), match.end(), [](int x) { return x != -1; }) / 2;
}

