    int n = graph.size();
    vector<int> base(n);
    iota(base.begin(), base.end(), 0);

    vector<bool> visited(n, false);
    vector<int> queue(n);
    int qStart = 0, qEnd = 0;

    visited[root] = true;
    queue[qEnd++] = root;

    while (qStart < qEnd) {
        int u = queue[qStart++];
        for (int v : graph[u]) {
            if (base[u] == base[v] || pair[u] == v) continue;

            if (v == root || (pair[v] != -1 && prev[pair[v]] != -1)) {
                int common = lowestCommonAncestor(pair, base, prev, u, v);
                vector<bool> blossom(n, false);
                colorPath(pair, base, blossom, prev, u, common, v);
                colorPath(pair, base, blossom, prev, v, common, u);

                for (int k = 0; k < n; k++) {
                    if (blossom[base[k]]) {
                        base[k] = common;
                        if (!visited[k]) {
                            visited[k] = true;
                            queue[qEnd++] = k;
                        }
                    }
                }
            } else if (prev[v] == -1) {
                prev[v] = u;
                if (pair[v] == -1) {
                    return v;
                }
                v = pair[v];
                visited[v] = true;
                queue[qEnd++] = v;
            }
        }
    }
    return -1;
}

int findMaximumMatching(vector<vector<int>>& graph) {
    int n = graph.size();
    vector<int> pair(n, -1);
    vector<int> prev(n);

    for (int i = 0; i < n; i++) {
        if (pair[i] == -1) {
            int end = locateAugmentingPath(graph, pair, prev, i);
            while (end != -1) {
                int parent = prev[end];
                int grandParent = pair[parent];
                pair[end] = parent;
                pair[parent] = end;
                end = grandParent;
            }
        }
    }

    return count(pair.begin(), pair.end(), -1) == 0 ? 0 : 
           (int)count_if(pair.begin(), pair.end(), [](int x) { return x != -1; }) / 2;
}

