int findLowestCommonAncestor(vector<int>& pairing, vector<int>& base, vector<int>& predecessor, int a, int b) {
    vector<bool> visited(pairing.size(), false);
    while (true) {
        a = base[a];
        visited[a] = true;
        if (pairing[a] == -1) break;
        a = predecessor[pairing[a]];
    }
    while (true) {
        b = base[b];
        if (visited[b]) return b;
        b = predecessor[pairing[b]];
    }
}

void markBlossomPath(vector<int>& pairing, vector<int>& base, vector<bool>& blossom, vector<int>& predecessor, int u, int lca, int child) {
    for (; base[u] != lca; u = predecessor[pairing[u]]) {
        blossom[base[u]] = true;
        blossom[base[pairing[u]]] = true;
        predecessor[u] = child;
        child = pairing[u];
    }
}

int searchAugmentingPath(vector<vector<int>>& graph, vector<int>& pairing, vector<int>& predecessor, int root) {
    fill(predecessor.begin(), predecessor.end(), -1);
    int n = graph.size();
    vector<int> base(n);
    iota(base.begin(), base.end(), 0);

    vector<bool> visited(n, false);
    vector<int> queue(n);
    int queueHead = 0, queueTail = 0;

    visited[root] = true;
    queue[queueTail++] = root;

    while (queueHead < queueTail) {
        int u = queue[queueHead++];
        for (int v : graph[u]) {
            if (base[u] == base[v] || pairing[u] == v) continue;

            if (v == root || (pairing[v] != -1 && predecessor[pairing[v]] != -1)) {
                int lca = findLowestCommonAncestor(pairing, base, predecessor, u, v);
                vector<bool> blossom(n, false);
                markBlossomPath(pairing, base, blossom, predecessor, u, lca, v);
                markBlossomPath(pairing, base, blossom, predecessor, v, lca, u);

                for (int k = 0; k < n; k++) {
                    if (blossom[base[k]]) {
                        base[k] = lca;
                        if (!visited[k]) {
                            visited[k] = true;
                            queue[queueTail++] = k;
                        }
                    }
                }
            } else if (predecessor[v] == -1) {
                predecessor[v] = u;
                if (pairing[v] == -1) {
                    return v;
                }
                v = pairing[v];
                visited[v] = true;
                queue[queueTail++] = v;
            }
        }
    }
    return -1;
}

int computeMaximumMatching(vector<vector<int>>& graph) {
    int n = graph.size();
    vector<int> pairing(n, -1);
    vector<int> predecessor(n);

    for (int i = 0; i < n; i++) {
        if (pairing[i] == -1) {
            int terminal = searchAugmentingPath(graph, pairing, predecessor, i);
            while (terminal != -1) {
                int predecessorNode = predecessor[terminal];
                int grandPredecessor = pairing[predecessorNode];
                pairing[terminal] = predecessorNode;
                pairing[predecessorNode] = terminal;
                terminal = grandPredecessor;
            }
        }
    }

    return count(pairing.begin(), pairing.end(), -1) == 0 ? 0 : 0;
}

