int findPath(vector<vector<int>>& graph, vector<int>& match, vector<int>& prev, int root) {
    fill(prev.begin(), prev.end(), -1);
    int n = graph.size();
    vector<int> base(n);
    for (int i = 0; i < n; i++) base[i] = i;

    vector<bool> used(n, false);
    vector<int> q(n);
    int qend = 0;
    used[root] = true;
    q[qend++] = root;

    for (int qbeg = 0; qbeg < qend; qbeg++) {
        int u = q[qbeg];
        for (int v : graph[u]) {
            if (base[u] == base[v] || match[u] == v) continue;
            if (v == root || (match[v] != -1 && prev[match[v]] != -1)) {
                // Find LCA
                vector<bool> used_lca(match.size(), false);
                int a = u, b = v;
                while (true) {
                    a = base[a];
                    used_lca[a] = true;
                    if (match[a] == -1) break;
                    a = prev[match[a]];
                }
                while (true) {
                    b = base[b];
                    if (used_lca[b]) {
                        int cb = b;
                        // Mark blossom
                        vector<bool> blossom(n, false);
                        // Path from u to cb
                        for (int cur = u; base[cur] != cb; cur = prev[match[cur]]) {
                            blossom[base[cur]] = true;
                            blossom[base[match[cur]]] = true;
                            prev[cur] = v;
                            v = match[cur];
                        }
                        blossom[cb] = true;
                        // Path from v to cb
                        v = u; // reset v
                        for (int cur = v; base[cur] != cb; cur = prev[match[cur]]) {
                            blossom[base[cur]] = true;
                            blossom[base[match[cur]]] = true;
                            prev[cur] = u;
                            u = match[cur];
                        }
                        blossom[cb] = true;

                        for (int i = 0; i < n; i++) {
                            if (blossom[base[i]]) {
                                base[i] = cb;
                                if (!used[i]) {
                                    used[i] = true;
                                    q[qend++] = i;
                                }
                            }
                        }
                        break;
                    }
                    b = prev[match[b]];
                }
            } else if (prev[v] == -1) {
                prev[v] = u;
                if (match[v] == -1) return v;
                v = match[v];
                used[v] = true;
                q[qend++] = v;
            }
        }
    }
    return -1;
}

int findMaxMatching(vector<vector<int>>& graph) {
    int n = graph.size();
    vector<int> match(n, -1);
    vector<int> prev(n);

    for (int i = 0; i < n; i++) {
        if (match[i] == -1) {
            int end = findPath(graph, match, prev, i);
            while (end != -1) {
                int p = prev[end];
                int pp = match[p];
                match[end] = p;
                match[p] = end;
                end = pp;
            }
        }
    }

    int count = 0;
    for (int x : match) {
        if (x != -1) count++;
    }
    return count / 2;
}

