using namespace std;

// Simple BigInteger implementation for the specific operations needed
class BigInteger {
public:
    long long value;

    BigInteger(long long v = 0) : value(v) {}

    static BigInteger valueOf(long long v) {
        return BigInteger(v);
    }

    BigInteger min(const BigInteger& other) const {
        return (value <= other.value) ? *this : other;
    }

    BigInteger max(const BigInteger& other) const {
        return (value >= other.value) ? *this : other;
    }

    bool equals(const BigInteger& other) const {
        return value == other.value;
    }

    BigInteger mod(const BigInteger& other) const {
        return BigInteger(value % other.value);
    }

    BigInteger multiply(const BigInteger& other) const {
        return BigInteger(value * other.value);
    }

    long long longValue() const {
        return value;
    }
};

int main() {
    string line;
    getline(cin, line);
    istringstream iss(line);
    vector<string> parts;
    string part;
    while (iss >> part) {
        parts.push_back(part);
    }

    BigInteger n(stoll(parts[0]));
    BigInteger m(stoll(parts[1]));

    BigInteger x1 = n.min(m);
    BigInteger x2 = n.max(m);

    if (x1.equals(BigInteger(1))) {
        int memo[] = {0, 1, 2, 3, 2, 1};
        long long modVal = x2.mod(BigInteger(6)).longValue();
        cout << x1.multiply(x2).longValue() - memo[(int)modVal] << endl;
    } else if (x1.equals(BigInteger(2))) {
        if (x2.equals(BigInteger(2))) {
            cout << 0 << endl;
        } else if (x2.equals(BigInteger(3)) || x2.equals(BigInteger(7))) {
            cout << x1.multiply(x2).longValue() - 2 << endl;
        } else {
            cout << x1.multiply(x2).longValue() << endl;
        }
    } else if (x1.multiply(x2).mod(BigInteger(2)).equals(BigInteger(0))) {
