                    match[i][j] = true;
                }
            }
        }

        return 2 * maxMatching(match);
    }

    int maxMatching(const vector<vector<bool>>& graph) {
        int n1 = graph.size();
        int n2 = n1 == 0 ? 0 : graph[0].size();
        vector<int> matching(n2, -1);
        int matches = 0;
        for (int u = 0; u < n1; u++) {
            vector<bool> vis(n1, false);
            if (findPath(graph, u, matching, vis)) {
                ++matches;
            }
        }
        return matches;
    }

    bool findPath(const vector<vector<bool>>& graph, int u1, vector<int>& matching, vector<bool>& vis) {
        vis[u1] = true;
        for (int v = 0; v < (int)matching.size(); ++v) {
            int u2 = matching[v];
            if (graph[u1][v] && (u2 == -1 || !vis[u2] && findPath(graph, u2, matching, vis))) {
                matching[v] = u1;
                return true;
            }
        }
        return false;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    CFA solver;

    return 0;
}

