    static long compute(long rows, long cols) {
        if (rows < 3 && cols < 3) {
            return 0L;
        }
        if (rows == 1) {
            long total = cols;
            long remainder = cols % 6;
            if (remainder != 0) {
                if (remainder <= 3) {
                    total -= remainder;
                } else if (remainder == 4) {
                    total -= 2;
                } else if (remainder == 5) {
                    total -= 1;
                }
            }
            return total;
        }
        if (rows == 2) {
            if (cols == 3 || cols == 7) {
                return 2 * (cols - 1);
            }
            return 2 * cols;
