//			}
//			System.out.println();
			return true;
		}
		if (c >= C)
			return can(cur, r+1, 0);
		if (grid[r][c] != 0)
			return can(cur, r, c+1);
		grid[r][c] = cur;
		for (int dr = 0; dr <= 3; dr++)
		{
			for (int dc = -2; dc <= 3; dc++)
			{
				if (dr+Math.abs(dc) != 3)
					continue;
				if (ok(r+dr, c+dc))
				{
					grid[r+dr][c+dc] = cur;
					if (can(cur+1, r, c+1))
						return true;
					grid[r+dr][c+dc] = 0;
				}
			}
		}
		grid[r][c] = 0;
		return false;
