using namespace std;

class FS {
public:
    istream& in;
    string buffer;
    int pos;

    FS(istream& str) : in(str), pos(0) {}

    string next() {
        while (pos == 0) {
            if (!getline(in, buffer)) {
                return "";
            }
            pos = 0;
        }

        while (pos < buffer.size() && buffer[pos] == ' ') pos++;

        if (pos >= buffer.size()) {
            pos = 0;
            return next();
        }

        int start = pos;
        while (pos < buffer.size() && buffer[pos] != ' ') pos++;

        return buffer.substr(start, pos - start);
    }

    int nextInt() {
        return stoi(next());
    }
};

