class FastScanner {
private:
    std::string line;
    std::istringstream stream;
    bool hasLine = false;

public:
    std::string ns() {
        while (stream.fail() || stream.eof()) {
            if (!std::getline(std::cin, line)) {
                return "";
            }
            stream.clear();
            stream.str(line);
        }
        std::string token;
        stream >> token;
        return token;
    }

    long long ni() {
        return std::stoll(ns());
    }
};

class BDiv1 {
public:
    void solve(int testNumber, FastScanner& in, std::ostream& out) {
        long long n = in.ni(), m = in.ni();
        if (n > m) {
            long long t = n;
            n = m;
            m = t;
        }
