        final int MOD = 1_000_000_007;
        long sum = 0;

        // Use 1D DP optimization
        int[] prev = new int[n + 1];
        int[] curr = new int[n + 1];

        // Initialize first column (i=0)
        for (int i = 0; i <= n; i++) {
            prev[i] = 1;
            if (i % 2 == 1) {
                sum = (sum + 1) % MOD;
            }
        }

        // Process columns 1 to n
        for (int col = 1; col <= n; col++) {
            curr[col] = prev[col]; // dp[col][col-1]
            for (int row = col + 1; row <= n; row++) {
                curr[row] = (prev[row] + curr[row - 1]) % MOD;
                if ((row + col) % 2 == 1) {
                    sum = (sum + curr[row]) % MOD;
                }
            }
            // Swap arrays
            int[] temp = prev;
            prev = curr;
            curr = temp;
        }

        System.out.println(sum);
    }
}

