using namespace std;

const int MOD = 1000000007;

class InputReader {
public:
    istream& in;

    InputReader(istream& stream) : in(stream) {}

    string next() {
        string token;
        in >> token;
        return token;
    }

    int nextInt() {
        return stoi(next());
    }

    long long nextLong() {
        return stoll(next());
    }

    bool hasNext() {
        return in.peek() != EOF;
    }
};

class Main {
public:
    void solve() {
        InputReader in(cin);
        int n = in.nextInt();

        vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));
        dp[0][0] = 1;

        for (int i = 0; i <= n; i++) {
            for (int j = i; j <= n; j++) {
                if (j != i) {
                    dp[i][j] += dp[i][j - 1];
                }
                if (i != 0) {
                    dp[i][j] += dp[i - 1][j];
                }
                dp[i][j] %= MOD;
            }
        }

        long long ans = 0;
        for (int j = n; j >= 0; j--) {
            for (int i = j - 1; i >= 0; i -= 2) {
                ans += dp[i][j];
                ans %= MOD;
            }
        }

        cout << ans << endl;
    }

    void run() {
        try {
            solve();
        } catch (const exception& e) {
            cerr << e.what() << endl;
        }
    }
};

