    static class TaskF {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int MOD = 1_000_000_007;
            int[][] dp1 = new int[N+1][N+1];
            int[][] dp2 = new int[N+1][N+1];

            for (int x = N; x >= 0; --x)
                for (int y = N; y >= 0; --y) {
                    int d1=0;
                    int d2=0;
                    // calc d2
                    if (x+1 <= N) {
                        int m = Math.max(dp1[x+1][y], dp2[x+1][y]);
                        d2 += m;
                    }
                    d2 %= MOD;
                    if (y+1 <= Math.min(x, N)) {
                        int m = Math.max(dp1[x][y+1], dp2[x][y+1]);
                        d2 += m;
                    }
                    d2 %= MOD;

