#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <sstream>
#include <climits>

using namespace std;

const int MOD = 1000000007;

class InputReader {
public:
    istream& reader;
    string buffer;
    size_t pos;

    InputReader(istream& stream) : reader(stream), pos(0) {}

    string next() {
        while (true) {
            if (buffer.empty() || pos >= buffer.size()) {
                if (!getline(reader, buffer)) {
                    throw runtime_error("No more input");
                }
                pos = 0;
            }
            while (pos < buffer.size() && isspace(buffer[pos])) {
                pos++;
            }
            if (pos >= buffer.size()) {
                buffer.clear();
                continue;
            }
            size_t start = pos;
            while (pos < buffer.size() && !isspace(buffer[pos])) {
                pos++;
            }
            return buffer.substr(start, pos - start);
        }
    }

    int nextInt() {
        return stoi(next());
    }
};

class TaskF {
public:
    void solve(int testNumber, InputReader& in, ostream& out) {
        int N = in.nextInt();

        vector<vector<int>> dp1(N+1, vector<int>(N+1, 0));
        vector<vector<int>> dp2(N+1, vector<int>(N+1, 0));

        for (int x = N; x >= 0; --x) {
            for (int y = N; y >= 0; --y) {
                int d1 = 0;
                int d2 = 0;

                // calc d2
                if (x+1 <= N) {
                    int m = max(dp1[x+1][y], dp2[x+1][y]);
                    d2 = (d2 + m) % MOD;
                }
                d2 %= MOD;
                if (y+1 <= min(x, N)) {
                    int m = max(dp1[x][y+1], dp2[x][y+1]);
                    d2 = (d2 + m) % MOD;
                }
                d2 %= MOD;

                if (x+1 <= N) {
                    int m = max(dp1[x+1][y], dp2[x+1][y]);
                    int candidate = (1 + d2 - m + dp2[x+1][y]) % MOD;
                    if (candidate < 0) candidate += MOD;
                    d1 = max(d1, candidate);
                    d1 %= MOD;
                }
                if (y+1 <= min(x, N)) {
                    int m = max(dp1[x][y+1], dp2[x][y+1]);
                    int candidate = (1 + d2 - m + dp2[x][y+1]) % MOD;
                    if (candidate < 0) candidate += MOD;
                    d1 = max(d1, candidate);
                    d1 %= MOD;
                }
                d1 %= MOD;
                if (d1 < 0) d1 += MOD;
                d2 %= MOD;
                if (d2 < 0) d2 += MOD;

                dp1[x][y] = d1;
                dp2[x][y] = d2;
            }
        }

        int ans = max(dp1[0][0], dp2[0][0]);
        ans %= MOD;
        if (ans < 0) ans += MOD;

        out << ans << endl;
    }
};

int main() {
    InputReader in(cin);
    ostream& out = cout;
    TaskF solver;
    solver.solve(1, in, out);
    return 0;
}

