    void solve(int testNumber, InputReader& in, OutputWriter& out) {
        int n = in.readInt();
        out.print(compute(n));
    }

private:
    int compute(int n) {
        int maxLen = 2 * n + 1;
        std::vector<std::vector<int>> prev(maxLen, std::vector<int>(2, 0));
        std::vector<std::vector<int>> curr(maxLen, std::vector<int>(2, 0));
        prev[0][0] = 1;

        for (int step = 1; step <= 2 * n; step++) {
            for (int open = step & 1; open <= step; open += 2) {
                curr[open][0] = 0;
                curr[open][1] = 0;

                if (open > 0) {
                    curr[open][0] = (curr[open][0] + prev[open - 1][1]) % MOD;
                    curr[open][1] = (curr[open][1] + prev[open - 1][0]) % MOD;
                }
                if (open + 1 < maxLen) {
                    curr[open][0] = (curr[open][0] + prev[open + 1][1]) % MOD;
                    curr[open][1] = (curr[open][1] + prev[open + 1][0]) % MOD;
                }
                curr[open][0] = (curr[open][0] + 1) % MOD;
            }
            std::swap(prev, curr);
        }
        return prev[0][1];
    }
};

