const long long MOD = 998244353;

long long modPow(long long base, long long exp) {
    base %= MOD;
    long long result = 1;
    while (exp > 0) {
        if ((exp & 1) == 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long modInverse(long long a) {
    return modPow(a, MOD - 2);
}

class FastScanner {
private:
    const int BUFFER_SIZE = 1 << 16;
    unsigned char buffer[BUFFER_SIZE];
    int bufferPointer = 0, bytesRead = 0;
    FILE* file;

public:
    FastScanner() {
        file = stdin;
    }

    inline char readChar() {
        if (bufferPointer == bytesRead) {
            bytesRead = fread(buffer, 1, BUFFER_SIZE, file);
            if (bytesRead == 0) {
                buffer[0] = -1;
            }
            bufferPointer = 0;
        }
        return buffer[bufferPointer++];
    }

    long long nextLong() {
        long long num = 0;
        char c = readChar();
        bool neg = false;
        while (c <= ' ') {
            c = readChar();
        }
        if (c == '-') {
            neg = true;
            c = readChar();
        }
        while (c >= '0' && c <= '9') {
            num = (num << 3) + (num << 1) + (c - '0');
            c = readChar();
        }
        return neg ? -num : num;
    }

    int nextInt() {
        return (int)nextLong();
    }

    string next() {
        string sb = "";
        char c;
        while ((c = readChar()) <= ' ');
        do {
            sb += c;
        } while ((c = readChar()) > ' ');
        return sb;
    }
};

int main() {
    FastScanner sc;

    long long N = sc.nextLong();
    long long M = sc.nextLong();
    long long L = sc.nextLong();
    long long R = sc.nextLong();

    long long totalRange = R - L + 1;
    long long evenCount = totalRange / 2 + (totalRange % 2 == 0 && L % 2 == 0 ? 1 : 0);
    long long oddCount = totalRange - evenCount;

    long long totalWays;
    if ((N * M) % 2 == 1) {
        totalWays = modPow(evenCount + oddCount, N * M);
    } else {
        long long term1 = modPow(evenCount + oddCount, N * M);
        long long term2 = modPow(evenCount - oddCount, N * M);
        totalWays = (term1 + term2) % MOD;
        totalWays = (totalWays * modInverse(2)) % MOD;
    }

    cout << totalWays << endl;

    return 0;
}

