ll modPow(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

string reverseString(const string& str) {
    string reversed = str;
    reverse(reversed.begin(), reversed.end());
    return reversed;
}

bool isPalindrome(const string& str) {
    int i = 0, j = str.length() - 1;
    while (i < j) {
        if (str[i] != str[j]) {
            return false;
        }
        i++;
        j--;
    }
    return true;
}

int gcd(int a, int b) {
    if (a == 0) return b;
    return gcd(b % a, a);
}

int modInverse(int a, int m) {
    int g = gcd(a, m);
    if (g != 1) return -1;
    else return modPow(a, m - 2, m);
}

vector<int> primeGenerator(int num) {
    int length = 0;
    vector<int> arr(num);
    int a = num;
    int factor = 1;

    if (num % 2 == 0) {
        while (num % 2 == 0) {
            num /= 2;
            factor *= 2;
        }
        arr[length++] = factor;
    }

    for (int i = 3; i * i <= a; i += 2) {
        factor = 1;
        if (num % i == 0) {
            while (num % i == 0) {
                num /= i;
                factor *= i;
            }
            arr[length++] = factor;
        }
    }

    if (num > 1) {
        arr[length++] = num;
    }

    arr.resize(length);
    return arr;
}

