    BigInteger(long long v = 0) : value(v % 998244353) {}

    static BigInteger valueOf(long long v) {
        return BigInteger(v);
    }

    BigInteger modPow(BigInteger exponent, const BigInteger& mod) const {
        long long base = value;
        long long exp = exponent.value;
        long long modulus = mod.value;

        long long result = 1;
        base = base % modulus;

        while (exp > 0) {
            if (exp & 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exp >>= 1;
        }

        return BigInteger(result);
    }

    BigInteger add(const BigInteger& other) const {
        return BigInteger((value + other.value) % 998244353);
    }

    BigInteger subtract(const BigInteger& other) const {
        long long result = (value - other.value) % 998244353;
        if (result < 0) result += 998244353;
        return BigInteger(result);
    }

    BigInteger multiply(const BigInteger& other) const {
        return BigInteger((value * other.value) % 998244353);
    }

    BigInteger divide(BigInteger other) const {
        // For division by 2, we can use modular inverse
        // Since MOD is prime, inverse of 2 is (MOD+1)/2
        long long inv2 = 499122177; // (998244353 + 1) / 2
        return BigInteger((value * inv2) % 998244353);
    }

    void print() const {
        cout << value << endl;
    }
};

