        BigInteger exponent = BigInteger::valueOf(n * m);
        base.modPow(exponent, MOD).print();
    } else {
        long long evenCount = (R >> 1) - ((L - 1) >> 1);
        long long oddCount = k - evenCount;
        BigInteger E = BigInteger::valueOf(evenCount);
        BigInteger O = BigInteger::valueOf(oddCount);
        BigInteger exponent = BigInteger::valueOf(n * m);
        BigInteger sum = E.add(O);
        BigInteger diff = E.subtract(O);
        BigInteger result = sum.modPow(exponent, MOD).add(diff.modPow(exponent, MOD));
        BigInteger one = BigInteger::valueOf(1);
        BigInteger modPlusOne = BigInteger::valueOf(998244354);
        result = result.multiply(modPlusOne).divide(BigInteger::valueOf(2));
        result = result.modPow(BigInteger::valueOf(1), MOD);
        result.print();
    }

    return 0;
}

