const long long MOD = 998244353LL;

long long power(long long base, long long exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if ((exp & 1) == 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

class FastInput {
public:
    string line;
    int pos;

    FastInput() : pos(0) {}

    string next() {
        while (pos < line.size() && line[pos] == ' ') pos++;
        if (pos >= line.size()) {
            getline(cin, line);
            pos = 0;
            while (pos < line.size() && line[pos] == ' ') pos++;
        }
        int start = pos;
        while (pos < line.size() && line[pos] != ' ') pos++;
        return line.substr(start, pos - start);
    }

    long long nextLong() {
        string s = next();
        return stoll(s);
    }
};

