    long long n = input.nextLong();
    long long m = input.nextLong();
    long long l = input.nextLong();
    long long r = input.nextLong();

    long long total = n * m;

    if ((total & 1) == 1LL) {
        cout << power(r - l + 1, total) << endl;
        return 0;
    }

    long long evens = r / 2 - (l - 1) / 2;
    long long odds = (r - l + 1) - evens;

    long long sum = (evens + odds) % MOD;
    long long diff = ((evens - odds) % MOD + MOD) % MOD;

    long long term1 = power(sum, total);
    long long term2 = power(diff, total);
    long long sumTerms = (term1 + term2) % MOD;

    // Calculate modular inverse of 2 using Fermat's little theorem
    long long inv2 = power(2, MOD - 2);
    long long result = (sumTerms * inv2) % MOD;

    cout << result << endl;
    return 0;
}

