#include <iomanip>
using namespace std;

const long long MOD = 998244353LL;

long long modPow(long long base, long long exp, long long mod) {
    long long result = 1LL;
    base %= mod;
    while (exp > 0) {
        if ((exp & 1) == 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    string line;
    getline(cin, line);
    stringstream ss(line);
    vector<string> tokens;
    string token;
    while (ss >> token) {
        tokens.push_back(token);
    }

    long long N = stoll(tokens[0]);
    long long M = stoll(tokens[1]);
    long long L = stoll(tokens[2]);
    long long R = stoll(tokens[3]);

    long long totalCells = N * M;
    long long rangeSize = R - L + 1;

    if (totalCells % 2 == 1) {
        long long result = modPow(rangeSize, totalCells, MOD);
        cout << (result + MOD) % MOD << endl;
    } else {
        long long result = modPow(rangeSize, totalCells, MOD);

        if ((R - L) % 2 == 0) {
            result = (result + 1) % MOD;
        }

        long long inv2 = modPow(2, MOD - 2, MOD);
        result = (result * inv2) % MOD;
        cout << result << endl;
    }

    return 0;
}

