class Main {
public:
    static void main() {
        auto in = std::make_shared<FastScanner>(std::cin);
        auto out = std::make_shared<std::ostream>(std::cout.rdbuf());
        TaskC solver;
        solver.solve(1, in, out);
    }
};

class TaskC {
public:
    struct Point {
        int v, w, x, y, z;

        Point(int a, int b, int c, int d, int e) : v(a), w(b), x(c), y(d), z(e) {}

        double mag() const {
            return std::sqrt(v * v + w * w + x * x + y * y + z * z);
        }
    };

    static bool angle(const Point& a, const Point& b) {
        double amag = a.mag();
        double bmag = b.mag();
        double abmag = static_cast<double>(a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z);
        double angle = std::acos(abmag / (amag * bmag)) * 180.0 / M_PI;
        return angle < 90.0;
    }

    void solve(int testNumber, std::shared_ptr<FastScanner> in, std::shared_ptr<std::ostream> out) {
        int n = in->nextInt();
        if (n > 11) {
            *out << "0" << std::endl;
        } else {
            std::unordered_set<int> good;
            std::vector<Point> arr;

            for (int i = 0; i < n; i++) {
                int a = in->nextInt();
                int b = in->nextInt();
                int c = in->nextInt();
                int d = in->nextInt();
                int e = in->nextInt();
                Point p(a, b, c, d, e);
                arr.push_back(p);
            }

            for (int i = 0; i < n; i++) {
                bool b = true;
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if (i != j && i != k && j != k) {
                            Point one = arr[j];
                            Point two = arr[k];
                            Point three = arr[i];
                            Point lol2(one.v - three.v, one.w - three.w, one.x - three.x, one.y - three.y, one.z - three.z);
                            Point lol1(two.v - three.v, two.w - three.w, two.x - three.x, two.y - three.y, two.z - three.z);
                            if (angle(lol1, lol2)) {
                                b = false;
                            }
                        }
                    }
                }
                if (b) {
                    good.insert(i + 1);
                }
            }

            if (good.empty()) {
                *out << "0" << std::endl;
            } else {
                *out << good.size() << std::endl;
                for (int idx : good) {
                    *out << idx << std::endl;
                }
            }
        }
    }
};

class FastScanner {
public:
    std::istream* stream;
    std::string buffer;
    size_t pos;

    FastScanner(std::istream& s) : stream(&s), buffer(""), pos(0) {}

    std::string next() {
        while (pos >= buffer.size()) {
            std::string line;
            if (!std::getline(*stream, line)) {
                throw std::runtime_error("Unexpected end of input");
            }
            buffer = line;
            pos = 0;
        }

        while (pos < buffer.size() && buffer[pos] == ' ') pos++;

        size_t start = pos;
        while (pos < buffer.size() && buffer[pos] != ' ') pos++;

        if (start == pos) {
            throw std::runtime_error("No more tokens");
        }

        return buffer.substr(start, pos - start);
    }

    int nextInt() {
        return std::stoi(next());
    }
};

int main() {
    Main::main();
    return 0;
}

