        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int n = Integer.parseInt(br.readLine().trim());
            if (n > 11) {
                pw.println("0");
                return;
            }

            List<Point> points = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                String[] vals = br.readLine().split("\\s+");
                points.add(new Point(
                    Integer.parseInt(vals[0]),
                    Integer.parseInt(vals[1]),
                    Integer.parseInt(vals[2]),
                    Integer.parseInt(vals[3]),
                    Integer.parseInt(vals[4])
                ));
            }

            Set<Integer> goodIndices = new TreeSet<>();
            for (int i = 0; i < n; i++) {
                boolean isGood = true;
                for (int j = 0; j < n && isGood; j++) {
                    for (int k = 0; k < n && isGood; k++) {
                        if (i != j && i != k && j != k) {
                            Point v1 = points.get(j).subtract(points.get(i));
                            Point v2 = points.get(k).subtract(points.get(i));
                            if (dotProduct(v1, v2) > 0) {
                                isGood = false;
                            }
                        }
                    }
                }
                if (isGood) {
                    goodIndices.add(i + 1);
                }
            }

            if (goodIndices.isEmpty()) {
                pw.println("0");
            } else {
                pw.println(goodIndices.size());
                goodIndices.forEach(pw::println);
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

