        Point(int v, int w, int x, int y, int z) {
            this.v = v;
            this.w = w;
            this.x = x;
            this.y = y;
            this.z = z;
        }

        Point subtract(Point other) {
            return new Point(
                this.v - other.v,
                this.w - other.w,
                this.x - other.x,
                this.y - other.y,
                this.z - other.z
            );
        }

