            y - other.y,
            z - other.z
        );
    }

    double magnitude() const {
        return std::sqrt(v*v + w*w + x*x + y*y + z*z);
    }
};

double dotProduct(const Point& a, const Point& b) {
    return static_cast<double>(a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z);
}

int main() {
    try {
        std::string line;
        std::getline(std::cin, line);
        int n = std::stoi(line);

        if (n > 11) {
            std::cout << "0" << std::endl;
            return 0;
        }

        std::vector<Point> points;
        for (int i = 0; i < n; i++) {
            std::getline(std::cin, line);
            std::istringstream iss(line);
            std::vector<int> vals;
            std::string val;
            while (iss >> val) {
                vals.push_back(std::stoi(val));
            }
            points.push_back(Point(vals[0], vals[1], vals[2], vals[3], vals[4]));
        }

        std::set<int> goodIndices;
        for (int i = 0; i < n; i++) {
            bool isGood = true;
            for (int j = 0; j < n && isGood; j++) {
                for (int k = 0; k < n && isGood; k++) {
                    if (i != j && i != k && j != k) {
                        Point v1 = points[j].subtract(points[i]);
                        Point v2 = points[k].subtract(points[i]);
                        if (dotProduct(v1, v2) > 0) {
                            isGood = false;
                        }
                    }
                }
            }
            if (isGood) {
                goodIndices.insert(i + 1);
            }
        }

        if (goodIndices.empty()) {
            std::cout << "0" << std::endl;
        } else {
            std::cout << goodIndices.size() << std::endl;
            for (int idx : goodIndices) {
                std::cout << idx << std::endl;
            }
        }
    } catch (const std::exception& e) {
        throw std::runtime_error(e.what());
    }

