class TaskC {
public:
    struct Point {
        int v, w, x, y, z;

        Point(int a, int b, int c, int d, int e) : v(a), w(b), x(c), y(d), z(e) {}

        double mag() const {
            return std::sqrt(v * v + w * w + x * x + y * y + z * z);
        }
    };

    static bool angle(const Point& a, const Point& b) {
        double amag = a.mag();
        double bmag = b.mag();
        double abmag = static_cast<double>(a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z);
        double angle = std::acos(abmag / (amag * bmag)) * 180.0 / M_PI;
        if (angle < 90.0) {
            return true;
        }
        return false;
    }

    void solve(int testNumber, FastScanner& in, PrintWriter& out) {
        int n = in.nextInt();
        if (n > 11) {
            out.println("0");
        } else {
            std::unordered_set<int> good;
            std::vector<Point> arr;

            for (int i = 0; i < n; i++) {
                int a = in.nextInt();
                int b = in.nextInt();
                int c = in.nextInt();
                int d = in.nextInt();
                int e = in.nextInt();
                Point p(a, b, c, d, e);
                arr.push_back(p);
            }

            for (int i = 0; i < n; i++) {
                bool b = true;
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if (i != j && i != k && j != k) {
