                    out.println(idx);
                }
            }
        }
    }
};

class FastScanner {
private:
    std::istream& stream;
    std::string buffer;
    size_t pos;

public:
    FastScanner(std::istream& inputStream) : stream(inputStream), pos(0) {}

    std::string next() {
        while (buffer.empty() || pos >= buffer.size()) {
            if (!std::getline(stream, buffer)) {
                throw std::runtime_error("No more input");
            }
            pos = 0;
        }

        while (pos < buffer.size() && std::isspace(buffer[pos])) {
