                    dir1[dim] = points[idx1][dim] - points[center][dim];
                    dir2[dim] = points[idx2][dim] - points[center][dim];
                }

                long long dot = 0;
                for (int dim = 0; dim < 5; dim++) {
                    dot += dir1[dim] * dir2[dim];
                }

                if (dot > 0) {
                    isCenterGood = false;
                }
            }
        }

        if (isCenterGood) {
            result.push(center + 1);
        }
    }

    if (result.empty()) {
        std::cout << "0" << std::endl;
    } else {
        std::cout << result.size() << std::endl;
        std::vector<int> output;
        while (!result.empty()) {
            output.push_back(result.top());
            result.pop();
        }
        for (int i = output.size() - 1; i >= 0; i--) {
            std::cout << output[i] << std::endl;
        }
    }

    return 0;
}

