                    b[i] = in.nextInt();
                    c[i] = in.nextInt();
                    d[i] = in.nextInt();
                    e[i] = in.nextInt();
                }

                Set<Integer> bad = new HashSet<>();

                for (int i = 1; i <= n; i++) {
                    for (int j = 1; j <= n; j++) {
                        for (int k = 1; k <= n; k++) {
                            if (i == j || j == k || k == i) {
                                continue;
                            }

                            long ax = a[j] - a[i];
                            long bx = b[j] - b[i];
                            long cx = c[j] - c[i];
