            out << 0;
        } else {
            vector<int> a(105), b(105), c(105), d(105), e(105);
            for (int i = 1; i <= n; i++) {
                a[i] = in.nextInt();
                b[i] = in.nextInt();
                c[i] = in.nextInt();
                d[i] = in.nextInt();
                e[i] = in.nextInt();
            }

            set<int> bad;

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    for (int k = 1; k <= n; k++) {
