                        long long bx = (long long)c[j] - c[i];
                        long long cx = (long long)d[j] - d[i];
                        long long dx = (long long)e[j] - e[i];
                        long long ex = (long long)a[j] - a[i];

                        long long ay = (long long)b[k] - b[i];
                        long long by = (long long)c[k] - c[i];
                        long long cy = (long long)d[k] - d[i];
                        long long dy = (long long)e[k] - e[i];
                        long long ey = (long long)a[k] - a[i];

                        double val = (double)(ax * ay + bx * by + cx * cy + dx * dy + ex * ey);
                        long long m1 = ax * ax + bx * bx + cx * cx + dx * dx + ex * ex;
