#include <algorithm>
#include <sstream>
#include <string>
#include <cctype>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    std::cin.ignore();

    if (n >= 100) {
        std::cout << 0 << std::endl;
        return 0;
    }

    std::vector<std::vector<int>> points(n + 1, std::vector<int>(5));

    for (int i = 1; i <= n; i++) {
        std::string line;
        std::getline(std::cin, line);
        std::istringstream iss(line);
        for (int j = 0; j < 5; j++) {
            iss >> points[i][j];
        }
    }

    std::set<int> goodIndices;
    for (int i = 1; i <= n; i++) {
        goodIndices.insert(i);
    }

    for (int i = 1; i <= n; i++) {
        bool foundBad = false;
        for (int j = 1; j <= n && !foundBad; j++) {
            for (int k = 1; k <= n && !foundBad; k++) {
                if (i == j || j == k || k == i) continue;

                std::vector<long long> v1(5);
                std::vector<long long> v2(5);
                for (int d = 0; d < 5; d++) {
                    v1[d] = static_cast<long long>(points[j][d]) - points[i][d];
                    v2[d] = static_cast<long long>(points[k][d]) - points[i][d];
                }

                long long dot = 0, mag1 = 0, mag2 = 0;
                for (int d = 0; d < 5; d++) {
                    dot += v1[d] * v2[d];
                    mag1 += v1[d] * v1[d];
                    mag2 += v2[d] * v2[d];
                }

                double cosAngle = static_cast<double>(dot) / std::sqrt(static_cast<double>(mag1) * static_cast<double>(mag2));
                double angleDeg = std::acos(cosAngle) * 180.0 / M_PI;

                if (angleDeg + 1e-9 < 90.0) {
                    foundBad = true;
                }
            }
        }
        if (foundBad) {
            goodIndices.erase(i);
        }
    }

    std::cout << goodIndices.size() << std::endl;
    for (int idx : goodIndices) {
        std::cout << idx << std::endl;
    }

    return 0;
}

