public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int n = Integer.parseInt(br.readLine().trim());
            if (n >= 100) {
                pw.println(0);
                return;
            }

            int[][] points = new int[n+1][5];
            for (int i = 1; i <= n; i++) {
                String[] line = br.readLine().split("\\s+");
                for (int j = 0; j < 5; j++) {
                    points[i][j] = Integer.parseInt(line[j]);
                }
            }

            List<Integer> goodIndices = new ArrayList<>();

            for (int i = 1; i <= n; i++) {
                boolean isGood = true;
                for (int j = 1; j <= n && isGood; j++) {
                    for (int k = 1; k <= n && isGood; k++) {
                        if (i == j || j == k || k == i) continue;

                        long ax = points[j][0] - points[i][0];
                        long bx = points[j][1] - points[i][1];
                        long cx = points[j][2] - points[i][2];
                        long dx = points[j][3] - points[i][3];
                        long ex = points[j][4] - points[i][4];

                        long ay = points[k][0] - points[i][0];
                        long by = points[k][1] - points[i][1];
                        long cy = points[k][2] - points[i][2];
                        long dy = points[k][3] - points[i][3];
                        long ey = points[k][4] - points[i][4];

                        long dot = ax*ay + bx*by + cx*cy + dx*dy + ex*ey;
                        long mag1 = ax*ax + bx*bx + cx*cx + dx*dx + ex*ex;
                        long mag2 = ay*ay + by*by + cy*cy + dy*dy + ey*ey;

                        double cosAngle = dot / Math.sqrt(mag1 * mag2);
                        double angleDeg = Math.toDegrees(Math.acos(cosAngle));

                        if (angleDeg + 1e-9 < 90.0) {
                            isGood = false;
                        }
                    }
                }
                if (isGood) goodIndices.add(i);
            }

            pw.println(goodIndices.size());
            goodIndices.forEach(pw::println);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

