    string line;
    int pos;

    InputReader(istream& stream) : reader(stream), pos(0) {}

    string next() {
        while (true) {
            if (pos >= line.size()) {
                if (!getline(reader, line)) {
                    throw runtime_error("No more input");
                }
                pos = 0;
                continue;
            }
            while (pos < line.size() && isspace(line[pos])) {
                pos++;
            }
            if (pos >= line.size()) continue;

            int start = pos;
            while (pos < line.size() && !isspace(line[pos])) {
                pos++;
            }
            return line.substr(start, pos - start);
        }
    }

    int nextInt() {
        return stoi(next());
    }
};

