        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            if (n > 40) {
                out.println(0);
                return;
            } else {
                final ArrayList<TaskC.Point> points = new ArrayList<>();
                for (int i = 0; i < n; ++i) {
                    int a, b, c, d, e;
                    a = in.nextInt();
                    b = in.nextInt();
                    c = in.nextInt();
                    d = in.nextInt();
                    e = in.nextInt();
                    points.add(new TaskC.Point(a, b, c, d, e));
                }
                if (n < 3) {
                    out.println(n);
                    for (int i = 1; i <= n; ++i) {
                        out.println(i);
                    }
                    return;
                }
                ArrayList<Integer> result = new ArrayList<>();
                for (int center = 0; center < n; ++center) {
                    boolean find = false;
                    for (int a = 0; a < n; ++a)
                        if (a != center) {
                            for (int b = 0; b < n; ++b)
                                if (b != center && b != a) {
                                    TaskC.Point A = points.get(a).minus(points.get(center));
                                    TaskC.Point B = points.get(b).minus(points.get(center));
                                    if (A.dot(B)) {
                                        find = true;
                                        break;
                                    }
                                }
                            if (find) break;
                        }
                    if (!find) result.add(center + 1);
                }
                out.println(result.size());
                for (int id : result) {
                    out.println(id);
                }
            }
        }

