				for(int k=0; k<n; k++) {
					if(i == j || j == k || k == i) continue;
					int sum = 0;
					for(int l=0; l<5; l++) {
						sum += (a[j][l] - a[i][l]) * (a[k][l] - a[i][l]);
					}
					if(sum > 0) {
						flag = false;
						break loop;
					}
				}
			}

			if(flag) {
				ans.add(i + 1);
			}
		}

		System.out.println(ans.size());
		for(int i=0; i<ans.size(); i++) {
			System.out.println(ans.get(i));
		}
	}

