    cin >> n;

    if (n <= 11) {
        vector<vector<long long>> points(n, vector<long long>(5));

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                cin >> points[i][j];
            }
        }

        vector<vector<vector<long long>>> vectors(n, vector<vector<long long>>(n, vector<long long>(5)));

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < 5; k++) {
                    vectors[i][j][k] = points[j][k] - points[i][k];
