            bool flag = false;
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (!equal(vectors[i][j], vectors[i][k]) && dot(vectors[i][j], vectors[i][k])) {
                        list.insert(i + 1);
                        flag = true;
                        break;
                    }
                }
                if (flag) break;
            }
        }

