public class div375B
{
	BufferedReader in;
	PrintWriter ob;
	StringTokenizer st;
	public static void main(String[] args) throws IOException {
		new div375B().run();
	}
	void run() throws IOException {
		in=new BufferedReader(new InputStreamReader(System.in));
		ob=new PrintWriter(System.out);
		solve();
		ob.flush();
	}
	void solve() throws IOException {
		int n=ni();
		char s[]=ns().toCharArray();
		int ans1=0,ans2=0;
		for (int i=0; i<n ; i++ ) {
			if(s[i]=='(') {
				int c=0;
				while(i+1<n) {
					if(s[i+1]==')') {
						if(c>0)++ans2;
						break;
					}
					if(s[i+1]=='_'){
						if(c>0) {
							++ans2;
							c=0;
						}
					}
					else
						++c;
					++i;
				}	
			}
			else if(s[i]==')' || s[i]=='_') {
				int c=0;
				while(i+1<n && s[i+1]!=')' && s[i+1]!='_' && s[i+1]!='(') {++c;++i;}
				ans1=Math.max(c,ans1);
			}
			else {
				int c=0;
				while(i<n && s[i]!=')' && s[i]!='_' && s[i]!='(') {++c;++i;}
				ans1=Math.max(c,ans1);	
				--i;
			}
