class div375B {
private:
    string buffer;
    vector<string> tokens;
    int tokenIndex;

    string nextToken() {
        if (tokenIndex >= tokens.size()) {
            getline(cin, buffer);
            istringstream iss(buffer);
            tokens.clear();
            while (iss >> buffer) {
                tokens.push_back(buffer);
            }
            tokenIndex = 0;
        }
        return tokens[tokenIndex++];
    }

public:
    void solve() {
        int n = stoi(nextToken());
        string s;
        cin >> s;

        int ans1 = 0, ans2 = 0;
        for (int i = 0; i < n; ) {
            if (s[i] == '(') {
                int c = 0;
                while (i + 1 < n) {
                    if (s[i + 1] == ')') {
                        if (c > 0) ++ans2;
                        break;
                    }
                    if (s[i + 1] == '_') {
                        if (c > 0) {
                            ++ans2;
                            c = 0;
                        }
                    } else {
                        ++c;
                    }
                    ++i;
                }
                ++i;
            } else if (s[i] == ')' || s[i] == '_') {
                int c = 0;
                while (i + 1 < n && s[i + 1] != ')' && s[i + 1] != '_' && s[i + 1] != '(') {
                    ++c;
                    ++i;
