using namespace std;

class Solver {
public:
    void solve(istream& in, ostream& out) {
        int n;
        in >> n;
        string s;
        in >> s;

        int winpars = 0, longest = 0;
        int i = 0, j = 0;

        // Replace "__" with "_" until no more double underscores
        while (s.find("__") != string::npos) {
            size_t pos = 0;
            string temp = "";
            for (size_t k = 0; k < s.length(); ++k) {
                if (k < s.length() - 1 && s[k] == '_' && s[k+1] == '_') {
                    temp += '_';
                    ++k;
                } else {
                    temp += s[k];
                }
            }
            s = temp;
        }
        n = s.length();

        // First while loop for parentheses processing
        while (i < n && s[i] == '(') {
            j = i;
            while (j < n && s[j] != ')') {
                ++j;
            }
            if (j < n && s[j] == ')') {
                string temp = s.substr(i + 1, j - i - 1);
                if (temp.find('_') == string::npos && temp.length() > 0) {
                    ++winpars;
                } else {
                    vector<string> tokens;
                    string token = "";
                    for (char c : temp) {
                        if (c == '_') {
                            if (!token.empty()) {
                                tokens.push_back(token);
                                token = "";
                            }
                        } else {
                            token += c;
                        }
                    }
                    if (!token.empty()) {
                        tokens.push_back(token);
                    }
                    winpars += tokens.size();
                }
                i = j;
            }
            ++i;
        }

        // Second while loop for parentheses processing
        while (i < n) {
            while (i < n && s[i] != '(') {
                ++i;
            }
            if (i >= n) break;
            j = i;
            while (j < n && s[j] != ')') {
                ++j;
            }
            if (j < n && s[j] == ')') {
                string temp = s.substr(i + 1, j - i - 1);
                if (temp.find('_') == string::npos && temp.length() > 0) {
