using namespace std;

string normalizeUnderscores(string s) {
    while (s.find("__") != string::npos) {
        size_t pos = s.find("__");
        s.erase(pos, 1);
    }
    return s;
}

int countMatchingParenSegments(string s) {
    int total = 0;
    stack<int> stack;

    // First pass: count matching segments
    for (int i = 0; i < s.length(); ++i) {
        char c = s[i];
        if (c == '(') {
            stack.push(i);
        } else if (c == ')') {
            if (!stack.empty()) {
                int start = stack.top() + 1;
                stack.pop();
                string segment = s.substr(start, i - start);
                if (segment.empty()) {
                    total++;
                } else if (segment.find('_') == string::npos) {
                    total++;
                } else {
                    int nonEmpty = 0;
                    vector<string> parts;
                    stringstream ss(segment);
                    string part;
                    while (getline(ss, part, '_')) {
                        parts.push_back(part);
                    }
                    for (const string& p : parts) {
                        if (!p.empty()) nonEmpty++;
                    }
                    total += nonEmpty;
                }
            }
        }
    }

    // Replace parentheses with underscore
    string result = "";
    int i = 0;
    while (i < s.length()) {
        if (s[i] == '(') {
            int depth = 1;
            int j = i + 1;
            while (j < s.length() && depth > 0) {
                if (s[j] == '(') depth++;
                else if (s[j] == ')') depth--;
                j++;
            }
            if (depth == 0) {
                result += '_';
                i = j;
                continue;
            }
        }
        result += s[i];
        i++;
    }

    return total;
}

int computeMaxSegmentLength(string s) {
    // Replace parentheses with underscore
    string result = "";
    int i = 0;
    while (i < s.length()) {
        if (s[i] == '(') {
            int depth = 1;
            int j = i + 1;
            while (j < s.length() && depth > 0) {
                if (s[j] == '(') depth++;
                else if (s[j] == ')') depth--;
                j++;
            }
            if (depth == 0) {
                result += '_';
                i = j;
                continue;
            }
        }
        result += s[i];
        i++;
    }

    // Normalize underscores
    while (result.find("__") != string::npos) {
        size_t pos = result.find("__");
        result.erase(pos, 1);
    }

    int maxLen = 0;
    int curLen = 0;
    for (char c : result) {
        if (c == '_') {
            maxLen = max(maxLen, curLen);
            curLen = 0;
        } else {
            curLen++;
        }
    }
    maxLen = max(maxLen, curLen);
    return maxLen;
}

