    std::string s;
    std::getline(std::cin, s);

    // Split by parentheses content (non-greedy)
    std::vector<std::string> p;
    size_t start = 0;
    size_t end = 0;
    while (end < s.length()) {
        if (s[end] == '(') {
            // Find matching closing parenthesis
            int depth = 1;
            size_t closePos = end + 1;
            while (closePos < s.length() && depth > 0) {
                if (s[closePos] == '(') depth++;
                else if (s[closePos] == ')') depth--;
                closePos++;
            }
            if (depth == 0) {
                p.push_back(s.substr(start, end - start));
                start = closePos;
                end = closePos;
                continue;
            }
        }
        end++;
    }
    if (start < s.length()) {
        p.push_back(s.substr(start));
    }

    int maxLen = 0;
    for (const auto& part : p) {
        std::istringstream iss(part);
        std::string token;
        while (std::getline(iss, token, '_')) {
            maxLen = std::max(static_cast<int>(token.length()), maxLen);
        }
    }

    std::vector<std::string> li;
    char openParen = '(';
    char closeParen = ')';
    int last = -1;
    for (size_t i = 0; i < s.length(); i++) {
        char c = s[i];
