#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <stdexcept>
#include <algorithm>

class FI {
private:
    std::istream& is;
    std::string buffer;
    std::istringstream currentStream;

public:
    FI(std::istream& stream) : is(stream) {}

    bool hasNext() {
        if (currentStream.eof() && !is.eof()) {
            std::string line;
            if (std::getline(is, line)) {
                buffer = line;
                currentStream.str(buffer);
                currentStream.clear();
            }
        }
        return !currentStream.eof() || !is.eof();
    }

    std::string next() {
        if (currentStream.eof() && !is.eof()) {
            std::string line;
            if (std::getline(is, line)) {
                buffer = line;
                currentStream.str(buffer);
                currentStream.clear();
            }
        }

        std::string token;
        if (!(currentStream >> token)) {
            throw std::runtime_error("No more tokens available");
        }
        return token;
    }

    int nextInt() {
        std::string token = next();
        try {
            return std::stoi(token);
        } catch (const std::exception& e) {
            throw std::runtime_error("Invalid integer: " + token);
        }
    }
};

int main() {
    FI k(std::cin);
    std::cout.sync_with_stdio(false);

    while (k.hasNext()) {
        int n = k.nextInt();
        std::string s = k.next();

        bool ok = false;
        int one = 0;
        std::string tt = "";
        std::string twoans = "";
        bool wordnok = true;

        for (int c = 0; c < n; c++) {
            char ch = s[c];
            if (ch == '(') {
                ok = true;
                wordnok = true;
                tt = "";
            } else if (ch == ')') {
                tt = "";
                ok = false;
            } else {
                if (!ok) {
                    if (ch == '_') {
                        tt = "";
                    } else {
                        tt += ch;
                    }

                    if (tt.length() > twoans.length()) {
                        twoans = tt;
                    }
                } else {
                    if (ch == '_') {
                        wordnok = true;
                    } else {
                        if (wordnok) {
                            one++;
                            wordnok = false;
                        }
                    }
                }
            }
        }

        std::cout << twoans.length() << " " << one << std::endl;
    }

    std::cout.flush();
    return 0;
}

