#include <vector>
#include <sstream>
#include <cctype>
#include <algorithm>
#include <climits>

using namespace std;

class FI {
public:
    istream& in;
    string buffer;
    size_t pos;

    FI(istream& stream) : in(stream), pos(0) {}

    bool hasNext() {
        while (buffer.empty() || pos >= buffer.size()) {
            if (!getline(in, buffer)) {
                return false;
            }
            pos = 0;
        }
        return true;
    }

    string next() {
        while (true) {
            while (pos < buffer.size() && isspace(buffer[pos])) {
                pos++;
            }
            if (pos >= buffer.size()) {
                if (!getline(in, buffer)) {
                    return "";
                }
                pos = 0;
                continue;
            }
            size_t start = pos;
            while (pos < buffer.size() && !isspace(buffer[pos])) {
                pos++;
            }
            return buffer.substr(start, pos - start);
        }
    }

    int nextInt() {
        string token = next();
        return stoi(token);
    }
};

int main() {
    FI k(cin);
    cout.sync_with_stdio(false);

    while (k.hasNext()) {
        int n = k.nextInt();
        string s = k.next();

        int maxWordLength = 0;
        int wordCount = 0;
        bool inParentheses = false;
        int currentWordLength = 0;
        bool wordStarted = false;

        for (int i = 0; i < n; i++) {
            char ch = s[i];

            if (ch == '(') {
                inParentheses = true;
                currentWordLength = 0;
                wordStarted = false;
            } else if (ch == ')') {
                inParentheses = false;
                currentWordLength = 0;
            } else {
                if (!inParentheses) {
                    if (ch == '_') {
                        if (currentWordLength > 0) {
                            if (currentWordLength > maxWordLength) {
                                maxWordLength = currentWordLength;
                            }
                            currentWordLength = 0;
                        }
                        wordStarted = false;
                    } else {
                        currentWordLength++;
                        wordStarted = true;
                        if (i == n - 1 || s[i + 1] == '_') {
                            if (currentWordLength > maxWordLength) {
                                maxWordLength = currentWordLength;
                            }
                            currentWordLength = 0;
                        }
                    }
                } else {
                    if (ch == '_') {
                        wordStarted = false;
                    } else {
                        if (!wordStarted) {
                            wordCount++;
                            wordStarted = true;
                        }
                    }
                }
            }
        }

        cout << maxWordLength << " " << wordCount << endl;
    }

    return 0;
}

