public class Text_Document_Analysis {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            scanner.nextLine(); // consume newline
            String line = scanner.nextLine().trim();
            StringBuilder us = new StringBuilder();
            StringBuilder bc = new StringBuilder();
            int i = 0;
            while (i < n) {
                char c = line.charAt(i);
                if (c == '(') {
                    i++;
                    while (i < n && line.charAt(i) != ')') {
                        bc.append(line.charAt(i));
                        i++;
                    }
                    if (i < n) i++;
                    bc.append('_');
                    us.append('_');
                } else {
                    us.append(c);
                    i++;
                }
            }
            us.append('_');
            bc.append('_');

            int maxLen = 0, curLen = 0, groups = 0;
            // First pass: find longest run of non-underscore characters in 'us'
            for (int j = 0; j < us.length(); j++) {
                if (us.charAt(j) == '_') {
                    maxLen = Math.max(maxLen, curLen);
                    curLen = 0;
                } else {
                    curLen++;
                }
            }
            maxLen = Math.max(maxLen, curLen);

            // Second pass: count non-empty segments between underscores in 'bc'
            curLen = 0;
            for (int j = 0; j < bc.length(); j++) {
                if (bc.charAt(j) == '_') {
                    if (curLen > 0) groups++;
                    curLen = 0;
                } else {
                    curLen++;
                }
            }

            System.out.println(maxLen + " " + groups);
        }
    }
}

