                us.append(s.charAt(pos));
                bc.append(s.charAt(pos));
                pos++;
            }
        }

        us.append('_');
        bc.append('_');

        int maxSeq = 0, currentSeq = 0, groupCount = 0;
        String[] usParts = us.toString().split("_", -1);
        String[] bcParts = bc.toString().split("_", -1);

