        for (String token : tokens) {
            if (token.contains(")")) {
                String[] parts = token.split("\\)");
                String inside = parts[0];
                String[] words = inside.split("_");
                for (String w : words) {
                    if (!w.trim().isEmpty()) countInParens++;
                }
                if (parts.length > 1) {
                    String outside = parts[1];
                    String[] outsideWords = outside.split("_");
                    for (String w : outsideWords) {
                        if (!w.isEmpty()) {
                            maxLenOutside = Math.max(maxLenOutside, w.length());
                        }
                    }
                }
            } else {
                String[] outsideWords = token.split("_");
                for (String w : outsideWords) {
                    if (!w.isEmpty()) {
                        maxLenOutside = Math.max(maxLenOutside, w.length());
                    }
                }
            }
        }

        System.out.println(maxLenOutside + " " + countInParens);
        read.close();
    }
