    // Split by '('
    std::vector<std::string> tokens;
    size_t start = 0;
    size_t end = line.find('(');
    while (end != std::string::npos) {
        tokens.push_back(line.substr(start, end - start));
        start = end + 1;
        end = line.find('(', start);
    }
    tokens.push_back(line.substr(start));

    for (const std::string& token : tokens) {
        size_t parenPos = token.find(')');
        if (parenPos != std::string::npos) {
            std::string inside = token.substr(0, parenPos);
            std::string outside = (parenPos + 1 < token.length()) ? token.substr(parenPos + 1) : "";

            // Process inside part
            std::vector<std::string> words;
            size_t wordStart = 0;
            size_t wordEnd = inside.find('_');
            while (wordEnd != std::string::npos) {
                std::string word = inside.substr(wordStart, wordEnd - wordStart);
                bool allWhitespace = true;
                for (char c : word) {
                    if (!std::isspace(static_cast<unsigned char>(c))) {
                        allWhitespace = false;
                        break;
                    }
