class InputReader {
public:
    stringstream tokenizer;
    istream& input;

    InputReader(istream& inputStream) : input(inputStream) {}

    string next() {
        string token;
        while (tokenizer.eof() || tokenizer.peek() == EOF) {
            string line;
            if (!getline(input, line)) {
                break;
            }
            tokenizer.clear();
            tokenizer.str(line);
        }
        tokenizer >> token;
        return token;
    }

    int nextInt() {
        return stoi(next());
    }
};

