        vector<string> outSite;
        sregex_token_iterator iter(input.begin(), input.end(), pattern, -1);
        sregex_token_iterator end;
        while (iter != end) {
            outSite.push_back(*iter);
            ++iter;
        }
        int longest = 0;
        for (const string& s : outSite) {
            longest = max(longest, longestWords(s));
        }
        long numberInside = 0;
        sregex_iterator m(input.begin(), input.end(), pattern);
        sregex_iterator m_end;
        while (m != m_end) {
            string matched = (*m).str();
            string inner = trimParentheses(matched);
            vector<string> parts;
            stringstream ss(inner);
            string item;
            while (getline(ss, item, '_')) {
                if (!item.empty()) {
                    parts.push_back(item);
                }
            }
            numberInside += parts.size();
            ++m;
        }
        out << longest << " " << numberInside << endl;
    }

private:
    int longestWords(const string& line) {
        vector<int> lengths;
        stringstream ss(line);
