                if (depth > 0) {
                    String content = inside.toString();
                    if (!content.isEmpty()) {
                        String[] segs = content.split("_+", -1);
                        for (String seg : segs) {
                            if (!seg.isEmpty()) cnt++;
                        }
                    }
                }
                depth--;
            } else if (depth > 0) {
                inside.append(c);
            }
        }

        System.out.println(cnt);
    }
