        }
    }

    std::string processed = sb;
    std::vector<std::string> tokens;
    std::string temp;
    for (char c : processed) {
        if (c == '_') {
            if (!temp.empty()) {
                tokens.push_back(temp);
                temp.clear();
            }
        } else {
            temp += c;
        }
    }
    if (!temp.empty()) {
        tokens.push_back(temp);
    }

    int maxLen = 0;
    for (const std::string& token : tokens) {
        if (!token.empty()) {
            maxLen = std::max(maxLen, (int)token.length());
        }
    }

    std::cout << maxLen << std::endl;

    // Count underscore-separated segments inside parentheses
    int cnt = 0;
    depth = 0;
    std::string inside;
    for (char c : s) {
        if (c == '(') {
            depth++;
            inside.clear();
        } else if (c == ')') {
            if (depth > 0) {
                if (!inside.empty()) {
                    std::vector<std::string> segs;
                    std::string tempSeg;
                    for (char segChar : inside) {
                        if (segChar == '_') {
                            if (!tempSeg.empty()) {
                                segs.push_back(tempSeg);
                                tempSeg.clear();
                            }
                        } else {
                            tempSeg += segChar;
                        }
                    }
                    if (!tempSeg.empty()) {
                        segs.push_back(tempSeg);
                    }
                    for (const std::string& seg : segs) {
                        if (!seg.empty()) {
                            cnt++;
                        }
                    }
                }
            }
            depth--;
        } else if (depth > 0) {
            inside += c;
        }
    }

    std::cout << cnt << std::endl;

    return 0;
