int main() {
    int n;
    std::string s;

    std::cin >> n;
    std::cin >> s;

    // Replace parentheses and their contents with underscores
    std::string replaced = s;
    std::regex parenRegex("\\([^)]*\\)");
    replaced = std::regex_replace(replaced, parenRegex, "_");

    // Split by underscores
    std::vector<std::string> nonParenParts;
    size_t start = 0;
    size_t end = 0;
    while ((end = replaced.find('_', start)) != std::string::npos) {
        if (end > start) {
            nonParenParts.push_back(replaced.substr(start, end - start));
        }
        start = end + 1;
    }
    if (start < replaced.length()) {
        nonParenParts.push_back(replaced.substr(start));
    }

    int maxLen = 0;
    for (const std::string& part : nonParenParts) {
        if (!part.empty()) {
            maxLen = std::max(maxLen, static_cast<int>(part.length()));
        }
    }

    std::cout << maxLen << std::endl;

    // Count segments inside parentheses
    int count = 0;
    int startIdx = -1;
    for (int i = 0; i < s.length(); i++) {
        if (s[i] == '(') {
            startIdx = i;
        } else if (s[i] == ')' && startIdx != -1) {
            std::string inner = s.substr(startIdx + 1, i - startIdx - 1);
            if (!inner.empty()) {
                // Split by underscores
                std::vector<std::string> segments;
                size_t segStart = 0;
                size_t segEnd = 0;
                while ((segEnd = inner.find('_', segStart)) != std::string::npos) {
                    if (segEnd > segStart) {
                        segments.push_back(inner.substr(segStart, segEnd - segStart));
                    }
                    segStart = segEnd + 1;
                }
                if (segStart < inner.length()) {
                    segments.push_back(inner.substr(segStart));
                }

                for (const std::string& seg : segments) {
                    if (!seg.empty()) {
                        count++;
                    }
                }
            }
            startIdx = -1;
        }
    }

    std::cout << count << std::endl;

    return 0;
}

