import java.util.*;

public class P2 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();
        String s = sc.nextLine();

        int maxLen = 0, currLen = 0, wordCount = 0, innerLen = 0, parenDepth = 0;
        boolean inOuter = false, inInner = false;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);

            if (c == '(') {
                parenDepth++;
                maxLen = Math.max(maxLen, currLen);
                currLen = 0;
                inOuter = false;
            } else if (c == ')') {
                parenDepth--;
                if (parenDepth == 0 && innerLen > 0) {
                    wordCount++;
                    innerLen = 0;
                }
            }

            if (c != '(' && c != ')') {
                if (parenDepth == 0) {
                    if (c == '_') {
                        maxLen = Math.max(maxLen, currLen);
                        currLen = 0;
                        inOuter = false;
                    } else {
                        inOuter = true;
                        currLen++;
                    }
                } else {
                    if (c == '_') {
                        if (innerLen > 0) wordCount++;
                        innerLen = 0;
                        inInner = false;
                    } else {
                        inInner = true;
                        innerLen++;
                    }
                }
            }
        }

        maxLen = Math.max(maxLen, currLen);
        System.out.println(maxLen + " " + wordCount);
    }
}

