#include <iostream>
#include <string>
#include <functional>
#include <vector>
#include <algorithm>

void processSegment(const std::string& s, const std::function<void(int)>& consumer) {
    std::vector<std::string> tokens;
    size_t start = 0;
    size_t end = s.find('_');

    while (end != std::string::npos) {
        tokens.push_back(s.substr(start, end - start));
        start = end + 1;
        end = s.find('_', start);
    }
    tokens.push_back(s.substr(start));

    for (const auto& token : tokens) {
        consumer(token.length());
    }
}

void processInner(const std::string& s, const std::function<void(const std::string&)>& consumer) {
    std::vector<std::string> tokens;
    size_t start = 0;
    size_t end = s.find('_');

    while (end != std::string::npos) {
        tokens.push_back(s.substr(start, end - start));
        start = end + 1;
        end = s.find('_', start);
    }
    tokens.push_back(s.substr(start));

    for (const auto& token : tokens) {
        consumer(token);
    }
}

int main() {
    std::string line;

    // Skip first line
    std::getline(std::cin, line);

    // Read input string
    std::getline(std::cin, line);

    int maxLength = 0;
    int innerCount = 0;
    int segmentStart = 0;

    size_t lastClose = line.rfind(')');

    for (size_t i = 0; i < line.length(); i++) {
        if (line[i] == '(') {
            std::string segment = line.substr(segmentStart, i - segmentStart);
            processSegment(segment, [&maxLength](int len) {
                if (len > maxLength) maxLength = len;
            });

            size_t closeIndex = line.find(')', i);
            if (closeIndex == std::string::npos) break;

            std::string inner = line.substr(i + 1, closeIndex - i - 1);
            processInner(inner, [&innerCount](const std::string& token) {
                if (!token.empty()) innerCount++;
            });

            segmentStart = closeIndex + 1;
            i = closeIndex;
        }
    }

    std::string finalSegment = line.substr(segmentStart);
    processSegment(finalSegment, [&maxLength](int len) {
        if (len > maxLength) maxLength = len;
    });

    std::cout << maxLength << " " << innerCount << std::endl;

    return 0;
}

