        int underscoreCount = 0;
        int lastPos = -1;
        boolean insideParen = false;

        for (int pos = 0; pos < s.length(); pos++) {
            char ch = s.charAt(pos);
            if (ch == '_') {
                if (lastPos != pos - 1) {
                    if (insideParen) {
                        underscoreCount++;
                    } else {
                        maxGap = Math.max(maxGap, pos - 1 - lastPos);
                    }
