                insideParen = true;
                if (lastPos != pos - 1) {
                    maxGap = Math.max(maxGap, pos - 1 - lastPos);
                }
                lastPos = pos;
            } else if (ch == ')') {
                insideParen = false;
                if (lastPos != pos - 1) {
                    underscoreCount++;
                }
                lastPos = pos;
            }
        }

        if (lastPos != s.length() - 1) {
            maxGap = Math.max(maxGap, s.length() - 1 - lastPos);
