#include <algorithm>
#include <cctype>

int main() {
    std::string line;

    // Skip first line
    std::getline(std::cin, line);

    // Read second line
    std::getline(std::cin, line);

    int maxLen = 0;
    int i = 0;
    while (i < line.length()) {
        if (line[i] == '(') {
            int start = i + 1;
            while (i < line.length() && line[i] != ')') i++;
            std::string id = line.substr(start, i - start);
            int j = 0;
            while (j < id.length()) {
                int k = j;
                while (k < id.length() && std::isalpha(id[k])) k++;
                if (k > j) {
                    maxLen = std::max(maxLen, k - j);
                }
                j = k + 1;
            }
        } else {
            int j = i;
            while (j < line.length() && line[j] != '(') j++;
            std::string segment = line.substr(i, j - i);
            size_t pos = 0;
            while (pos < segment.length()) {
                size_t start_pos = segment.find_first_not_of('_', pos);
                if (start_pos == std::string::npos) break;
                size_t end_pos = segment.find('_', start_pos);
                if (end_pos == std::string::npos) {
                    end_pos = segment.length();
                }
                std::string p = segment.substr(start_pos, end_pos - start_pos);
                maxLen = std::max(maxLen, static_cast<int>(p.length()));
                pos = end_pos;
            }
            i = j;
            continue;
        }
        i++;
    }

    int count = 0;
    bool inParens = false;
    bool prevWasLetter = false;

    for (int j = 0; j < line.length(); j++) {
        char c = line[j];
        if (c == '(') {
            inParens = true;
            prevWasLetter = false;
        } else if (c == ')') {
            inParens = false;
            prevWasLetter = false;
        } else if (inParens && std::isalpha(c)) {
            if (!prevWasLetter) {
                count++;
            }
            prevWasLetter = true;
        } else {
            prevWasLetter = false;
        }
    }

    std::cout << maxLen << " " << count << std::endl;

    return 0;
}

