class InputReader {
private:
    std::istream& stream;
    std::string buffer;
    int pos;

public:
    InputReader(std::istream& s) : stream(s), pos(0) {}

    int read() {
        if (buffer.empty() || pos >= buffer.size()) {
            std::string line;
            if (std::getline(stream, line)) {
                buffer = line + "\n";
                pos = 0;
            } else {
                return -1;
            }
        }
        return static_cast<unsigned char>(buffer[pos++]);
    }

    int readInt() {
        int c = read();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = read();
        }
        return res * sgn;
    }

    std::string readString() {
        int c = read();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = read();
        std::string res;
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            res += static_cast<char>(c);
            c = read();
        }
        return res;
    }

    double readDouble() {
        int c = read();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        double res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = read();
        }
        if (c == '.') {
            c = read();
            double m = 1;
            while (c >= '0' && c <= '9') {
                m /= 10;
                res += (c - '0') * m;
                c = read();
            }
        }
        return res * sgn;
    }

    long readLong() {
        int c = read();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = read();
        }
        return res * sgn;
    }
};

class OutputWriter {
private:
    std::ostream& stream;

public:
    OutputWriter(std::ostream& s) : stream(s) {}

    void print(const std::vector<std::string>& objects) {
        for (size_t i = 0; i < objects.size(); ++i) {
            if (i != 0) stream << ' ';
            stream << objects[i];
        }
    }

    void println(const std::vector<std::string>& objects) {
        print(objects);
        stream << '\n';
    }

    void close() {
        stream.flush();
    }
};

int main() {
    InputReader in(std::cin);
    OutputWriter out(std::cout);

    int n = in.readInt();
    std::string st = in.readString();
    std::vector<char> c(st.begin(), st.end());
    int a1 = 0, a2 = 0;
    std::string sb = "";
    std::string sb2 = "";

    for (int i = 0; i < n; i++) {
        if (c[i] == '(') {
            sb += "_";
            i++;
            while (i < n && c[i] != ')') {
                sb2 += c[i];
                i++;
            }
            sb2 += "_";
        } else {
            sb += c[i];
        }
    }

    std::vector<std::string> parts;
    std::istringstream iss(sb);
    std::string token;
    while (std::getline(iss, token, '_')) {
        parts.push_back(token);
    }
    for (size_t i = 0; i < parts.size(); i++) {
        a1 = std::max(a1, static_cast<int>(parts[i].length()));
    }

    parts.clear();
    std::istringstream iss2(sb2);
    while (std::getline(iss2, token, '_')) {
        parts.push_back(token);
    }
    for (size_t i = 0; i < parts.size(); i++) {
        if (parts[i].length() > 0) a2++;
    }

    std::vector<std::string> result;
    result.push_back(std::to_string(a1));
    result.push_back(std::to_string(a2));
    out.println(result);
    out.close();

    return 0;
}

