class InputReader {
private:
    std::istream& stream;
    std::vector<std::string> tokens;
    std::vector<std::string>::iterator tokenIter;

public:
    InputReader(std::istream& s) : stream(s) {}

    std::string readLine() {
        std::string line;
        std::getline(stream, line);
        return line;
    }

    int readInt() {
        std::string token = next();
        return std::stoi(token);
