int count(const std::string& s) {
    if (s.empty()) return 0;
    std::string temp = s;
    size_t pos = 0;
    while ((pos = temp.find("__")) != std::string::npos) {
        temp.replace(pos, 2, "_");
    }

    std::vector<std::string> parts;
    size_t start = 0;
    size_t end = 0;

    while ((end = temp.find("_", start)) != std::string::npos) {
        if (end > start) {
            parts.push_back(temp.substr(start, end - start));
        }
        start = end + 1;
    }
    if (start < temp.length()) {
        parts.push_back(temp.substr(start));
    }

    int result = parts.size();
    if (!s.empty()) {
        if (s[0] == '_') result--;
        if (!s.empty() && s[s.length()-1] == '_') result--;
        result++;
    }

