long long powMod(long long b, long long e) {
    long long res = 1;
    b %= MOD;
    while (e > 0) {
        if ((e & 1) == 1) res = (res * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return res;
}

long long invMod(long long x) {
    return powMod(x, MOD - 2);
}

struct State {
