    for (int i = 1; i < 51; i++) {
        fac[i] = (fac[i-1] * i) % MOD;
    }

    for (int i = 0; i < 51; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            long long den = (fac[j] * fac[i-j]) % MOD;
            C[i][j] = (fac[i] * invMod(den)) % MOD;
