const long long MOD = 1000000007LL;

long long modPow(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if ((exp & 1) == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modInv(long long a) {
    return modPow(a, MOD - 2);
}

class Vertex {
public:
    int f, h, flag, depth;
    long long count;
    vector<Vertex*> connections;

    Vertex(int five, int hundred, int flag) : f(five), h(hundred), flag(flag), depth(0), count(0) {}
};

int main() {
