    factorial[0] = 1;
    for (int i = 1; i <= 50; i++) {
        factorial[i] = (factorial[i - 1] * i) % MOD;
    }

    long long C[51][51];
    memset(C, 0, sizeof(C));
    for (int i = 0; i < 51; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            long long denom = (factorial[j] * factorial[i - j]) % MOD;
            C[i][j] = (factorial[i] * modInv(denom)) % MOD;
        }
    }

    int n, k;
    cin >> n >> k;
    int fifty = 0, hundred = 0;
    for (int i = 0; i < n; i++) {
        int v;
