            graph[a][b][1] = new Vertex(a, b, 1);
        }
    }

    for (int a = 0; a <= fifty; a++) {
        for (int b = 0; b <= hundred; b++) {
            int maxFifty = min(k / 50, a);
            int maxHundred = min(k / 100, b);

            for (int hUse = maxHundred; hUse >= 0; hUse--) {
                int remaining = k - (100 * hUse);
                int maxFiftyUse = min(maxFifty, remaining / 50);

                for (int fUse = maxFiftyUse; fUse >= 0; fUse--) {
                    if (fUse == 0 && hUse == 0) continue;

                    Vertex* from = graph[a][b][0];
                    Vertex* to = graph[a - fUse][b - hUse][1];
                    from->connections.push_back(to);
                    to->connections.push_back(from);
                }
            }
        }
    }

    queue<Vertex*> queue;
    graph[fifty][hundred][0]->depth = 1;
    graph[fifty][hundred][0]->count = 1;
    queue.push(graph[fifty][hundred][0]);

    while (!queue.empty()) {
        Vertex* cur = queue.front();
