            if (adj->depth == 0 || adj->depth == cur->depth + 1) {
                int sourceF = (cur->flag == 0) ? cur->f : (fifty - cur->f);
                int deltaF = abs(cur->f - adj->f);
                long long wF = C[sourceF][deltaF];

                int sourceH = (cur->flag == 0) ? cur->h : (hundred - cur->h);
                int deltaH = abs(cur->h - adj->h);
                long long wH = C[sourceH][deltaH];

                long long edgeWeight = (wF * wH) % MOD;
                adj->count = (adj->count + (cur->count * edgeWeight) % MOD) % MOD;

                if (adj->depth == 0) {
                    adj->depth = cur->depth + 1;
                    queue.push(adj);
                }
            }
        }
    }

    Vertex* end = graph[0][0][1];
    cout << (end->depth - 1) << endl;
    cout << end->count << endl;

    return 0;
}

