class InputReader {
private:
    std::istream& stream;
    std::vector<std::string> tokens;
    std::vector<std::string>::iterator tokenIter;

public:
    InputReader(std::istream& s) : stream(s) {}

    std::string nextLine() {
        std::string line;
        if (!std::getline(stream, line)) {
            throw std::runtime_error("Error reading line");
        }
        return line;
    }

    std::string next() {
        while (tokens.empty() || tokenIter == tokens.end()) {
            std::string line;
            if (!std::getline(stream, line)) {
                throw std::runtime_error("No more tokens available");
            }
            std::istringstream iss(line);
            tokens.clear();
            std::string token;
            while (iss >> token) {
                tokens.push_back(token);
            }
            tokenIter = tokens.begin();
            if (tokens.empty()) {
                throw std::runtime_error("No tokens found in input");
            }
        }
        return *tokenIter++;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long nextLong() {
        return std::stol(next());
    }

    double nextDouble() {
        return std::stod(next());
    }
};

