        String s = sc.next();

        AtomicInteger ans = new AtomicInteger(0);
        s.chars()
         .mapToObj(c -> (char) c)
         .collect(Collectors.groupingBy(
             c -> s.indexOf(c),
             LinkedHashMap::new,
             Collectors.counting()
         ));

