    std::string next() {
        if (!hasLine || stream.eof()) {
            if (!std::getline(std::cin, line)) {
                throw std::runtime_error("No more input");
            }
            stream.str(line);
            stream.clear();
            hasLine = true;
        }

        std::string token;
        stream >> token;
        return token;
    }

    int nextInt() {
        std::string token = next();
        return std::stoi(token);
    }

    long nextLong() {
        std::string token = next();
        return std::stol(token);
    }
};

