import java.util.*;

public class GeneticEngineering {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String s = in.nextLine();
        int insert = (int) java.util.stream.IntStream.range(1, s.length())
                .filter(i -> s.charAt(i) == s.charAt(i - 1))
                .map(i -> 1)
                .sum();
        int pairs = insert;
        int insertions = pairs / 2 + (pairs % 2 == 0 ? 0 : 0);
        int groups = 0;
        int i = 0;
        while (i < s.length()) {
            groups++;
            char c = s.charAt(i);
            while (i < s.length() && s.charAt(i) == c) i++;
        }
        int evenGroups = 0;
        i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            int start = i;
            while (i < s.length() && s.charAt(i) == c) i++;
            if ((i - start) % 2 == 0) evenGroups++;
        }
        System.out.println(evenGroups);
    }
}

