}

long long modPow(long long a, long long x, long long p) {
    long long res = 1;
    while (x > 0) {
        if (x % 2 != 0) {
            res = (res * a) % p;
        }
        a = (a * a) % p;
        x /= 2;
    }
    return res;
}

