#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
#include <string>
#include <sstream>

using namespace std;

class InputReader {
public:
    istream& reader;
    string buffer;
    size_t pos;

    InputReader(istream& stream) : reader(stream), pos(0) {}

    string next() {
        while (true) {
            if (pos >= buffer.size()) {
                if (!getline(reader, buffer)) {
                    throw runtime_error("No more input");
                }
                pos = 0;
            }
            while (pos < buffer.size() && isspace(buffer[pos])) {
                pos++;
            }
            if (pos >= buffer.size()) continue;
            size_t start = pos;
            while (pos < buffer.size() && !isspace(buffer[pos])) {
                pos++;
            }
            return buffer.substr(start, pos - start);
        }
    }

    int nextInt() {
        return stoi(next());
    }
};

class ERockPaperScissors {
public:
    int min_val;

    void check(vector<vector<int>>& aa, vector<int> a, vector<int> b) {
        for (int i = 0; i < aa.size(); i++) {
            int m = min(a[aa[i][0]], b[aa[i][1]]);
            b[aa[i][1]] -= m;
            a[aa[i][0]] -= m;
        }
        int curr = 0;
        for (int i = 0; i < 3; i++) curr += a[i];
        min_val = min(min_val, curr);
    }

    void per(vector<vector<int>>& aa, int index, vector<int> a, vector<int> b) {
        check(aa, a, b);
        for (int i = index; i < aa.size(); i++) {
            swap(aa[i], aa[index]);
            per(aa, index + 1, a, b);
            swap(aa[i], aa[index]);
        }
    }

    void solve(int testNumber, InputReader& in, ostream& out) {
        int n = in.nextInt();
        vector<int> a(3);
        vector<int> b(3);
        min_val = INT_MAX;
        int max_val = 0;
        for (int i = 0; i < 3; i++) {
            a[i] = in.nextInt();
        }
        for (int i = 0; i < 3; i++) {
            b[i] = in.nextInt();
        }
        max_val = min(a[0], b[1]) + min(a[1], b[2]) + min(a[2], b[0]);
        vector<vector<int>> aa;
        aa.push_back({0, 0});
        aa.push_back({1, 1});
        aa.push_back({2, 2});
        aa.push_back({0, 2});
        aa.push_back({1, 0});
        aa.push_back({2, 1});
        per(aa, 0, a, b);
        out << min_val << " " << max_val << endl;
    }
};

int main() {
    InputReader in(cin);
    ERockPaperScissors solver;
    solver.solve(1, in, cout);
    return 0;
}

