        return hasMoreBytes() ? static_cast<unsigned char>(buffer[ptr++]) : -1; 
    }

    bool isSpaceChar(int c) { 
        return c <= 32 || c == 127; 
    }

    bool isPrintableChar(int c) { 
        return c >= 33 && c <= 126; 
    }

public:
    Scanner(std::istream& stream) : in(stream) {}

    bool hasNext() {
        while (hasMoreBytes() && !isPrintableChar(buffer[ptr])) ptr++;
        return hasMoreBytes();
    }

    std::string next() {
        if (!hasNext()) throw std::runtime_error("No more elements");
        std::string sb;
        int c = readByte();
        while (isPrintableChar(c)) {
            sb += static_cast<char>(c);
            c = readByte();
        }
        return sb;
    }

    long long nextLong() {
        if (!hasNext()) throw std::runtime_error("No more elements");
        long long value = 0;
        bool negative = false;
        int c = readByte();
        if (c == '-') { negative = true; c = readByte(); }
        if (c < '0' || c > '9') throw std::runtime_error("Number format error");
        while (true) {
            if (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
            } else if (c == -1 || !isPrintableChar(c) || c == ':') {
                return negative ? -value : value;
            } else {
                throw std::runtime_error("Number format error");
            }
            c = readByte();
        }
    }

    int nextInt() {
        long long val = nextLong();
        if (val < INT_MIN || val > INT_MAX) throw std::runtime_error("Number format error");
        return static_cast<int>(val);
    }
};

void solve() {
    Scanner SCANNER(std::cin);
    long long n = SCANNER.nextLong();
    std::vector<long long> A(3);
    std::vector<long long> B(3);
    for (int i = 0; i < 3; ++i) A[i] = SCANNER.nextLong();
    for (int i = 0; i < 3; ++i) B[i] = SCANNER.nextLong();

    long long winCount = 0;
    long long nonWinCount = 0;

    for (int idx = 0; idx < 3; ++idx) {
        winCount += std::min(A[idx], B[(idx + 1) % 3]);
        long long possibleDefeat = std::min(B[idx], A[(idx + 1) % 3]);
        long long possibleTie = std::min(B[idx], A[idx]);
        nonWinCount += std::min(B[idx], possibleDefeat + possibleTie);
    }

    std::cout << (n - nonWinCount) << " " << winCount << "\n";
}

int main() {
    solve();
    return 0;
}

