class Reader {
private:
    static const int BUFFER_SIZE = 1 << 16;
    FILE* file;
    char buffer[BUFFER_SIZE];
    int bufferPointer, bytesRead;

public:
    Reader() {
        file = stdin;
        bufferPointer = bytesRead = 0;
    }

    Reader(const string& fileName) {
        file = fopen(fileName.c_str(), "r");
        bufferPointer = bytesRead = 0;
    }

    ~Reader() {
        if (file != stdin) fclose(file);
    }

    char readChar() {
        if (bufferPointer == bytesRead) {
            bytesRead = fread(buffer, 1, BUFFER_SIZE, file);
            bufferPointer = 0;
            if (bytesRead == 0) return -1;
        }
        return buffer[bufferPointer++];
    }

    int nextInt() {
        int ret = 0;
        char c = readChar();
        while (c <= ' ') c = readChar();
        bool neg = (c == '-');
        if (neg) c = readChar();
        do {
            ret = ret * 10 + c - '0';
        } while ((c = readChar()) >= '0' && c <= '9');
        if (neg) return -ret;
        return ret;
    }

    long long nextLong() {
        long long ret = 0;
        char c = readChar();
        while (c <= ' ') c = readChar();
        bool neg = (c == '-');
        if (neg) c = readChar();
        do {
            ret = ret * 10 + c - '0';
        } while ((c = readChar()) >= '0' && c <= '9');
        if (neg) return -ret;
        return ret;
    }

    double nextDouble() {
        double ret = 0, div = 1;
        char c = readChar();
        while (c <= ' ') c = readChar();
        bool neg = (c == '-');
        if (neg) c = readChar();
        do {
            ret = ret * 10 + c - '0';
        } while ((c = readChar()) >= '0' && c <= '9');
        if (c == '.') {
            while ((c = readChar()) >= '0' && c <= '9') {
                ret += (c - '0') / (div *= 10);
            }
        }
        if (neg) return -ret;
        return ret;
    }

    string readLine() {
        string line;
        char c;
        while ((c = readChar()) != -1 && c != '\n') {
            line += c;
        }
        return line;
    }
};

class Print {
private:
    FILE* file;

public:
    Print() {
        file = stdout;
    }

    ~Print() {
        // Don't close stdout
    }

    void print(const string& str) {
        fputs(str.c_str(), file);
    }

    void printLine(const string& str) {
        print(str);
        print("\n");
    }

    void flush() {
        fflush(file);
    }
};

