public class A {
    private static List<Long> exponentials;
    private static List<Long> combinationSums;

    private static void produceCombinations(int position, long accumulated) {
        if (position == exponentials.size()) {
            combinationSums.add(accumulated);
            return;
        }
        produceCombinations(position + 1, accumulated + exponentials.get(position));
        produceCombinations(position + 1, accumulated);
    }

    private static boolean fulfillsRequirement(long M, long W, long testValue) {
        if (testValue == M) return true;
        long x = testValue + M;
        while (x > 0) {
            if (x % W > 1) return false;
            x /= W;
        }
        return true;
    }

