            System.out.println("YES");
            return;
        }

        exponentials = new ArrayList<>();
        exponentials.add(1L);
        exponentials.add(W);
        long power = W;
        long maxLimit = (long)1e10;

        while (true) {
            power *= W;
            if (power <= 0 || power > maxLimit) break;
            exponentials.add(power);
        }

        combinationSums = new ArrayList<>();
        produceCombinations(0, 0L);

        boolean solutionFound = false;
        for (long val : combinationSums) {
            if (fulfillsRequirement(M, W, val)) {
                solutionFound = true;
                break;
            }
        }

        System.out.println(solutionFound ? "YES" : "NO");
    }
}

