int main() {
    int w, m;
    std::cin >> w >> m;

    // Convert m to base w
    int r = m;
    int e = 0;
    if (r > 0) {
        e = static_cast<int>(std::log(r) / std::log(w));
    }
    int l = e;
    std::vector<int> digits(l + 2, 0);

    int temp_e = e;
    while (temp_e >= 0) {
        double power = std::pow(w, temp_e);
        if (r - static_cast<int>(power) >= 0) {
            digits[temp_e] = (static_cast<int>(r / power)) % w;
        }
        temp_e--;
    }

    // Process digits
    for (int i = 0; i < l + 1; i++) {
        if (digits[i] >= w) {
            digits[i] %= w;
            digits[i + 1]++;
        }
        if (!(digits[i] == 0 || digits[i] == 1)) {
            digits[i]++;
        }
        if (digits[i] >= w) {
            digits[i] %= w;
            digits[i + 1]++;
        }
    }

    // Check if all digits are 0 or 1
