    public void solve() {
        int w = in.nextInt();
        int m = in.nextInt();

        while (m != 0){
            if (m % w == 0 || m % w == 1){
                m /= w;
            }else if (m % w == w - 1){
                m = (m + 1) / w;
            }
            else{
                out.println("NO");
                return;
            }
        }
        out.println("YES");
    }

    private InputReader in;
    private PrintWriter out;

    Task(InputReader in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }
}

