public class CF552C{ 
  public static int k, w;
  public static HashSet<Long> set;
  public static void main(String[] args)throws Exception {
    InputReader in = new InputReader(System.in);
    PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));

    w = in.nextInt();
    long n = in.nextLong();

    k = 0;
    for(int i = 0; w > 2 && i < 21; i++){
      k = i;
      if(Math.pow(w, i) > 1e9){
        break;
      }
    }

    set = new HashSet<Long>();
    if(w > 2) solve(0, 0);

    boolean bol = false;
    if(w == 2) bol = true;

    for(long i : set){
      if(i >= n && set.contains(i-n)){
        bol = true;
        break;
      }
    }

    if(bol) pw.println("YES");
    else pw.println("NO");

    pw.close();
  }

  static void solve(int i, long sum){
    if(i > k){
      set.add(sum);
