#include <sstream>
#include <stdexcept>

class FastReader {
private:
    std::istream& reader;
    std::string buffer;
    size_t pos;

public:
    FastReader(std::istream& inputStream) : reader(inputStream), pos(0) {}

    std::string next() {
        while (true) {
            if (buffer.empty() || pos >= buffer.size()) {
                if (!std::getline(reader, buffer)) {
                    throw std::runtime_error("No more input");
                }
                pos = 0;
            }
            while (pos < buffer.size() && std::isspace(buffer[pos])) {
                ++pos;
            }
            if (pos >= buffer.size()) {
                buffer.clear();
                continue;
            }
            size_t start = pos;
            while (pos < buffer.size() && !std::isspace(buffer[pos])) {
                ++pos;
            }
            return buffer.substr(start, pos - start);
        }
    }

    std::string nextLine() {
        std::string line;
        if (!std::getline(reader, line)) {
            throw std::runtime_error("No more input");
        }
        return line;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long nextLong() {
        return std::stol(next());
    }
};

