    while (m > 0) {
        int mod = m % w;
        if (mod == 0) {
            m /= w;
        } else if (mod == 1) {
            m -= 1;
            m /= w;
        } else if (mod == w - 1) {
            m += 1;
            m /= w;
        } else {
            res = false;
            break;
        }
    }
    std::cout << (res ? "YES" : "NO") << std::endl;

    return 0;
}

