		int w = in.nextInt();
		int m = in.nextInt();
		in.close();

		List<Integer> digits = new ArrayList<>();

		int current = m;
		while (current > 0) {
			digits.add(current % w);
			current /= w;
		}

		for (int i = 0; i < digits.size(); i++) {
			int digit = digits.get(i);
			if (digit == 0 || digit == 1 || digit == -1) continue;
			else if (digit == w - 1) {
				digits.set(i, digit - w);
				if (i + 1 >= digits.size()) {
					digits.add(1);
				} else {
					digits.set(i + 1, digits.get(i + 1) + 1);
				}
			} else if (digit == w) {
				digits.set(i, 0);
				if (i + 1 >= digits.size()) {
					digits.add(1);
				} else {
					digits.set(i + 1, digits.get(i + 1) + 1);
				}
			} else {
				System.out.println("NO");
				return;
			}
		}

		System.out.println("YES");
	}
}

