    if (m == 0) return true;
    if (m == 1) return true;
    if (w == 1) return m >= 0;
    if (w == 0) return m == 0;

    int r = ((m % w) + w) % w; // floorMod equivalent
    if (r == 0) {
        return canBalance(w, m / w);
    } else if (r == 1) {
        return canBalance(w, (m - 1) / w);
    } else if (r == w - 1) {
        return canBalance(w, (m + 1) / w);
    }
    return false;
}

