            return false;
        }

        if (current + cumulative[level] < target) {
            return tryCombinations(current + nextPower, target, level - 1, powers, cumulative);
        } else if (current - cumulative[level] > target) {
            return tryCombinations(current - nextPower, target, level - 1, powers, cumulative);
        } else {
            return tryCombinations(current, target, level - 1, powers, cumulative);
        }
    }
};

