class FasterScanner {
private:
    std::vector<char> buf;
    int curChar;
    int numChars;

public:
    FasterScanner() : buf(1024), curChar(0), numChars(0) {}

    int read() {
        if (numChars == -1)
            throw std::runtime_error("Input mismatch exception");
        if (curChar >= numChars) {
            curChar = 0;
            numChars = std::cin.rdbuf()->sgetn(buf.data(), buf.size());
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    bool isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    bool isEndOfLine(int c) {
        return c == '\n' || c == '\r' || c == -1;
    }

    std::string nextLine() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        std::string res;
        do {
            res += static_cast<char>(c);
            c = read();
        } while (!isEndOfLine(c));
        return res;
    }

    std::string nextString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        std::string res;
        do {
            res += static_cast<char>(c);
            c = read();
        } while (!isSpaceChar(c));
        return res;
    }

    long long nextLong() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long long res = 0;
        do {
            if (c < '0' || c > '9')
                throw std::runtime_error("Input mismatch exception");
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    int nextInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw std::runtime_error("Input mismatch exception");
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    std::vector<int> nextIntArray(int n) {
        std::vector<int> arr(n);
        for (int i = 0; i < n; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    std::vector<long long> nextLongArray(int n) {
        std::vector<long long> arr(n);
        for (int i = 0; i < n; i++) {
            arr[i] = nextLong();
        }
        return arr;
    }
};

int main() {
    FasterScanner sc;

    int W = sc.nextInt();
    int M = sc.nextInt();

    std::vector<int> B(101, 0);
    int tmp = M;
    for (int i = 0; i < 100; i++) {
        B[i] = tmp % W;
        tmp /= W;
    }

    for (int i = 0; i < 100; i++) {
        if (B[i] > 1) {
            B[i] -= W;
            B[i + 1]++;
        }
    }

    for (int i = 0; i <= 100; i++) {
        if (B[i] < -1 || B[i] > 1) {
            std::cout << "NO" << std::endl;
            return 0;
        }
    }
    std::cout << "YES" << std::endl;

    return 0;
}

