using namespace std;

class FastReader {
public:
    string line;
    int pos;

    FastReader() : pos(0) {}

    string next() {
        while (true) {
            if (pos >= line.size()) {
                if (!getline(cin, line)) {
                    return "";
                }
                pos = 0;
            }

            // Skip whitespace
            while (pos < line.size() && line[pos] == ' ') {
                pos++;
            }

            if (pos >= line.size()) continue;

            // Find next token
            int start = pos;
            while (pos < line.size() && line[pos] != ' ') {
                pos++;
            }
            return line.substr(start, pos - start);
        }
    }

    int nextInt() {
