            if (all.get(i) == 0 || all.get(i) == 1)
                continue;
            if (all.get(i) == w - 1) {
                int j = i + 1;
                while (j < all.size()) {
                    if (all.get(j) == w - 1) {
                        all.set(j, 0);
                    } else {
                        all.set(j, all.get(j) + 1);
                        break;
                    }
                    ++j;
                }
                continue;
            }
            ok = false;
            break;
        }

        if (ok)
            System.out.println("YES");
        else
            System.out.println("NO");
    }
}

