        } else if (k == 0) {
            cout << factorial[n] << endl;
        } else {
            long long comb = nCr((int)n, (int)(n - k));
            long long solveResult = compute((int)n, (int)k);
            cout << 2 * comb % MOD * solveResult % MOD << endl;
        }
    }
