        fact[i] = (int)((long long)fact[i - 1] * i % mod);
    }

    // Compute modular inverse of fact[n] using Fermat's little theorem
    invFact[n] = pow_mod(fact[n], mod - 2, mod);

    for (int i = n; i > 0; i--) {
        invFact[i - 1] = (int)((long long)invFact[i] * i % mod);
    }

    return {fact, invFact};
}

