#include <algorithm>

using namespace std;

class Mod998;

class Modulo {
protected:
    vector<long long> facts;
    vector<long long> invFacts;

public:
    Modulo() {
        facts.push_back(1LL);
        invFacts.push_back(1LL);
    }

    virtual long long modulus() = 0;

    long long fact(int n) {
        while (facts.size() <= n) {
            facts.push_back(mult(facts[facts.size() - 1], (long long)facts.size()));
        }
        return facts[n];
    }

    long long invFact(int n) {
        int last = invFacts.size() - 1;
        if (last < n) {
            vector<long long> buf(n - last);
            buf[0] = inv(fact(n));
            for (int i = 1; i < buf.size(); i++) {
                buf[i] = mult(buf[i - 1], n - i + 1);
            }
            for (int i = buf.size() - 1; i >= 0; i--) {
                invFacts.push_back(buf[i]);
            }
        }
        return invFacts[n];
    }

    long long paritySign(long long k) {
        return (k % 2 == 0) ? 1 : modulus() - 1;
    }

    long long ncr(int n, int r) {
        if (r < 0 || n < r) return 0;
        return mult(fact(n), mult(invFact(r), invFact(n - r)));
    }

    long long normalize(long long x) {
        x %= modulus();
        return x < 0 ? x + modulus() : x;
    }

    long long add(long long a, long long b) {
        long long s = a + b;
        return s >= modulus() ? s - modulus() : s;
    }

    long long mult(long long a, long long b) {
        return (a * b) % modulus();
    }

    long long mult(long long a, long long b, long long c) {
        return mult(mult(a, b), c);
    }

    long long pow(long long base, int exp) {
        long long res = 1;
        base = normalize(base);
        while (exp > 0) {
            if ((exp & 1) == 1) res = mult(res, base);
            base = mult(base, base);
            exp >>= 1;
        }
        return res;
    }

    long long inv(long long x) {
        long long m = modulus(), a = x, b = m;
        long long u = 1, v = 0;
        while (b != 0) {
            long long q = a / b;
            long long r = a % b;
            a = b; b = r;
            long long t = u - q * v; u = v; v = t;
        }
        return normalize(u);
    }
};

class Mod998 : public Modulo {
public:
    long long modulus() override { return 998244353LL; }
};

class Solver {
public:
    Mod998 mod;

    void process(int testNum, int n, long long k, ostream& out) {
        if (k == 0) {
            out << mod.fact(n) << endl;
            return;
        }

        if (k > n - 1) {
            out << 0 << endl;
            return;
        }

        int c = n - (int)k;
        long long sum = 0;

        for (int i = 1; i <= c; i++) {
            long long sign = mod.paritySign(c - i);
            long long comb = mod.ncr(c, i);
            long long pow_val = mod.pow(i, n);
            long long term = mod.mult(sign, comb, pow_val);
            sum = mod.add(sum, term);
        }

        long long multiplier = mod.mult(2, mod.ncr(n, c));
        long long result = mod.mult(sum, multiplier);
        out << result << endl;
    }
};

class InputReader {
private:
    istream& reader;
    string buffer;
    size_t pos;

public:
    InputReader(istream& stream) : reader(stream), pos(0) {}

    string next() {
        while (true) {
            if (pos >= buffer.size()) {
                if (!getline(reader, buffer)) {
                    throw runtime_error("End of input");
                }
                pos = 0;
            }

            while (pos < buffer.size() && isspace(buffer[pos])) {
                pos++;
            }

            if (pos >= buffer.size()) continue;

            size_t start = pos;
            while (pos < buffer.size() && !isspace(buffer[pos])) {
                pos++;
            }
            return buffer.substr(start, pos - start);
        }
    }

