public class E {
    private static final int INF = 1_000_000_000;

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        if (n > m) {
            int x = n;
            n = m;
            m = x;
        }

        int N = 1 << n;
        int[][][] dp = new int[2][N][N];
        int cur = 0, nxt = 1;

        for (int i = 0; i < N; i++) Arrays.fill(dp[cur][i], INF);
        Arrays.fill(dp[cur][0], 0);

        for (int col = 0; col < m; col++) {
            for (int i = 0; i < N; i++) Arrays.fill(dp[nxt][i], INF);

            int limit = (col == m - 1) ? 1 : N;

            for (int a = 0; a < N; a++) {
                for (int b = 0; b < N; b++) {
                    if (dp[cur][a][b] == INF) continue;

                    for (int c = 0; c < limit; c++) {
                        int covered = 0;
                        for (int r = 0; r < n; r++) {
                            if ((b & (1 << r)) == 0) {
                                boolean ok = false;
                                if (r > 0 && (b & (1 << (r - 1))) != 0) ok = true;
                                if (r < n - 1 && (b & (1 << (r + 1))) != 0) ok = true;
                                if ((a & (1 << r)) != 0) ok = true;
                                if ((c & (1 << r)) != 0) ok = true;
                                if (ok) covered |= (1 << r);
                            }
                        }
                        int uncovered = n - Integer.bitCount(covered);
                        dp[nxt][b][c] = Math.min(dp[nxt][b][c], dp[cur][a][b] + uncovered);
                    }
                }
            }

            int tmp = cur;
            cur = nxt;
            nxt = tmp;
        }

        int ans = INF;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                ans = Math.min(ans, dp[cur][i][j]);
            }
        }

        System.out.println(n * m - ans);
    }
}

