import java.util.*;
import java.io.*;

public class cf111c {
    private static int n, m, maxm;
    private static int[][][] dp;
    private static int[] s;

    private static int countBits(int x) {
        int cnt = 0;
        while (x != 0) {
            cnt++;
            x &= (x - 1);
        }
        return cnt;
    }

    private static boolean isValid(int prev, int curr, int next) {
        int covered = (maxm - 1) & (curr | (curr << 1) | (curr >> 1) | prev | next);
        return covered == (maxm - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        if (n < m) {
            int temp = n;
            n = m;
            m = temp;
        }

        maxm = 1 << m;
        dp = new int[n + 1][maxm][maxm];
        s = new int[maxm];

        for (int row = 0; row <= n; row++) {
            for (int mask1 = 0; mask1 < maxm; mask1++) {
                Arrays.fill(dp[row][mask1], 100);
            }
        }

        for (int mask = 0; mask < maxm; mask++) {
            s[mask] = countBits(mask);
            dp[0][0][mask] = 0;
        }

        for (int row = 1; row <= n; row++) {
            for (int curMask = 0; curMask < maxm; curMask++) {
                for (int prevMask = 0; prevMask < maxm; prevMask++) {
                    for (int prevPrevMask = 0; prevPrevMask < maxm; prevPrevMask++) {
                        if (dp[row - 1][prevPrevMask][prevMask] != 100 && 
                            isValid(prevPrevMask, prevMask, curMask)) {
                            dp[row][prevMask][curMask] = Math.min(
                                dp[row][prevMask][curMask],
                                dp[row - 1][prevPrevMask][prevMask] + s[prevMask]
                            );
                        }
                    }
                }
            }
        }

        int minRemoved = 100;
        for (int lastMask = 0; lastMask < maxm; lastMask++) {
            minRemoved = Math.min(minRemoved, dp[n][lastMask][0]);
        }

        System.out.println(n * m - minRemoved);
    }
}

