        private int ptr = 0;
        private int len = 0;
        private SpaceCharFilter validator;

        public InputReader(InputStream stream) {
            in = stream;
        }

        private int nextByte() {
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

