            int c = nextByte();
            while (isSpace(c)) c = nextByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextByte();
            }
            int result = 0;
            while (!isSpace(c)) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                result = result * 10 + (c - '0');
                c = nextByte();
            }
            return result * sign;
        }

        private boolean isSpace(int c) {
            if (validator != null) return validator.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

