private:
    static const int BAD = 11111;
    int rows;
    int cols;
    std::vector<std::unordered_map<IntIntPair, int>> dpMemo;

    bool isBitSet(int state, int pos) {
        if (pos < 0) return false;
        return ((state >> pos) & 1) == 1;
    }

    int setBit(int state, int pos) {
        if (!isBitSet(state, pos)) {
            state |= (1 << pos);
        }
        return state;
    }

    int popCount(int state) {
        int count = 0;
        while (state != 0) {
            count += state & 1;
            state >>= 1;
        }
        return count;
    }

    void sanityCheck() {
        if (!isBitSet(5, 0)) throw std::runtime_error("Sanity check failed");
        if (isBitSet(5, 1)) throw std::runtime_error("Sanity check failed");
        if (isBitSet(5, -1)) throw std::runtime_error("Sanity check failed");
        if (!isBitSet(5, 2)) throw std::runtime_error("Sanity check failed");
        if (!isBitSet(5, 3)) throw std::runtime_error("Sanity check failed");
        if (setBit(0, 2) != 4) throw std::runtime_error("Sanity check failed");
        if (setBit(4, 0) != 5) throw std::runtime_error("Sanity check failed");
        if (setBit(5, 0) != 5) throw std::runtime_error("Sanity check failed");
        if (popCount(5) != 2) throw std::runtime_error("Sanity check failed");
    }

    int computeDP(int level, int needed, int prevPattern) {
        if (level == rows) {
            return (needed == 0) ? 0 : BAD;
        }
        IntIntPair pair(needed, prevPattern);
        if (dpMemo[level].find(pair) != dpMemo[level].end()) {
            return dpMemo[level][pair];
        }
        int best = BAD;
        int maxConfigs = 1 << cols;
        for (int cfg = 0; cfg < maxConfigs; cfg++) {
            int current = 0;
            for (int j = 0; j < cols; j++) {
                if (((cfg >> j) & 1) == 1) {
                    current |= (1 << j);
                }
            }
            bool ok = true;
            for (int k = 0; k < cols; k++) {
                if (((needed >> k) & 1) == 1 && (((current >> k) & 1) == 0)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                int future = 0;
                for (int j = 0; j < cols; j++) {
                    if (!isBitSet(current, j - 1) && !isBitSet(current, j) &&
                        !isBitSet(current, j + 1) && !isBitSet(prevPattern, j)) {
                        future |= (1 << j);
                    }
                }
                int temp = popCount(current) + computeDP(level + 1, future, current);
                if (temp < best) {
                    best = temp;
                }
            }
        }
        dpMemo[level][pair] = best;
        return best;
    }

public:
    void solve(int testNum, int n, int m) {
        sanityCheck();
        cols = std::min(n, m);
        rows = std::max(n, m);
        dpMemo.resize(rows);
