using namespace std;

double d2(double ax, double ay, double bx, double by) {
    return (bx - ax) * (bx - ax) + (by - ay) * (by - ay);
}

long long d2(long long ax, long long ay, long long bx, long long by) {
    return (bx - ax) * (bx - ax) + (by - ay) * (by - ay);
}

const double EPS = 1E-10;

vector<double> crossSimple(long long x, long long y, long long r, long long tx, long long ty, long long tr) {
    long long d2_val = d2(x, y, tx, ty);
    if (d2_val < (r - tr) * (r - tr)) return {};
    if (d2_val > (r + tr) * (r + tr)) return {};

    double base = atan2(static_cast<double>(ty - y), static_cast<double>(tx - x));
    double wing = acos((static_cast<double>(d2_val) + static_cast<double>(r) * r - static_cast<double>(tr) * tr) / 
                       (2 * sqrt(static_cast<double>(d2_val)) * r));

    double inf = base - wing;
    double sup = base + wing;

    return {inf, sup};
}

