using namespace std;

const int INF = (int)1e9;

class InputReader {
public:
    istream& reader;
    string buffer;
    size_t pos;

    InputReader(istream& stream) : reader(stream), pos(0) {}

    string next() {
        while (true) {
            if (buffer.empty() || pos >= buffer.size()) {
                if (!getline(reader, buffer)) {
                    throw runtime_error("No more input");
                }
                pos = 0;
            }
            while (pos < buffer.size() && isspace(buffer[pos])) {
                pos++;
            }
            if (pos >= buffer.size()) {
                buffer.clear();
                continue;
            }
            size_t start = pos;
            while (pos < buffer.size() && !isspace(buffer[pos])) {
                pos++;
            }
            return buffer.substr(start, pos - start);
        }
    }

    int nextInt() {
        return stoi(next());
    }
};

class TaskC {
public:
    void solve(int testNumber, InputReader& in, ostream& out) {
        int n = in.nextInt();
        string s = in.next();
        int nk = 0, nv = 0, no = 0;
        vector<int> kpos(n), vpos(n), opos(n);
        vector<int> snk(n + 1, 0), snv(n + 1, 0), sno(n + 1, 0);

        for (int i = 0; i < n; ++i) {
            char ch = s[i];
            if (ch == 'V') {
                vpos[nv++] = i;
            } else if (ch == 'K') {
                kpos[nk++] = i;
            } else {
                opos[no++] = i;
            }
            snk[i + 1] = nk;
            snv[i + 1] = nv;
            sno[i + 1] = no;
        }

        vector<vector<vector<vector<int>>>> best(2, 
            vector<vector<vector<int>>>(nk + 1, 
                vector<vector<int>>(nv + 1, 
                    vector<int>(no + 1, INF))));

        best[0][0][0][0] = 0;

        for (int k = 0; k <= nk; ++k) {
            for (int v = 0; v <= nv; ++v) {
                for (int o = 0; o <= no; ++o) {
                    for (int hv = 0; hv < 2; ++hv) {
                        int cur = best[hv][k][v][o];
                        if (cur == INF) continue;

                        if (k < nk && hv == 0) {
                            int cost = max(snv[kpos[k]] - v, 0) + max(sno[kpos[k]] - o, 0);
                            best[0][k + 1][v][o] = min(best[0][k + 1][v][o], cur + cost);
