#include <cstring>

using namespace std;

const string FORBIDDEN = "VK";
const int INF = 1000000;

class C {
public:
    string filterString(const string& input) {
        string result;
        for (char ch : input) {
            if (FORBIDDEN.find(ch) != string::npos) {
                result += ch;
            } else {
                result += 'A';
            }
        }
        return result;
    }

    int computeAnswer(const string& s) {
        string filtered = filterString(s);
        int n = filtered.length();

        vector<int> charType(n);
        vector<vector<int>> positions(3, vector<int>(n, 0));
        vector<int> counts(3, 0);

        vector<vector<vector<int>>> prefixCounts(3, vector<vector<int>>(n, vector<int>(3, 0)));
        vector<vector<int>> prefixSum(n + 1, vector<int>(3, 0));

        prefixSum[0] = {0, 0, 0};

        for (int i = 0; i < n; i++) {
            charType[i] = "VKA".find(filtered[i]);
            int type = charType[i];
            for (int j = 0; j < 3; j++) {
                prefixCounts[type][counts[type]][j] = prefixSum[i][j];
            }
            positions[type][counts[type]++] = i;

            prefixSum[i + 1] = prefixSum[i];
            prefixSum[i + 1][type]++;
        }

        vector<vector<vector<vector<int>>>> memo(2, vector<vector<vector<int>>>(counts[0] + 1, vector<vector<int>>(counts[1] + 1, vector<int>(counts[2] + 1, INF))));

        memo[0][0][0][0] = 0;
        int result = INF;

        for (int a = 0; a <= counts[0]; a++) {
            for (int b = 0; b <= counts[1]; b++) {
                for (int c = 0; c <= counts[2]; c++) {
                    for (int prev = 0; prev < 2; prev++) {
                        int idx = a + b + c;
                        int currentCost = memo[prev][a][b][c];
                        if (currentCost == INF) {
                            continue;
                        }

                        if (idx == n) {
                            result = min(result, currentCost);
                            continue;
                        }

                        if (a < counts[0]) {
                            int cost = max(0, b - prefixCounts[0][a][1]) + max(0, c - prefixCounts[0][a][2]);
                            memo[1][a + 1][b][c] = min(memo[1][a + 1][b][c], currentCost + cost);
                        }

                        if (b < counts[1] && prev == 0) {
                            int cost = max(0, a - prefixCounts[1][b][0]) + max(0, c - prefixCounts[1][b][2]);
                            memo[0][a][b + 1][c] = min(memo[0][a][b + 1][c], currentCost + cost);
                        }

                        if (c < counts[2]) {
                            int cost = max(0, a - prefixCounts[2][c][0]) + max(0, b - prefixCounts[2][c][1]);
                            memo[0][a][b][c + 1] = min(memo[0][a][b][c + 1], currentCost + cost);
                        }
                    }
                }
            }
        }

        return result;
    }

    void solve() {
        string s;
        cin >> s;
        cout << computeAnswer(s) << endl;
    }
};

