        }
        return result;
    }

    int optimize(const string& s) {
        string processed = preprocess(s);
        int n = processed.length();

        vector<int> charIdx(n);
        vector<vector<int>> positions(3, vector<int>(n, 0));
        vector<int> sizes(3, 0);

        vector<vector<vector<int>>> lookups(3, vector<vector<int>>(n, vector<int>(3, 0)));
        vector<vector<int>> prefix(n + 1, vector<int>(3, 0));

        prefix[0] = {0, 0, 0};

        for (int i = 0; i < n; i++) {
            charIdx[i] = string("VKA").find(processed[i]);
            int idx = charIdx[i];
            for (int j = 0; j < 3; j++) {
                lookups[idx][sizes[idx]][j] = prefix[i][j];
            }
            positions[idx][sizes[idx]++] = i;

            prefix[i + 1] = prefix[i];
            prefix[i + 1][idx]++;
        }

        vector<vector<vector<vector<int>>>> dp(2, vector<vector<vector<int>>>(sizes[0] + 1, vector<vector<int>>(sizes[1] + 1, vector<int>(sizes[2] + 1, 1000000))));

        int minSteps = 1000000;

        dp[0][0][0][0] = 0;
        for (int a = 0; a <= sizes[0]; a++) {
            for (int b = 0; b <= sizes[1]; b++) {
                for (int c = 0; c <= sizes[2]; c++) {
                    for (int prev = 0; prev < 2; prev++) {
                        int curPos = a + b + c;
                        int curCost = dp[prev][a][b][c];
                        if (curCost == 1000000) {
                            continue;
                        }

                        if (curPos == n) {
                            minSteps = min(minSteps, curCost);
                            continue;
                        }

                        if (a < sizes[0]) {
                            int cost = max(b - lookups[0][a][1], 0) + max(c - lookups[0][a][2], 0);
                            dp[1][a + 1][b][c] = min(dp[1][a + 1][b][c], curCost + cost);
