                            dp[0][a][b + 1][c] = min(dp[0][a][b + 1][c], curCost + cost);
                        }

                        if (c < sizes[2]) {
                            int cost = max(a - lookups[2][c][0], 0) + max(b - lookups[2][c][1], 0);
                            dp[0][a][b][c + 1] = min(dp[0][a][b][c + 1], curCost + cost);
                        }
                    }
                }
            }
