        vector<vector<int>> indices(3, vector<int>(n, 0));
        vector<int> lengths(3, 0);

        vector<vector<vector<int>>> table(3, vector<vector<int>>(n, vector<int>(3, 0)));
        vector<vector<int>> prefix(n + 1, vector<int>(3, 0));

