            vector<vector<int>>(lengths[1] + 1, vector<int>(lengths[2] + 1, BOUND))));

        int optimal = BOUND;

        memo[0][0][0][0] = 0;
        for (int a = 0; a <= lengths[0]; a++) {
            for (int b = 0; b <= lengths[1]; b++) {
                for (int c = 0; c <= lengths[2]; c++) {
