using namespace std;

class InputReader {
public:
    istream& reader;
    string line;
    int pos;
    vector<string> tokens;

    InputReader(istream& stream) : reader(stream), pos(0) {}

    string next() {
        while (tokens.empty() || pos >= tokens.size()) {
            if (!getline(reader, line)) {
                throw runtime_error("No more input");
            }
            tokens.clear();
            istringstream iss(line);
            string token;
            while (iss >> token) {
                tokens.push_back(token);
            }
            pos = 0;
        }
        return tokens[pos++];
    }

    int nextInt() {
        return stoi(next());
    }
};

class TaskC {
public:
    void solve(int testNumber, InputReader& in, ostream& out) {
        int n = in.nextInt();
        string s = in.next();
        vector<int> c(3, 0);
        vector<vector<int>> pos(3, vector<int>(n, 0));

        for (int i = 0; i < n; ++i) {
            int x;
            if (s[i] == 'K') x = 0;
            else if (s[i] == 'V') x = 1;
            else x = 2;
            pos[x][c[x]++] = i;
        }

        vector<vector<vector<vector<int>>>> dp(2, vector<vector<vector<int>>>(c[0] + 1, vector<vector<int>>(c[1] + 1, vector<int>(c[2] + 1, INT_MAX / 2))));
        dp[0][0][0][0] = 0;

        for (int i0 = 0; i0 <= c[0]; ++i0) {
            for (int i1 = 0; i1 <= c[1]; ++i1) {
                for (int i2 = 0; i2 <= c[2]; ++i2) {
                    for (int isLast1 = 0; isLast1 < 2; ++isLast1) {
                        int cur = dp[isLast1][i0][i1][i2];

                        if (i0 < c[0] && isLast1 == 0) {
                            int swaps = 0, pos0 = pos[0][i0];
                            for (int i = i1; i < c[1] && pos[1][i] < pos0; ++i) swaps++;
                            for (int i = i2; i < c[2] && pos[2][i] < pos0; ++i) swaps++;
                            dp[0][i0 + 1][i1][i2] = min(dp[0][i0 + 1][i1][i2], cur + swaps);
                        }

                        if (i1 < c[1]) {
                            int swaps = 0, pos1 = pos[1][i1];
                            for (int i = i0; i < c[0] && pos[0][i] < pos1; ++i) swaps++;
                            for (int i = i2; i < c[2] && pos[2][i] < pos1; ++i) swaps++;
                            dp[1][i0][i1 + 1][i2] = min(dp[1][i0][i1 + 1][i2], cur + swaps);
