                    boolean valid = true;
                    int fixedX = -1;

                    for (int i = 0; i < 2; i++) {
                        char target = end.charAt(i);
                        char actual = inp[n - 2 + i];

                        if (actual == '_') continue;
                        if (actual == 'X') {
                            int val = target - '0';
                            if (fixedX == -1) fixedX = val;
