class MyScanner {
private:
    static const int BUF_SIZE = 2048;
    FILE* br;
    char buf[BUF_SIZE];
    int bufPos, bufLen;

    void fillBuffer() {
        bufLen = fread(buf, 1, BUF_SIZE, br);
        bufPos = 0;
    }

public:
    MyScanner() : br(stdin), bufPos(0), bufLen(0) {}

    bool isSpace(char c) {
        return c == '\n' || c == '\r' || c == ' ';
    }

    string next() {
        string res = "";
        int c;
        while ((c = getChar()) != EOF && isSpace((char)c));
        if (c == EOF) return "";

        res += (char)c;
        while ((c = getChar()) != EOF && !isSpace((char)c)) {
            res += (char)c;
        }
        return res;
    }

    int nextInt() {
        return stoi(next());
    }

    long long nextLong() {
        return stoll(next());
    }

    double nextDouble() {
        return stod(next());
    }

private:
    int getChar() {
        if (bufPos >= bufLen) {
            fillBuffer();
            if (bufLen == 0) return EOF;
        }
        return buf[bufPos++];
    }
};

