bool* prime(int num) {
    bool* boolArr = new bool[num];
    for (int i = 0; i < num; i++) {
        boolArr[i] = true;
    }
    for (int i = 2; i <= sqrt(num); i++) {
        if (boolArr[i] == true) {
            for (int j = i * i; j < num; j = j + i) {
                boolArr[j] = false;
