    if (length < 2) return 0;
    char last = target[1];
    char first = target[0];

    if ((digits[length - 1] == '_' || digits[length - 1] == last) &&
        (digits[length - 2] == '_' || digits[length - 2] == first)) {
        return (long long)pow(10, unknownCount);
    }
    return 0;
}

long long computeValidNumbers(vector<char> digits, int n) {
    if (n == 1 || digits[0] == '0') return 0;

    int unknownCount = 0;
    for (int i = 1; i < n - 2; i++) {
        if (digits[i] == '_') unknownCount++;
    }

    long long result = 0;
    result += countForSuffix(digits, "25", n, unknownCount);
    result += countForSuffix(digits, "50", n, unknownCount);
    result += countForSuffix(digits, "75", n, unknownCount);

    if (n > 2 && digits[0] == '_') {
        result *= 9;
    }

    if (n >= 3) {
        if ((digits[n - 1] == '_' || digits[n - 1] == '0') &&
            (digits[n - 2] == '_' || digits[n - 2] == '0')) {
            if (n > 3) {
                long long temp = (long long)pow(10, unknownCount);
                if (digits[0] == '_') temp *= 9;
                result += temp;
            } else if (n == 3) {
                if (digits[0] == '_') {
                    result += 9;
                } else {
                    result += 1;
                }
            }
        }
    }

    return result;
}

