using namespace std;

class FastReader {
public:
    string line;
    int pos;
    vector<string> tokens;

    FastReader() : pos(0) {}

    string next() {
        while (tokens.empty() || pos >= tokens.size()) {
            if (!getline(cin, line)) return "";
            tokens.clear();
            pos = 0;
            istringstream iss(line);
            string token;
            while (iss >> token) {
                tokens.push_back(token);
            }
        }
        return tokens[pos++];
    }

    int nextInt() {
        return stoi(next());
    }

    long nextLong() {
        return stol(next());
    }

    double nextDouble() {
        return stod(next());
    }

    string nextLine() {
        if (!getline(cin, line)) return "";
        return line;
    }
};

int fun(string s) {
    int n = s.length();
    int p = 0;
    if (s[0] != '0') p = 1;

    for (int i = 0; i < n - 2; i++) {
        if (s[i] == '_') {
            if (i == 0) p *= 9;
            else p *= 10;
        }
    }

    int p1 = 0;
    if (s[n-1] == '_' && s[n-2] == '_') {
        p1 = 4;
        if (n == 2) p1 = 3;
    } else if (s[n-1] == '_') {
        if (s[n-2] == '0' || s[n-2] == '5' || s[n-2] == '2' || s[n-2] == '7') 
            p1 = 1;
    } else if (s[n-2] == '_') {
        if (s[n-1] == '0') {
            p1 = 2;
            if (n == 2) p1 = 1;
        } else if (s[n-1] == '5') {
            p1 = 2;
        }
    } else {
        int val = stoi(s.substr(n-2));
        if (val % 25 == 0) p1 = 1;
    }

    int pro = p * p1;
    return pro;
}

