        } else {
            int f = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s[i] == 'X') {
                    f = 1;
                    break;
                }
            }
            if (f == 0) {
                cout << fun(s) << endl;
            } else {
                int sum = 0;
