    int ways = 0;
    if (s[0] != '0') {
        ways = 1;
    }
    for (int i = 0; i < n - 2; i++) {
        if (s[i] == '_') {
            if (i == 0) {
                ways *= 9;
            } else {
                ways *= 10;
            }
        }
    }
    int suffixWays = 0;
    if (n >= 2) {
        if (s[n-1] == '_' && s[n-2] == '_') {
            suffixWays = 4;
            if (n == 2) {
                suffixWays = 3;
            }
