        if (getline(cin, str)) {
            return str;
        }
        return "";
    }
};

bool isSpecial(char c) {
    return c == '0' || c == '_' || c == 'X';
}

string replaceAllX(const string& s, int digit) {
    string result = s;
    size_t pos = 0;
    while ((pos = result.find("X", pos)) != string::npos) {
        result.replace(pos, 1, string(1, '0' + digit));
        pos++;
    }
    return result;
}

int countValid(const string& s) {
    int n = s.length();
    int prefix = (s[0] == '0') ? 0 : 1;
    for (int i = 0; i < n - 2; i++) {
        if (s[i] == '_') {
            prefix *= (i == 0) ? 9 : 10;
        }
    }
    int suffix = 0;
    if (n >= 2) {
        char a = s[n - 2];
        char b = s[n - 1];
        if (a == '_' && b == '_') {
            suffix = (n == 2) ? 3 : 4;
        } else if (b == '_') {
            if (a == '0' || a == '5' || a == '2' || a == '7') {
                suffix = 1;
            }
        } else if (a == '_') {
            if (b == '0') {
                suffix = (n == 2) ? 1 : 2;
            } else if (b == '5') {
                suffix = 2;
            }
        } else {
            int val = stoi(s.substr(n - 2));
            suffix = (val % 25 == 0) ? 1 : 0;
        }
    }
    return prefix * suffix;
}

int main() {
    FastReader input;
    int T = 1;
    while (T-- > 0) {
        string s = input.next();
        if (s.length() == 1) {
            cout << (isSpecial(s[0]) ? 1 : 0) << endl;
        } else {
            if (s.find("X") == string::npos) {
                cout << countValid(s) << endl;
            } else {
                int total = 0;
                for (int d = 0; d < 10; d++) {
                    total += countValid(replaceAllX(s, d));
                }
                cout << total << endl;
            }
        }
    }
    return 0;
}

