import java.io.*;
import java.util.*;

public class Codeforces {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        double target = Double.parseDouble(st.nextToken());
        br.close();

        int minIndex = n;
        outer:
        for (int i = 0; i <= n; i++) {
            if (computeProbability(n, i) >= target) {
                minIndex = i;
                break outer;
            }
        }
        System.out.println(minIndex);
    }

    static int binomial(int N, int K) {
        if (K < 0 || K > N) return 0;
        if (K == 0 || K == N) return 1;
        if (K > N - K) K = N - K;
        int res = 1;
        for (int i = 0; i < K; i++) {
            res *= (N - i);
            res /= (i + 1);
        }
        return res;
    }

    static double computeProbability(int n, int x) {
        int partA = binomial(x, 3) * binomial(n - x, 0);
        int partB = binomial(x, 2) * binomial(n - x, 1);
        int partC = binomial(x, 1) * binomial(n - x, 2);
        double sum = partA + partB + 0.5 * partC;
        return sum / binomial(n, 3);
    }
}

