    if (K < 0 || K > N) return 0;
    if (K == 0 || K == N) return 1;
    if (K > N - K) K = N - K;
    int res = 1;
    for (int i = 0; i < K; i++) {
        res *= (N - i);
        res /= (i + 1);
    }
    return res;
}

double computeProbability(int n, int x) {
    int partA = binomial(x, 3) * binomial(n - x, 0);
    int partB = binomial(x, 2) * binomial(n - x, 1);
    int partC = binomial(x, 1) * binomial(n - x, 2);
    double sum = partA + partB + 0.5 * partC;
    return sum / binomial(n, 3);
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    int n;
    double target;
    iss >> n >> target;

    int minIndex = n;
    for (int i = 0; i <= n; i++) {
        if (computeProbability(n, i) >= target) {
            minIndex = i;
            break;
        }
    }
    std::cout << minIndex << std::endl;
    return 0;
}

