#include <stdexcept>
#include <cstring>

using namespace std;

class Main {
public:
    void run() {
        int mod = 998244353;
        int n, k;
        cin >> n >> k;

        vector<int> v(10, 0);
        for (int i = 0; i < k; i++) {
            int idx;
            cin >> idx;
            v[idx] = 1;
        }

        vector<int> ans = {1};
        int p = n / 2;
        while (true) {
            if ((p & 1) == 1) {
                ans = multiply(ans, v, mod);
            }
            v = multiply(v, v, mod);
            p >>= 1;
            if (p == 0) break;
        }

        long long res = 0;
        for (int x : ans) {
            res = (res + (long long)x * x) % mod;
        }
        cout << res << endl;
    }

    vector<int> multiply(const vector<int>& a, const vector<int>& b, int mod) {
        int need = a.size() + b.size() - 1;
        int n = max(2, 1 << (32 - __builtin_clz(need - 1)));

        vector<double> ar(n, 0.0), ai(n, 0.0);
        for (int i = 0; i < a.size(); i++) {
            long long x = (a[i] % mod + mod) % mod;
            ar[i] = x & ((1 << 15) - 1);
            ai[i] = x >> 15;
        }
        fft(ar, ai, false);

        vector<double> br(n, 0.0), bi(n, 0.0);
        for (int i = 0; i < b.size(); i++) {
            long long x = (b[i] % mod + mod) % mod;
            br[i] = x & ((1 << 15) - 1);
            bi[i] = x >> 15;
        }
        fft(br, bi, false);

        vector<double> fr(n, 0.0), fi(n, 0.0);
        vector<double> gr(n, 0.0), gi(n, 0.0);

        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);

            double ar1 = (ar[i] + ar[j]) * 0.5;
            double ai1 = (ai[i] - ai[j]) * 0.5;
            double ar2 = (ai[i] + ai[j]) * 0.5;
            double ai2 = (ar[j] - ar[i]) * 0.5;

            double br1 = (br[i] + br[j]) * 0.5;
            double bi1 = (bi[i] - bi[j]) * 0.5;
            double br2 = (bi[i] + bi[j]) * 0.5;
            double bi2 = (br[j] - br[i]) * 0.5;

            fr[i] = ar1 * br1 - ai1 * bi1 - ar2 * bi2 - ai2 * br2;
            fi[i] = ar1 * bi1 + ai1 * br1 + ar2 * br2 - ai2 * bi2;
            gr[i] = ar1 * br2 - ai1 * bi2 + ar2 * br1 - ai2 * bi1;
            gi[i] = ar1 * bi2 + ai1 * br2 + ar2 * bi1 + ai2 * br1;
        }

        fft(fr, fi, true);
        fft(gr, gi, true);

        vector<int> res(need);
        for (int i = 0; i < need; i++) {
            long long a_val = llround(fr[i]);
            long long b_val = llround(gr[i]);
            long long c_val = llround(fi[i]);
            res[i] = (int)((a_val + ((b_val % mod) << 15) + ((c_val % mod) << 30)) % mod);
        }
        return res;
    }

    void fft(vector<double>& re, vector<double>& im, bool inverse) {
        int n = re.size();
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; (j ^= bit) < bit; bit >>= 1);
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            double ang = 2 * M_PI / len * (inverse ? -1 : 1);
            double wlen_re = cos(ang);
            double wlen_im = sin(ang);

            for (int i = 0; i < n; i += len) {
                double w_re = 1.0;
                double w_im = 0.0;
                for (int j = 0; j < len / 2; j++) {
                    double u_re = re[i + j];
                    double u_im = im[i + j];
                    double v_re = re[i + j + len/2] * w_re - im[i + j + len/2] * w_im;
                    double v_im = re[i + j + len/2] * w_im + im[i + j + len/2] * w_re;

                    re[i + j] = u_re + v_re;
                    im[i + j] = u_im + v_im;
                    re[i + j + len/2] = u_re - v_re;
                    im[i + j + len/2] = u_im - v_im;

                    double tmp = w_re * wlen_re - w_im * wlen_im;
                    w_im = w_re * wlen_im + w_im * wlen_re;
                    w_re = tmp;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }
};

int main() {
    Main mainInstance;
    mainInstance.run();
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>
using namespace std;

class Main {
public:
    void exec() {
        int n, k;
        cin >> n >> k;

        vector<int> poly(10, 0);
        for (int i = 0; i < k; i++) {
            int x;
            cin >> x;
            poly[x] = 1;
        }

        vector<int> result = {1};
        int exponent = n / 2;

        const int MOD = 998244353;

        while (exponent > 0) {
            if (exponent & 1) {
                result = convolute(result, poly, MOD);
            }
            poly = convolute(poly, poly, MOD);
            exponent >>= 1;
        }

        long long answer = 0;
        for (int val : result) {
            answer = (answer + (long long)val * val) % MOD;
        }
        cout << answer << endl;
    }

    vector<int> convolute(vector<int> p, vector<int> q, int mod) {
        int len = p.size() + q.size() - 1;
        int n = 1;
        while (n < len) n <<= 1;
        if (n < 2) n = 2;

        vector<double> pr(n, 0.0), pi(n, 0.0);
        for (int i = 0; i < p.size(); i++) {
            long long x = (p[i] % mod + mod) % mod;
            pr[i] = x & 0x7FFF;
            pi[i] = x >> 15;
        }
        transform(pr, pi, false);

        vector<double> qr(n, 0.0), qi(n, 0.0);
        for (int i = 0; i < q.size(); i++) {
            long long x = (q[i] % mod + mod) % mod;
            qr[i] = x & 0x7FFF;
            qi[i] = x >> 15;
        }
        transform(qr, qi, false);

        vector<double> cr(n, 0.0), ci(n, 0.0);
        vector<double> dr(n, 0.0), di(n, 0.0);

        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);

            double a1r = (pr[i] + pr[j]) * 0.5;
            double a1i = (pi[i] - pi[j]) * 0.5;
            double a2r = (pi[i] + pi[j]) * 0.5;
            double a2i = (pr[j] - pr[i]) * 0.5;

            double b1r = (qr[i] + qr[j]) * 0.5;
            double b1i = (qi[i] - qi[j]) * 0.5;
            double b2r = (qi[i] + qi[j]) * 0.5;
            double b2i = (qr[j] - qr[i]) * 0.5;

            cr[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            ci[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            dr[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            di[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        transform(cr, ci, true);
        transform(dr, di, true);

        vector<int> res(len);
        for (int i = 0; i < len; i++) {
            long long a = llround(cr[i]);
            long long b = llround(dr[i]);
            long long c = llround(ci[i]);
            res[i] = (int)((a + ((b % mod) << 15) + ((c % mod) << 30)) % mod);
        }
        return res;
    }

    void transform(vector<double>& re, vector<double>& im, bool inverse) {
        int n = re.size();
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; j ^ bit; bit >>= 1) {
                j ^= bit;
                if (j < bit) break;
            }
            if (i < j) {
                swap(re[i], re[j]);
                swap(im[i], im[j]);
            }
        }

        for (int h = 2; h <= n; h <<= 1) {
            double ang = 2 * M_PI / h * (inverse ? -1 : 1);
            double wH_re = cos(ang);
            double wH_im = sin(ang);

            for (int i = 0; i < n; i += h) {
                double w_re = 1.0;
                double w_im = 0.0;
                for (int j = 0; j < h / 2; j++) {
                    double ur = re[i + j];
                    double ui = im[i + j];
                    double vr = re[i + j + h/2] * w_re - im[i + j + h/2] * w_im;
                    double vi = re[i + j + h/2] * w_im + im[i + j + h/2] * w_re;

                    re[i + j] = ur + vr;
                    im[i + j] = ui + vi;
                    re[i + j + h/2] = ur - vr;
                    im[i + j + h/2] = ui - vi;

                    double t_re = w_re * wH_re - w_im * wH_im;
                    w_im = w_re * wH_im + w_im * wH_re;
                    w_re = t_re;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }
};

int main() {
    Main mainInstance;
    mainInstance.exec();
    return 0;
}

#include <iostream>
