const int MOD = 998244353;

vector<int> polyMul(const vector<int>& a, const vector<int>& b, int mod) {
    int need = a.size() + b.size() - 1;
    int size = 1;
    while (size < need) size <<= 1;

    vector<double> ar(size, 0.0), ai(size, 0.0);
    vector<double> br(size, 0.0), bi(size, 0.0);

    for (int i = 0; i < a.size(); i++) {
        long long x = a[i];
        x = ((x % mod) + mod) % mod;
        ar[i] = x & 32767;
        ai[i] = x >> 15;
    }
    for (int i = 0; i < b.size(); i++) {
        long long x = b[i];
        x = ((x % mod) + mod) % mod;
        br[i] = x & 32767;
        bi[i] = x >> 15;
    }

    // FFT for ar, ai
    int n = size;
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) {
            swap(ar[i], ar[j]);
            swap(ai[i], ai[j]);
        }
    }

    for (int h = 2; h <= n; h <<= 1) {
        double ang = 2 * M_PI / h;
        double wr = cos(ang);
        double wi = sin(ang);

        for (int i = 0; i < n; i += h) {
            double w_r = 1.0;
            double w_i = 0.0;
            int half = h >> 1;
            for (int j = 0; j < half; j++) {
                double ur = ar[i + j];
                double ui = ai[i + j];
                double vr = ar[i + j + half] * w_r - ai[i + j + half] * w_i;
                double vi = ar[i + j + half] * w_i + ai[i + j + half] * w_r;

                ar[i + j] = ur + vr;
                ai[i + j] = ui + vi;
                ar[i + j + half] = ur - vr;
                ai[i + j + half] = ui - vi;

                double t = w_r * wr - w_i * wi;
                w_i = w_r * wi + w_i * wr;
                w_r = t;
            }
        }
    }

    // FFT for br, bi
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) {
            swap(br[i], br[j]);
            swap(bi[i], bi[j]);
        }
    }

    for (int h = 2; h <= n; h <<= 1) {
        double ang = 2 * M_PI / h;
        double wr = cos(ang);
        double wi = sin(ang);

        for (int i = 0; i < n; i += h) {
            double w_r = 1.0;
            double w_i = 0.0;
            int half = h >> 1;
            for (int j = 0; j < half; j++) {
                double ur = br[i + j];
                double ui = bi[i + j];
                double vr = br[i + j + half] * w_r - bi[i + j + half] * w_i;
                double vi = br[i + j + half] * w_i + bi[i + j + half] * w_r;

                br[i + j] = ur + vr;
                bi[i + j] = ui + vi;
                br[i + j + half] = ur - vr;
                bi[i + j + half] = ui - vi;

                double t = w_r * wr - w_i * wi;
                w_i = w_r * wi + w_i * wr;
                w_r = t;
            }
        }
    }

    vector<double> resr(size), resi(size), resj(size), resk(size);

    for (int i = 0; i < n; i++) {
        int j = (n - i) & (n - 1);

        double a1r = (ar[i] + ar[j]) * 0.5;
        double a1i = (ai[i] - ai[j]) * 0.5;
        double a2r = (ai[i] + ai[j]) * 0.5;
        double a2i = (ar[j] - ar[i]) * 0.5;

        double b1r = (br[i] + br[j]) * 0.5;
        double b1i = (bi[i] - bi[j]) * 0.5;
        double b2r = (bi[i] + bi[j]) * 0.5;
        double b2i = (br[j] - br[i]) * 0.5;

        resr[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
        resi[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
        resj[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
        resk[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
    }

    // Inverse FFT for resr, resi
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) {
            swap(resr[i], resr[j]);
            swap(resi[i], resi[j]);
        }
    }

    for (int h = 2; h <= n; h <<= 1) {
        double ang = 2 * M_PI / h;
        double wr = cos(ang);
        double wi = -sin(ang);

        for (int i = 0; i < n; i += h) {
            double w_r = 1.0;
            double w_i = 0.0;
            int half = h >> 1;
            for (int j = 0; j < half; j++) {
                double ur = resr[i + j];
                double ui = resi[i + j];
                double vr = resr[i + j + half] * w_r - resi[i + j + half] * w_i;
