                resr[i + j] = ur + vr;
                resi[i + j] = ui + vi;
                resr[i + j + half] = ur - vr;
                resi[i + j + half] = ui - vi;

                double t = w_r * wr - w_i * wi;
                w_i = w_r * wi + w_i * wr;
                w_r = t;
            }
        }
    }

    for (int i = 0; i < n; i++) resr[i] /= n;
    for (int i = 0; i < n; i++) resi[i] /= n;

    // Inverse FFT for resj, resk
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) {
            swap(resj[i], resj[j]);
            swap(resk[i], resk[j]);
        }
    }

    for (int h = 2; h <= n; h <<= 1) {
        double ang = 2 * M_PI / h;
        double wr = cos(ang);
        double wi = -sin(ang);

        for (int i = 0; i < n; i += h) {
            double w_r = 1.0;
            double w_i = 0.0;
            int half = h >> 1;
            for (int j = 0; j < half; j++) {
                double ur = resj[i + j];
                double ui = resk[i + j];
                double vr = resj[i + j + half] * w_r - resk[i + j + half] * w_i;
                double vi = resj[i + j + half] * w_i + resk[i + j + half] * w_r;

                resj[i + j] = ur + vr;
                resk[i + j] = ui + vi;
                resj[i + j + half] = ur - vr;
                resk[i + j + half] = ui - vi;

                double t = w_r * wr - w_i * wi;
                w_i = w_r * wi + w_i * wr;
                w_r = t;
            }
        }
    }

    for (int i = 0; i < n; i++) resj[i] /= n;
    for (int i = 0; i < n; i++) resk[i] /= n;

    vector<int> res(need);
    for (int i = 0; i < need; i++) {
        long long a = llround(resr[i]);
        long long b = llround(resj[i]);
        long long c = llround(resi[i]);
        res[i] = (int)((a + ((b % mod) << 15) + ((c % mod) << 30)) % mod);
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
