const long long MOD = 998244353;

vector<long long> shrink(vector<long long> arr) {
    int last = arr.size() - 1;
    while (last >= 0 && arr[last] == 0) last--;
    if (last < 0) return {};
    return vector<long long>(arr.begin(), arr.begin() + last + 1);
}

vector<long long> polySquare(const vector<long long>& a) {
    int n = a.size();
    vector<long long> res(2 * n - 1, 0);
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            long long prod = (a[i] * a[j]) % MOD;
            if (i == j) {
                res[i + j] = (res[i + j] + prod) % MOD;
            } else {
                res[i + j] = (res[i + j] + 2 * prod) % MOD;
            }
        }
    }
    return res;
}

vector<long long> polyMultiply(const vector<long long>& a, const vector<long long>& b) {
    int lenA = a.size(), lenB = b.size();
    vector<long long> res(lenA + lenB - 1, 0);
    for (int i = 0; i < lenA; i++) {
        for (int j = 0; j < lenB; j++) {
            res[i + j] = (res[i + j] + a[i] * b[j]) % MOD;
        }
    }
    return res;
}

