    Main mainInstance;
    mainInstance.run();
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>

using namespace std;

const int MOD = 998244353;

vector<int> convolve(const vector<int>& x, const vector<int>& y, int mod) {
    int len = x.size() + y.size() - 1;
    int size = 1;
    while (size < len) size <<= 1;

    vector<double> xr(size, 0.0), xi(size, 0.0);
    for (int i = 0; i < x.size(); i++) {
        long long v = ((long long)x[i] % mod + mod) % mod;
        xr[i] = v & 32767;
        xi[i] = v >> 15;
    }

    // FFT
    for (int i = 1, j = 0; i < size; i++) {
        int bit = size >> 1;
        while (j >= bit) {
            j -= bit;
            bit >>= 1;
        }
        j += bit;
        if (i < j) {
            swap(xr[i], xr[j]);
            swap(xi[i], xi[j]);
        }
    }

    for (int step = 2; step <= size; step <<= 1) {
        int half = step >> 1;
        vector<double> c(half), s(half);
        for (int i = 0; i < half; i++) {
            double angle = 2 * M_PI * i / step;
            c[i] = cos(angle);
            s[i] = sin(angle);
        }

        for (int i = 0; i < size; i += step) {
            for (int k = 0; k < half; k++) {
                double cr = xr[i + k + half] * c[k] - xi[i + k + half] * s[k];
                double ci = xr[i + k + half] * s[k] + xi[i + k + half] * c[k];

                double ur = xr[i + k];
                double ui = xi[i + k];

                xr[i + k] = ur + cr;
                xi[i + k] = ui + ci;
                xr[i + k + half] = ur - cr;
                xi[i + k + half] = ui - ci;
            }
        }
    }

    vector<double> yr(size, 0.0), yi(size, 0.0);
    if (x == y) {
        yr = xr;
        yi = xi;
    } else {
        for (int i = 0; i < y.size(); i++) {
            long long v = ((long long)y[i] % mod + mod) % mod;
            yr[i] = v & 32767;
            yi[i] = v >> 15;
        }

        // FFT for y
        for (int i = 1, j = 0; i < size; i++) {
            int bit = size >> 1;
            while (j >= bit) {
                j -= bit;
                bit >>= 1;
            }
            j += bit;
            if (i < j) {
                swap(yr[i], yr[j]);
                swap(yi[i], yi[j]);
            }
        }

        for (int step = 2; step <= size; step <<= 1) {
            int half = step >> 1;
            vector<double> c(half), s(half);
            for (int i = 0; i < half; i++) {
                double angle = 2 * M_PI * i / step;
                c[i] = cos(angle);
                s[i] = sin(angle);
            }

            for (int i = 0; i < size; i += step) {
                for (int k = 0; k < half; k++) {
                    double cr = yr[i + k + half] * c[k] - yi[i + k + half] * s[k];
                    double ci = yr[i + k + half] * s[k] + yi[i + k + half] * c[k];

                    double ur = yr[i + k];
                    double ui = yi[i + k];

                    yr[i + k] = ur + cr;
                    yi[i + k] = ui + ci;
                    yr[i + k + half] = ur - cr;
                    yi[i + k + half] = ui - ci;
                }
            }
        }
    }

    vector<double> resR(size, 0.0), resI(size, 0.0);
    double factor = 0.25 / size;

    for (int i = 0; i < size; i++) {
        int j = (size - i) & (size - 1);

        double ar = xr[i] + xr[j];
        double ai = xi[i] - xi[j];
        double ac = xi[i] + xi[j];
        double ad = xr[j] - xr[i];

        double br = yr[i] + yr[j];
        double bi = yi[i] - yi[j];
        double bc = yi[i] + yi[j];
        double bd = yr[j] - yr[i];

        resR[i] = (ar * br - ai * bi) * factor - (ac * bd + ad * bc) * factor;
        resI[i] = (ar * bi + ai * br) * factor + (ac * bc - ad * bd) * factor;
    }

    // Inverse FFT
    for (int i = 1, j = 0; i < size; i++) {
        int bit = size >> 1;
        while (j >= bit) {
            j -= bit;
            bit >>= 1;
        }
        j += bit;
        if (i < j) {
            swap(resR[i], resR[j]);
            swap(resI[i], resI[j]);
        }
    }

    for (int step = 2; step <= size; step <<= 1) {
        int half = step >> 1;
        vector<double> c(half), s(half);
        for (int i = 0; i < half; i++) {
            double angle = -2 * M_PI * i / step;
            c[i] = cos(angle);
            s[i] = sin(angle);
        }

        for (int i = 0; i < size; i += step) {
            for (int k = 0; k < half; k++) {
                double cr = resR[i + k + half] * c[k] - resI[i + k + half] * s[k];
                double ci = resR[i + k + half] * s[k] + resI[i + k + half] * c[k];

                double ur = resR[i + k];
                double ui = resI[i + k];

                resR[i + k] = ur + cr;
                resI[i + k] = ui + ci;
                resR[i + k + half] = ur - cr;
                resI[i + k + half] = ui - ci;
            }
        }
    }

    for (int i = 0; i < size; i++) {
        resR[i] /= size;
        resI[i] /= size;
    }

    vector<int> out(len);
    for (int i = 0; i < len; i++) {
        long long r = llround(resR[i]);
        long long im = llround(resI[i]);
        long long low = r % mod;
        long long high = im % mod;
        out[i] = (int)((low + (high << 15)) % mod);
    }
    return out;
}

