public class Main {
    static final int MOD = 998244353;
    static final int G = 3;

    static long modPow(long base, long exp) {
        base %= MOD;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static void bitReverse(long[] arr, int n) {
        for (int i = 1, j = n >>> 1; i < n - 1; i++) {
            if (i < j) {
                long temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
            for (int k = n >>> 1; j >= k; k >>>= 1) j -= k;
            if (j < k) j += k;
        }
    }

    static void ntt(long[] arr, int n, int sign) {
        bitReverse(arr, n);
        for (int h = 2; h <= n; h <<= 1) {
            long wn = modPow(G, (MOD - 1) / h);
            if (sign == -1) wn = modPow(wn, MOD - 2);
            for (int j = 0; j < n; j += h) {
                long w = 1;
                int half = h >>> 1;
                for (int k = j; k < j + half; k++) {
                    long u = arr[k];
                    long t = (w * arr[k + half]) % MOD;
                    arr[k] = (u + t) % MOD;
                    arr[k + half] = (u - t + MOD) % MOD;
                    w = (w * wn) % MOD;
                }
            }
        }
        if (sign == -1) {
            long invN = modPow(n, MOD - 2);
            for (int i = 0; i < n; i++) arr[i] = (arr[i] * invN) % MOD;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
