        for (int i = 0; i < m; i++) {
            int x = Integer.parseInt(st.nextToken());
            a[x] = 1;
        }

        ntt(a, len, 1);
        for (int i = 0; i < len; i++) {
            if (a[i] != 0) a[i] = modPow(a[i], nn);
