    int nextInt() {
        int c = read();
        while (isWhitespace(c))
            c = read();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw runtime_error("Input mismatch");
            res = res * 10 + c - '0';
            c = read();
        } while (!isWhitespace(c));
        return res * sign;
    }

private:
    int read() {
        if (size == -1)
            throw runtime_error("Input mismatch");
        if (pos >= size) {
            pos = 0;
            try {
                size = is.readsome(&buf[0], buf.size());
            } catch (...) {
                throw runtime_error("Input mismatch");
            }
            if (size <= 0)
                return -1;
        }
        return buf[pos++] & 255;
    }

    static bool isWhitespace(int c) {
