using namespace std;

const int SIZE = 1 << 20;
const long long MOD = 998244353LL;
const long long ROOT = 646LL;
vector<long long> ROOT_POWERS(SIZE);
vector<long long> ROOT_INV_POWERS(SIZE);
long long SIZE_INVERSE;

long long modPow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long modInverse(long long a, long long mod) {
    return modPow(a, mod - 2, mod);
}

class CoefficientArray {
public:
    vector<long long> values;

    CoefficientArray(const vector<long long>& input) : values(SIZE, 0) {
        for (size_t i = 0; i < input.size(); i++) {
            values[i] = input[i];
        }
    }

    vector<long long> transform(bool forward) {
        return recursiveTransform(0, 1, forward);
    }

private:
    vector<long long> recursiveTransform(int start, int step, bool forward) {
        if (step == SIZE) {
            return vector<long long>{values[start]};
        }
        vector<long long> even = recursiveTransform(start, step << 1, forward);
        vector<long long> odd = recursiveTransform(start + step, step << 1, forward);
        int half = even.size();
        vector<long long> combined(half * 2);
        for (int i = 0; i < half; i++) {
            long long twiddle = forward ? ROOT_POWERS[i * step] : ROOT_INV_POWERS[i * step];
            combined[i] = (even[i] + twiddle * odd[i]) % MOD;
            if (combined[i] < 0) combined[i] += MOD;
        }
        for (int i = 0; i < half; i++) {
            long long twiddle = forward ? ROOT_POWERS[i * step] : ROOT_INV_POWERS[i * step];
            combined[half + i] = ((even[i] - twiddle * odd[i]) % MOD + MOD) % MOD;
        }
        return combined;
    }
};

long long directFourierTransform(const vector<long long>& input, vector<long long>& output) {
    output.assign(SIZE, 0);
    long long wPower = 1;
    for (int i = 0; i < SIZE; i++) {
        long long x = 1;
        for (size_t j = 0; j < input.size(); j++) {
            output[i] = (output[i] + input[j] * x) % MOD;
            x = x * wPower % MOD;
        }
        wPower = wPower * ROOT % MOD;
    }
    return 0;
}

vector<long long> raiseToExponent(vector<long long>& arr, int exponent) {
    for (size_t i = 0; i < arr.size(); i++) {
        arr[i] = modPow(arr[i], exponent, MOD);
    }
    return arr;
}

void run() {
    int n, k;
    cin >> n >> k;
    vector<long long> poly(10, 0);
    for (int i = 0; i < k; i++) {
        int idx;
        cin >> idx;
        if (idx < 10) poly[idx] = 1;
    }

    vector<long long> transformed(SIZE);
    directFourierTransform(poly, transformed);
    transformed = raiseToExponent(transformed, n / 2);

    CoefficientArray buffer(transformed);
    transformed = buffer.transform(false);

    for (size_t i = 0; i < transformed.size(); i++) {
        transformed[i] = transformed[i] * SIZE_INVERSE % MOD;
    }

    long long answer = 0;
    for (size_t i = 0; i < transformed.size(); i++) {
        answer = (answer + transformed[i] * transformed[i]) % MOD;
    }
    cout << answer << endl;
}

int main() {
    // Precompute ROOT_POWERS and ROOT_INV_POWERS
    ROOT_POWERS[0] = 1;
    ROOT_INV_POWERS[0] = 1;
    for (int i = 1; i < SIZE; i++) {
        ROOT_POWERS[i] = ROOT_POWERS[i - 1] * ROOT % MOD;
        ROOT_INV_POWERS[i] = ROOT_INV_POWERS[i - 1] * ROOT % MOD;
    }

    // Precompute SIZE_INVERSE
    SIZE_INVERSE = modInverse(SIZE, MOD);

    run();

    return 0;
}

