        base[x] = 1;
    }

    vector<int> result = {1};
    int exp = N / 2;

    while (true) {
        if (exp & 1) {
            result = convolve(result, base, MOD);
        }
        exp >>= 1;
        if (exp == 0) break;
        base = convolve(base, base, MOD);
    }

    long long sum = 0;
    for (int val : result) {
        sum = (sum + (long long)val * val) % MOD;
    }
    cout << sum << endl;

    return 0;
}

