#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>

using namespace std;

const int MOD = 998244353;
const int TWO_POW = 23;
const int ROOT = 15311432;

int bitReverse(int n, int k) {
    n = ((n & 0x55555555) << 1) | ((n & 0xAAAAAAAA) >> 1);
    n = ((n & 0x33333333) << 2) | ((n & 0xCCCCCCCC) >> 2);
    n = ((n & 0x0F0F0F0F) << 4) | ((n & 0xF0F0F0F0) >> 4);
    n = ((n & 0x00FF00FF) << 8) | ((n & 0xFF00FF00) >> 8);
    n = (n << 16) | (n >> 16);
    return n >> (32 - k);
}

long long modPow(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if ((exp & 1) == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long a) {
    return modPow(a, MOD - 2);
}

vector<long long> buildRoots(int k, bool inverse) {
    long long root = modPow(ROOT, modPow(2, TWO_POW - k));
    if (inverse) root = modInverse(root);
    vector<long long> rts(k, 0);
    if (k > 0) {
        rts[k - 1] = root;
        for (int i = k - 1; i > 0; i--) {
            rts[i - 1] = (rts[i] * rts[i]) % MOD;
        }
    }
    return rts;
}

vector<long long> permute(const vector<long long>& arr, int k) {
    vector<long long> res(arr.size(), 0);
    for (int i = 0; i < arr.size(); i++) {
        res[bitReverse(i, k)] = arr[i];
    }
    return res;
}

vector<long long> ntt(vector<long long> coef, int k, bool inverse) {
    coef = permute(coef, k);
    vector<long long> roots = buildRoots(k, inverse);
    for (int s = 0; s < k; s++) {
        int len = 1 << s;
        for (int st = 0; st < (int)coef.size(); st += 2 * len) {
            long long curRoot = 1;
            for (int j = st; j < st + len; j++) {
                long long t = (curRoot * coef[j + len]) % MOD;
                long long u = coef[j];
                coef[j] = (u + t) % MOD;
                long long diff = u - t;
                coef[j + len] = (diff < 0 ? diff + MOD : diff) % MOD;
                curRoot = (roots[s] * curRoot) % MOD;
            }
        }
    }
    return coef;
}

