        a = input;
        int n = a.size();
        int k = (int)floor(log(n) / log(2)) + 1;
        st.assign(n, vector<int>(k, 0));

        for (int i = 0; i < n; i++) {
            st[i][0] = i;
        }

        for (int j = 1; (1 << j) <= n; j++) {
            for (int i = 0; i + (1 << j) - 1 < n; i++) {
                if (a[st[i][j-1]] < a[st[i + (1 << (j-1))][j-1]]) {
                    st[i][j] = st[i][j-1];
                } else {
                    st[i][j] = st[i + (1 << (j-1))][j-1];
                }
            }
        }
