    int curChar, numChars;

public:
    InputReader(istream& s) : stream(s), curChar(0), numChars(0) {}

    int read() {
        if (numChars == -1) throw ios_base::failure("IO error");
        if (curChar >= numChars) {
            curChar = 0;
            stream.read(buf, 8192);
            numChars = stream.gcount();
            if (numChars <= 0) return -1;
        }
        return buf[curChar++];
    }

    int nextInt() {
        int c = read();
        while (c <= 32) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        while (c > 32) {
            res = res * 10 + (c - '0');
            c = read();
        }
        return res * sgn;
    }
};

int N, K;
vector<int> L, R;
int minAnswer;
int rotCount = 0;

void record(int x) {
    if (minAnswer == 0) minAnswer = x;
    else minAnswer = min(minAnswer, x);
}

void traverse(int side, vector<int>& low, vector<int>& high, int cur, int pos, bool inside) {
    if (low[0] > N || low[1] > N) return;
    if ((low[0] <= N && high[0] >= N) || (low[1] <= N && high[1] >= N)) {
        if ((high[0] < N && side == 1) || (high[1] < N && side == 0)) {
            record(rotCount + 1);
        } else {
            record(rotCount);
        }
        return;
