using namespace std;

class Main {
public:
    void run() {
        InputReader in(cin);
        ostream& out = cout;

        int N = in.nextInt();
        int k = in.nextInt();
        vector<vector<int>> intervals;
        for (int i = 0; i < k; i++) {
            int a = in.nextInt();
            int b = in.nextInt();
            intervals.push_back({a, b});
        }
        intervals.push_back({2 * N, 2 * N});

        vector<vector<int>> dp(2, vector<int>(N + 1, (int)(1e9)));
        dp[0][0] = 0;

        int cur = 0;
        for (auto& interval : intervals) {
            int start = interval[0];
            int end = interval[1];
            int len = end - start;

            vector<vector<int>> nextDp(2, vector<int>(N + 1, (int)(1e9)));

            for (int j = 0; j <= N; j++) {
                if (j >= len) {
                    nextDp[0][j] = dp[0][j - len];
                }
            }
            cur = end;

            for (int j = 0; j <= N; j++) {
                for (int side = 0; side < 2; side++) {
                    int twoSwaps = getMin(dp[side], j - len, j);
                    int oneSwap = getMin(dp[1 - side], j - len, j);
                    int noSwap = (side == 1) ? dp[side][j] : (j >= len ? dp[side][j - len] : (int)(1e9));
                    nextDp[side][j] = min(twoSwaps + 2, min(oneSwap + 1, noSwap));
                }
            }

            dp = nextDp;
        }

        int ans = min(dp[0][N], dp[1][N]);
        if (ans >= (int)(1e9)) {
            out << "Hungry" << endl;
        } else {
            out << "Full" << endl;
            out << ans << endl;
        }
    }

private:
    int getMin(const vector<int>& arr, int l, int r) {
        if (r < 0) return (int)(1e9);
        int minVal = (int)(1e9);
        for (int i = max(0, l); i <= r; i++) {
            minVal = min(minVal, arr[i]);
        }
        return minVal;
    }

    class InputReader {
    private:
        istream& stream;

    public:
        InputReader(istream& s) : stream(s) {}

        string next() {
            string token;
            stream >> token;
            return token;
        }

        int nextInt() {
            return stoi(next());
        }
    };
};

int main() {
    Main mainInstance;
    mainInstance.run();
    return 0;
}

