using namespace std;

class F {
public:
    void solve() {
        int n, K;
        cin >> n >> K;

        vector<vector<int>> ts(K, vector<int>(2));
        for (int i = 0; i < K; i++) {
            cin >> ts[i][0] >> ts[i][1];
        }

        const int INF = 99999999;
        vector<int> dpe(n + 1, INF);
        vector<int> dpo(n + 1, INF);

        if (ts[0][0] > n) {
            cout << "Hungry" << endl;
            return;
        }
        dpe[ts[0][0]] = 0;

        for (int i = 0; i < K; i++) {
            vector<int> ndpo(n + 1, INF);
            vector<int> ndpe(n + 1, INF);

            deque<int> dq;
            int w = ts[i][1] - ts[i][0];

            for (int j = 0; j <= n; j++) {
                while (!dq.empty() && dpe[dq.back()] >= dpe[j]) {
                    dq.pop_back();
                }
                while (!dq.empty() && dq.front() < j - w) {
                    dq.pop_front();
                }
                dq.push_back(j);
                ndpo[j] = min(ndpo[j], dpe[dq.front()] + 1);
                if (j + w <= n) {
                    ndpe[j + w] = min(ndpe[j + w], dpe[j]);
                }
            }

            dq.clear();
            for (int j = 0; j <= n; j++) {
                while (!dq.empty() && dpo[dq.back()] >= dpo[j]) {
                    dq.pop_back();
                }
                while (!dq.empty() && dq.front() < j - w) {
                    dq.pop_front();
                }
                dq.push_back(j);
                ndpe[j] = min(ndpe[j], dpo[dq.front()] + 1);
                ndpo[j] = min(ndpo[j], dpo[j]);
            }

            dpo = ndpo;
            dpe = ndpe;

            for (int j = 0; j <= n; j++) {
                dpe[j] = min(dpe[j], dpo[j] + 1);
                dpo[j] = min(dpo[j], dpe[j] + 1);
            }

            int s = (i == K - 1 ? 2 * n : ts[i + 1][0]) - ts[i][1];
            for (int j = n; j >= s; j--) {
                dpe[j] = dpe[j - s];
            }
            for (int j = min(n, s - 1); j >= 0; j--) {
                dpe[j] = INF;
            }
        }

        int ans = min(dpe[n], dpo[n]);
        if (ans >= INF) {
            cout << "Hungry" << endl;
        } else {
            cout << "Full" << endl;
            cout << ans << endl;
        }
    }
};

