        if (i == 0) ONES[i] = 0;
        else ONES[i] = ONES[i-1] * 10 + 1;
    }
}

long long process(long long value) {
    if (value <= 6) return value;
    int len = std::to_string(value).length();
    long long rep = ONES[len];
    if (value == rep) return len;
    long long lower = rep;
    long long upper = ONES[len + 1];
    long long option1 = process(value % lower) + (value / lower) * len;
    long long option2 = LLONG_MAX;
    if (upper - value < value) {
        option2 = process(upper - value) + (len + 1);
    }
    return std::min(option1, option2);
}

int main() {
    initOnes();
    Scanner sc(std::cin);
    long long n = sc.nextLong();
    std::cout << process(n) << std::endl;
    return 0;
}

