import java.io.*;
import java.util.*;

public class Main {
  static class Input {
    private final BufferedReader br;
    private String[] tokens;
    private int pos;

    Input(InputStream in) {
      br = new BufferedReader(new InputStreamReader(in));
    }

    private void load() throws IOException {
      String line = br.readLine();
      if (line != null) {
        tokens = line.split("\\s+");
        pos = 0;
      }
    }

    String next() throws IOException {
      if (tokens == null || pos >= tokens.length) {
        load();
      }
      return tokens[pos++];
    }

    long nextLong() throws IOException {
      return Long.parseLong(next());
    }
  }

  static final long[] REPS = {
    0L, 1L, 11L, 111L, 1111L, 11111L, 111111L, 1111111L, 11111111L,
    111111111L, 1111111111L, 11111111111L, 111111111111L,
    1111111111111L, 11111111111111L, 111111111111111L, 1111111111111111L
  };

  public static void main(String[] args) throws Exception {
    Input in = new Input(System.in);
    long n = in.nextLong();
    System.out.println(solveProblem(n));
  }

  static long solveProblem(long x) {
    if (x <= 6) return x;
    int d = String.valueOf(x).length();
    long r = REPS[d];
    if (x == r) return d;
    long lo = r;
    long hi = REPS[d + 1];
    long option1 = solveProblem(x % lo) + (x / lo) * d;
    long option2 = Long.MAX_VALUE;
    if (hi - x < x) {
      option2 = solveProblem(hi - x) + (d + 1);
    }
    return Math.min(option1, option2);
  }
}

