        Point a, b;
        Segment(const Point& a, const Point& b) : a(a), b(b) {}

        bool contains(const Point& p, bool includeEnds) const {
            if (includeEnds && (p == a || p == b)) return true;
            if (a == b) return false;

            // Check if point is on the line
            double cross = (p.x - a.x) * (b.y - a.y) - (p.y - a.y) * (b.x - a.x);
            if (fabs(cross) > EPS) return false;

            // Check if point is within bounding box
            double minX = min(a.x, b.x), maxX = max(a.x, b.x);
            double minY = min(a.y, b.y), maxY = max(a.y, b.y);
            return p.x >= minX - EPS && p.x <= maxX + EPS && 
                   p.y >= minY - EPS && p.y <= maxY + EPS;
