        Point intersect(const Segment& other, bool includeEnds) const {
            double det = (b.x - a.x) * (other.b.y - other.a.y) - (b.y - a.y) * (other.b.x - other.a.x);
            if (fabs(det) < EPS) return Point(); // Parallel

            double t = ((other.b.x - other.a.x) * (a.y - other.a.y) - (other.b.y - other.a.y) * (a.x - other.a.x)) / det;
            double u = ((b.x - a.x) * (a.y - other.a.y) - (b.y - a.y) * (a.x - other.a.x)) / det;

            if (t >= -EPS && t <= 1 + EPS && u >= -EPS && u <= 1 + EPS) {
