        Segment segment(points[i], points[j]);

        // Check if segment contains any polygon vertex
        for (const auto& point : polygon.vertices) {
            if (segment.contains(point, false)) return dp[i][j] = 0;
        }

        // Check intersections with other edges
        for (int k = 0; k < i - 1; k++) {
            if (segment.intersect(Segment(points[k], points[k+1]), true) != Point()) return dp[i][j] = 0;
        }
        for (int k = i + 1; k < j - 1; k++) {
            if (segment.intersect(Segment(points[k], points[k+1]), true) != Point()) return dp[i][j] = 0;
        }
        for (int k = j + 1; k < points.size() - 1; k++) {
            if (segment.intersect(Segment(points[k], points[k+1]), true) != Point()) return dp[i][j] = 0;
        }

        if (i != 0 && j != 0 && i != points.size() - 1 && j != points.size() - 1) {
            if (segment.intersect(Segment(points[0], points[points.size()-1]), true) != Point()) return dp[i][j] = 0;
        }

        Point middle((points[i].x + points[j].x) / 2.0, (points[i].y + points[j].y) / 2.0);
        if (!polygon.contains(middle)) return dp[i][j] = 0;

        for (int k = i + 1; k < j; k++) {
            dp[i][j] = (dp[i][j] + dp(i, k) * dp(k, j) % MOD) % MOD;
        }

        return dp[i][j];
    }

