    }

    void print(double x) {
        writer << fixed << setprecision(10) << x;
    }

    void print(const vector<int>& arr) {
        for (int i = 0; i < arr.size(); i++) {
            if (i != 0) writer << ' ';
            writer << arr[i];
        }
    }

    void print(const vector<long long>& arr) {
        for (int i = 0; i < arr.size(); i++) {
            if (i != 0) writer << ' ';
            writer << arr[i];
        }
    }

    void print(const vector<double>& arr) {
