            if (i != 0) writer << ' ';
            writer << fixed << setprecision(10) << arr[i];
        }
    }

    void print(const vector<string>& arr) {
        for (int i = 0; i < arr.size(); i++) {
            if (i != 0) writer << ' ';
            writer << arr[i];
        }
    }

    void printLine() {
        writer << '\n';
    }

    void printLine(const string& s) {
        writer << s << '\n';
    }

    void printLine(int x) {
        writer << x << '\n';
    }

    void printLine(long long x) {
        writer << x << '\n';
    }

    void printLine(double x) {
