        int c = read();
        while (c != -1 && isspace(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        double res = 0;
        while (c != -1 && !isspace(c) && c != '.') {
            if (c == 'e' || c == 'E') return res * pow(10, readInt());
            if (c < '0' || c > '9') throw runtime_error("Input mismatch");
            res *= 10;
            res += c - '0';
            c = read();
        }
        if (c == '.') {
            c = read();
            double m = 1;
            while (c != -1 && !isspace(c)) {
                if (c == 'e' || c == 'E') return res * pow(10, readInt());
                if (c < '0' || c > '9') throw runtime_error("Input mismatch");
                m /= 10;
                res += (c - '0') * m;
                c = read();
            }
        }
        return res * sgn;
    }

    bool isExhausted() {
        int value;
        while (isSpaceChar(value = peek()) && value != -1) read();
        return value == -1;
    }

    string next() {
        return readString();
    }
};

