class x440C_v2 {
    static final long[] P = new long[16];

    static {
        P[0] = 1;
        for (int k = 1; k < 16; ++k) P[k] = P[k-1] * 10;
    }

    public static void main(String[] args) throws Exception {
        Scanner s = new Scanner(System.in);
        String str = s.nextLine().trim();
        long val = Long.parseLong(str);
        System.out.println(process(val));
    }

    static int process(long x) {
        if (x <= 11) {
            switch ((int)x) {
                case 11: return 2;
                case 10: return 3;
                case 9:  return 4;
                case 8:  return 5;
                case 7:  return 6;
                default: return (int)x;
            }
        }
        String sx = Long.toString(x);
        int digits = sx.length();
        long total = 0;
        for (int i = 0; i <= digits; ++i) total += P[i];
        int best = Integer.MAX_VALUE;
        long diff1 = total - x;
        if (x > diff1) {
            best = Math.min(best, digits + 1 + process(diff1));
        }
        total -= P[digits];
        long leading = x / P[digits-1];
        for (int d = 1; d <= 9; ++d) {
            long curr = total * d;
            if (d == leading || d + 1 == leading) {
                best = Math.min(best, d * digits + process(Math.abs(curr - x)));
            }
        }
        return best;
    }
}

