import java.util.*;
import java.io.*;

public class C {
    private static final int INF = (int)1e6;
    private static int[][][][] memo;
    private static String digits;

    private static int compute(int i, int p, int n, int c) {
        int tc = c - 50;
        if (i == 17) {
            return (p + n + tc == 0) ? 0 : INF;
        }
        if (memo[i][p][n][c] != -1) return memo[i][p][n][c];
        int minVal = INF;
        int limitP = Math.min(15, p);
        int limitN = Math.min(15, n);
        for (int x = 0; x <= limitP; x++) {
            for (int y = 0; y <= limitN; y++) {
                int s = p - n + tc;
                int curDigit = (s % 10 + 10) % 10;
                int nxtCarry = s > 0 ? s / 10 : (s - 9) / 10;
                if (curDigit != digits.charAt(i) - '0') continue;
                int val = compute(i + 1, p - x, n - y, nxtCarry + 50) + (x + y) * (i + 1);
                if (val < minVal) minVal = val;
            }
        }
        return memo[i][p][n][c] = minVal;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long val = Long.parseLong(br.readLine().trim());
        int cap = 50;
        memo = new int[20][cap][cap][100];
        for (int a = 0; a < 20; a++) {
            for (int b = 0; b < cap; b++) {
                for (int c = 0; c < cap; c++) {
                    Arrays.fill(memo[a][b][c], -1);
                }
            }
        }
        digits = String.valueOf(val);
        while (digits.length() < 17) digits = "0" + digits;
        digits = new StringBuilder(digits).reverse().toString();
        int result = INF;
        for (int pos = 0; pos < cap; pos++) {
            for (int neg = 0; neg < cap; neg++) {
                int candidate = compute(0, pos, neg, 50);
                if (candidate < result) result = candidate;
            }
        }
        System.out.println(result);
    }
}

