        adjList.resize(nodes);
        for (int i = 0; i < nodes; i++) adjList[i].clear();
        pi.assign(nodes, INF);
        d.assign(nodes, 0);
        prevNode.assign(nodes, 0);
        u.assign(edges, 0);
        v.assign(edges, 0);
        uv.assign(edges, 0);
        c.assign(edges, 0);
        cap.assign(edges * 2, 0);
        edgeCount = 0;
    }

    void connect(int from, int to, int capacity, int cost) {
        int idx = edgeCount++;
        u[idx] = from;
        v[idx] = to;
        uv[idx] = from ^ to;
        c[idx] = cost;
        cap[idx * 2] = capacity;
        adjList[from].push_back(idx * 2);
        adjList[to].push_back(idx * 2 + 1);
    }

    vector<int> q;
    int qHead, qTail, qLen;
    vector<bool> inQ;

    void enqueue(int x) {
        if (inQ[x]) return;
        if (qHead + qTail == (int)q.size()) {
            if (qLen * 2 <= (int)q.size()) {
                for (int i = 0; i < qLen; i++) {
                    q[i] = q[qHead + i];
                }
            } else {
                vector<int> nq(q.size() * 2);
                for (int i = 0; i < qLen; i++) {
                    nq[i] = q[qHead + i];
                }
                q = nq;
            }
            qHead = 0;
        }
        q[qHead + qTail++] = x;
        inQ[x] = true;
