                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int t = 0; t < T - 1; t++) {
                int u_node = i * T + t;
                int v_node = u_node + 1;
                connect(u_node, v_node, k, i == 0 ? 0 : c_val);
            }
