    struct Edge {
        int u, flow, rid, cost;
        Edge(int a, int b, int c, int d) : u(a), flow(b), cost(c), rid(d) {}
    };

    struct MinCostMaxFlow {
        vector<vector<Edge>> al;
        vector<vector<Edge>> ja;
        vector<int> d;
        int N, S, T, maxFlow, minCost;
        const int INF = INT_MAX / 100;

        MinCostMaxFlow(int n, int source, int sink) {
            N = n;
            S = source;
            T = sink;
            maxFlow = 0;
            minCost = 0;
            al.resize(N);
            d.resize(N);
        }

        void addEdge(int u, int v, int flow, int cost) {
            int lu = al[u].size(), lv = al[v].size();
            al[u].push_back(Edge(v, flow, cost, lv));
            al[v].push_back(Edge(u, 0, -cost, lu));
        }

        void convertToArray() {
            ja.resize(N);
            for (int i = 0; i < N; i++) {
                int sz = al[i].size();
                ja[i].resize(sz);
                for (int j = 0; j < sz; j++) {
                    ja[i][j] = al[i][j];
                }
                al[i].clear();
            }
        }

        bool BellmanFord(bool check) {
            fill(d.begin(), d.end(), INF);
            d[S] = 0;
            for (int i = 0; i < N - 1; i++) {
                for (int j = 0; j < N; j++) {
                    for (const Edge& e : ja[j]) {
                        if (e.flow == 0) continue;
                        if (d[j] != INF && d[e.u] > d[j] + e.cost) {
                            d[e.u] = d[j] + e.cost;
                        }
                    }
                }
            }
            if (check) {
                for (int j = 0; j < N; j++) {
                    for (const Edge& e : ja[j]) {
                        if (e.flow == 0) continue;
                        if (d[j] != INF && d[j] + e.cost < d[e.u]) return false;
                    }
                }
            }
            return true;
        }

        vector<int> node, visit, prv, prve, dist;

        bool simple() {
            node.resize(N);
            visit.resize(N, 0);
            prv.resize(N);
            prve.resize(N);
            dist.resize(N);
            fill(dist.begin(), dist.end(), INF);

            node[0] = S;
            dist[S] = 0;
            int front = 1, back = 0;
            while (front != back) {
                int u = node[back++];
                if (back == N) back = 0;
                visit[u] = 2;
                for (int i = 0; i < (int)ja[u].size(); i++) {
                    Edge e = ja[u][i];
                    if (e.flow == 0) continue;
                    int cdist = dist[u] + e.cost;
                    if (cdist < dist[e.u]) {
                        if (visit[e.u] == 0) {
                            node[front] = e.u;
                            if (++front == N) front = 0;
                        } else if (visit[e.u] == 2) {
                            if (--back == -1) back += N;
                            node[back] = e.u;
                        }
                        visit[e.u] = 1;
                        prve[e.u] = i;
                        prv[e.u] = u;
                        dist[e.u] = cdist;
                    }
                }
            }
            return visit[T] != 0;
        }

        struct Pair {
            int F, S;
            Pair(int a, int b) : F(a), S(b) {}
            bool operator<(const Pair& other) const {
                return S > other.S;
            }
        };

        bool dijkstra() {
            visit.resize(N, 0);
            prv.resize(N);
            prve.resize(N);
            dist.resize(N);
            fill(dist.begin(), dist.end(), INF);
            priority_queue<Pair> pq;

            pq.push(Pair(S, 0));
            dist[S] = 0;
            while (!pq.empty()) {
                Pair p = pq.top();
                pq.pop();
                while (dist[p.F] < p.S) {
                    if (pq.empty()) return false;
                    p = pq.top();
                    pq.pop();
                }
                visit[p.F] = 2;
                for (int i = 0; i < (int)ja[p.F].size(); i++) {
                    Edge e = ja[p.F][i];
                    if (e.flow == 0) continue;
                    int cdist = p.S + (e.cost + d[p.F] - d[e.u]);
                    if (cdist < dist[e.u]) {
                        if (visit[e.u] == 2) return false;
                        pq.push(Pair(e.u, cdist));
                        dist[e.u] = cdist;
                        prv[e.u] = p.F;
                        prve[e.u] = i;
                        visit[e.u] = 1;
                    }
                }
            }
