                        Edge& e = graph[u][i];
                        if (e.f >= e.cap)
                            continue;
                        int v = e.to;
                        int ndist = dist[u] + e.cost;
                        if (dist[v] > ndist) {
                            dist[v] = ndist;
                            prevnode[v] = u;
                            prevedge[v] = i;
                            curflow[v] = min(curflow[u], e.cap - e.f);
                            if (!inqueue[v]) {
                                inqueue[v] = true;
                                q[qt++ % n] = v;
                            }
                        }
                    }
                }
            }

            vector<int> minCostFlow(int s, int t, int maxf) {
                int n = graph->size();
                vector<int> dist(n);
                vector<int> curflow(n);
                vector<int> prevedge(n);
                vector<int> prevnode(n);

