            int n, m, k, c, d;
            sc >> n >> m >> k >> c >> d;

            vector<int> pos(n, 0);
            for (int i = 0; i < k; i++) {
                int x;
                sc >> x;
                pos[x - 1]++;
            }

            int T = 100;
            MinCostFlowBF mf((T + 1) * n + 2);

            for (int i = 0; i < n; i++) {
                if (pos[i] > 0)
                    mf.addEdge(0, i + 1, pos[i], 0);
            }

            for (int i = 0; i < T; i++) {
                for (int j = 0; j < n; j++) {
                    mf.addEdge(1 + i * n + j, 1 + (i + 1) * n + j, k, 0);
                }
            }

            for (int i = 0; i <= T; i++) {
                for (int j = 1; j <= k; j++) {
                    mf.addEdge(1 + i * n, (T + 1) * n + 1, 1, c * i);
                }
            }

            for (int i = 0; i < m; i++) {
                int a, b;
                sc >> a >> b;
                a--; b--;
                for (int j = 0; j < T; j++) {
                    int cost = 0;
                    for (int l = 1; l <= k; l++) {
                        mf.addEdge(1 + j * n + a, 1 + (j + 1) * n + b, 1, l * l * d - cost);
                        mf.addEdge(1 + j * n + b, 1 + (j + 1) * n + a, 1, l * l * d - cost);
                        cost = l * l * d;
                    }
                }
            }

            vector<int> flowAndCost = mf.minCostFlow(0, (T + 1) * n + 1, k);
            pw << flowAndCost[1] << endl;
        }
    };
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    Main::Task t;
    t.solve(cin, cout);

    return 0;
}

