                BellmanFord(false);
                while (simple()) {
                    if (dist[T] >= gmax - 1) break;
                    minCost += dist[T] * augment();
                }
                return true;
            }

            void updPotential() {
                for (int i = 0; i < N; i++) {
                    if (visit[i] != 0) {
                        d[i] += dist[i] - dist[S];
                    }
                }
            }

            bool calWithPotential() {
                BellmanFord(false);
                while (dijkstra()) {
                    int min = dist[T] + d[T] - d[S];
                    if (min >= gmax - 1) break;
                    minCost += min * augment();
                    updPotential();
                }
                return true;
            }
        };

        int n, m, k, c, d_val;
        vector<int> a, f;

        void solve(int testNumber, InputReader& in, ostream& out) {
            n = in.nextInt(); m = in.nextInt(); k = in.nextInt(); c = in.nextInt(); d_val = in.nextInt();
            int maxl = n + k, T = n * maxl + 1;
            MinCostMaxFlow ans(T + 1, 0, T);
            a.assign(k + 1, 0); f.assign(n + 1, 0);
            for (int i = 1; i <= k; i++) {
                a[i] = in.nextInt();
                f[a[i]]++;
            }
            for (int i = 1; i <= n; i++) {
                if (f[i] == 0) continue;
                ans.addEdge(0, i, f[i], 0);
            }
            for (int i = 2; i <= n; i++) {
                for (int l = 0; l < maxl - 1; l++) {
                    ans.addEdge(l * n + i, (l + 1) * n + i, k, c);
                }
            }
            for (int i = 1; i <= m; i++) {
                int u = in.nextInt(), v = in.nextInt();
                for (int l = 0; l < maxl - 1; l++) {
                    for (int p = 1; p <= k; p++) {
                        if (u != 1)
                            ans.addEdge(n * l + u, n * (l + 1) + v, 1, d_val * (2 * p - 1) + c);
                        if (v != 1)
                            ans.addEdge(n * l + v, n * (l + 1) + u, 1, d_val * (2 * p - 1) + c);
                    }
                }
            }
            for (int l = 1; l < maxl; l++) {
                ans.addEdge(l * n + 1, T, k, 0);
            }
            ans.convertToArray();
            ans.calWithPotential();
            if (ans.maxFlow != k) {
                out << "BUG" << endl;
            } else {
                out << (int)ans.minCost << endl;
            }
        }
    };
};

int main() {
    G g;
    g.run();
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstring>
#include <fstream>
#include <sstream>
#include <string>

using namespace std;

class G {
public:
    class Solver {
    public:
        class MinCostFlow {
        public:
            struct Edge {
                int to, cap, revIdx, w;
                Edge(int t, int c, int w, int r) : to(t), cap(c), w(w), revIdx(r) {}
            };

            vector<vector<Edge>> adj;
            vector<vector<Edge>> matrix;
            vector<int> dist;
            int nodes, source, sink, flow;
            int cost;
            const int INF = INT_MAX / 100;

            MinCostFlow(int n, int src, int tgt) {
                nodes = n;
                source = src;
                sink = tgt;
                flow = 0;
                cost = 0;
                adj.resize(nodes);
                dist.resize(nodes);
            }

            void addEdge(int u, int v, int cap, int w) {
                int su = adj[u].size(), sv = adj[v].size();
                adj[u].push_back(Edge(v, cap, w, sv));
                adj[v].push_back(Edge(u, 0, -w, su));
            }

            void buildMatrix() {
                matrix.resize(nodes);
                for (int i = 0; i < nodes; i++) {
                    matrix[i] = adj[i];
                    adj[i].clear();
                }
            }

            bool shortestPath(bool detectNeg) {
                fill(dist.begin(), dist.end(), INF);
                dist[source] = 0;
                for (int iter = 0; iter < nodes - 1; iter++) {
                    for (int u = 0; u < nodes; u++) {
                        if (dist[u] == INF) continue;
                        for (const Edge& e : matrix[u]) {
                            if (e.cap > 0 && dist[u] + e.w < dist[e.to]) {
                                dist[e.to] = dist[u] + e.w;
                            }
                        }
                    }
                }
                if (detectNeg) {
                    for (int u = 0; u < nodes; u++) {
                        if (dist[u] == INF) continue;
                        for (const Edge& e : matrix[u]) {
                            if (e.cap > 0 && dist[u] + e.w < dist[e.to]) return false;
                        }
                    }
                }
                return true;
            }

            vector<int> pnode, pedge, vis, distQ;
            vector<int> q;

            bool spfa() {
                pnode.resize(nodes);
                pedge.resize(nodes);
                vis.resize(nodes, 0);
                distQ.resize(nodes, INF);
                q.resize(nodes);
                fill(distQ.begin(), distQ.end(), INF);
                distQ[source] = 0;
                int head = 0, tail = 0;
                q[tail++] = source;
                while (head != tail) {
                    int u = q[head++];
                    if (head == nodes) head = 0;
                    vis[u] = 2;
                    for (int i = 0; i < matrix[u].size(); i++) {
                        Edge e = matrix[u][i];
                        if (e.cap == 0) continue;
                        int nd = distQ[u] + e.w;
                        if (nd < distQ[e.to]) {
                            if (vis[e.to] == 0) {
                                q[tail++] = e.to;
                                if (tail == nodes) tail = 0;
                            } else if (vis[e.to] == 2) {
                                if (--head == -1) head += nodes;
                                q[head] = e.to;
                            }
                            vis[e.to] = 1;
                            pedge[e.to] = i;
                            pnode[e.to] = u;
                            distQ[e.to] = nd;
                        }
                    }
                }
                return vis[sink] != 0;
            }

            struct P {
                int node, dist;
                P(int n, int d) : node(n), dist(d) {}
                bool operator<(const P& o) const {
                    return dist > o.dist;
                }
            };

            bool dijkstraP() {
                vis.assign(nodes, 0);
                distQ.assign(nodes, INF);
                pnode.resize(nodes);
                pedge.resize(nodes);
                priority_queue<P> pq;
                pq.push(P(source, 0));
                distQ[source] = 0;
                while (!pq.empty()) {
                    P cur = pq.top();
                    pq.pop();
                    while (distQ[cur.node] < cur.dist) {
                        if (pq.empty()) return false;
                        cur = pq.top();
                        pq.pop();
                    }
                    vis[cur.node] = 2;
                    for (int i = 0; i < matrix[cur.node].size(); i++) {
                        Edge e = matrix[cur.node][i];
                        if (e.cap == 0) continue;
                        int rcost = e.w + dist[cur.node] - dist[e.to];
                        int nd = cur.dist + rcost;
                        if (nd < distQ[e.to]) {
                            if (vis[e.to] == 2) return false;
                            pq.push(P(e.to, nd));
                            distQ[e.to] = nd;
                            pnode[e.to] = cur.node;
                            pedge[e.to] = i;
                            vis[e.to] = 1;
                        }
                    }
                }
                return vis[sink] != 0;
            }

            int augmentFlow() {
                int pathCap = INF;
                int cur = sink;
                while (cur != source) {
                    int prev = pnode[cur], idx = pedge[cur];
                    pathCap = min(pathCap, matrix[prev][idx].cap);
                    cur = prev;
                }
                cur = sink;
                while (cur != source) {
                    int prev = pnode[cur], idx = pedge[cur];
                    matrix[prev][idx].cap -= pathCap;
                    matrix[cur][matrix[prev][idx].revIdx].cap += pathCap;
                    cur = prev;
                }
                flow += pathCap;
                return pathCap;
            }

            void compute() {
                shortestPath(false);
                while (spfa()) {
                    if (distQ[sink] >= INF - 1) break;
                    cost += distQ[sink] * augmentFlow();
                }
            }

            void computeWithPot() {
                shortestPath(false);
                while (dijkstraP()) {
                    int m = distQ[sink] + dist[sink] - dist[source];
                    if (m >= INF - 1) break;
                    cost += m * augmentFlow();
                    for (int i = 0; i < nodes; i++) {
                        if (vis[i] != 0) dist[i] += distQ[i] - dist[source];
                    }
                }
            }
        };

        void process(int testNum, istream& in, ostream& out) {
            int n, m, k, c, d;
            in >> n >> m >> k >> c >> d;
            int maxLen = n + k;
            int dest = n * maxLen + 1;
            MinCostFlow g(dest + 1, 0, dest);
            vector<int> freq(n + 1, 0);
            vector<int> arr(k + 1);
            for (int i = 1; i <= k; i++) {
                in >> arr[i];
                freq[arr[i]]++;
            }
            for (int i = 1; i <= n; i++) {
                if (freq[i] > 0) g.addEdge(0, i, freq[i], 0);
            }
            for (int i = 2; i <= n; i++) {
                for (int lvl = 0; lvl < maxLen - 1; lvl++) {
                    g.addEdge(lvl * n + i, (lvl + 1) * n + i, k, c);
                }
            }
            for (int i = 1; i <= m; i++) {
                int u, v;
                in >> u >> v;
                for (int lvl = 0; lvl < maxLen - 1; lvl++) {
                    for (int p = 1; p <= k; p++) {
                        if (u != 1) g.addEdge(n * lvl + u, n * (lvl + 1) + v, 1, d * (2 * p - 1) + c);
                        if (v != 1) g.addEdge(n * lvl + v, n * (lvl + 1) + u, 1, d * (2 * p - 1) + c);
                    }
                }
            }
            for (int lvl = 1; lvl < maxLen; lvl++) {
                g.addEdge(lvl * n + 1, dest, k, 0);
            }
            g.buildMatrix();
            g.computeWithPot();
            if (g.flow != k) out << "BUG" << endl;
            else out << g.cost << endl;
        }
    };

    void start() {
        istream& in = cin;
        ostream& out = cout;
        Solver task;
        task.process(1, in, out);
    }
};

int main() {
    G g;
    g.start();
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstring>
#include <cmath>
#include <iomanip>
using namespace std;

typedef long long ll;

class G {
public:
    class Problem {
    public:
        struct Edge {
            int to, capacity, rev, cost;
            Edge(int t, int c, int w, int r) : to(t), capacity(c), cost(w), rev(r) {}
        };

        class FlowNetwork {
        public:
            vector<vector<Edge>> graph;
            int vertexCount, src, dest, totalFlow;
            ll minCost;
            const ll INF = (ll)1e15;

            FlowNetwork(int v, int s, int t) {
                vertexCount = v;
                src = s;
                dest = t;
                totalFlow = 0;
                minCost = 0;
                graph.resize(v);
            }

            void addConnection(int from, int to, int capacity, int cost) {
                Edge forward = Edge(to, capacity, cost, graph[to].size());
                Edge backward = Edge(from, 0, -cost, graph[from].size());
                graph[from].push_back(forward);
                graph[to].push_back(backward);
            }

            void prepareArrays() {
                int n = vertexCount;
                vector<vector<Edge>> temp(n);
                for(int i = 0; i < n; i++) {
                    temp[i] = graph[i];
                    graph[i].clear();
                }
                graph = temp;
            }

            bool buildDistances(bool detectNeg) {
                vector<ll> d(vertexCount, INF);
                d[src] = 0;
                for(int iter = 0; iter < vertexCount - 1; iter++) {
                    bool changed = false;
                    for(int u = 0; u < vertexCount; u++) {
                        if(d[u] == INF) continue;
                        for(Edge e : graph[u]) {
                            if(e.capacity > 0 && d[u] + e.cost < d[e.to]) {
                                d[e.to] = d[u] + e.cost;
                                changed = true;
                            }
                        }
                    }
                    if(!changed) break;
                }
                if(detectNeg) {
                    for(int u = 0; u < vertexCount; u++) {
                        if(d[u] == INF) continue;
                        for(Edge e : graph[u]) {
                            if(e.capacity > 0 && d[u] + e.cost < d[e.to]) return false;
                        }
                    }
                }
                return true;
            }

            vector<int> parentV, parentE, visited, dist;
            vector<int> queue;

            bool SPFA() {
                dist.assign(vertexCount, INT_MAX/2);
                parentV.assign(vertexCount, -1);
                parentE.assign(vertexCount, -1);
                visited.assign(vertexCount, 0);
                queue.assign(vertexCount, 0);
                dist[src] = 0;
                int head = 0, tail = 0;
                queue[tail++] = src;
                while(head != tail) {
                    int u = queue[head++];
                    if(head == vertexCount) head = 0;
                    visited[u] = 2;
                    for(int idx = 0; idx < graph[u].size(); idx++) {
                        Edge e = graph[u][idx];
                        if(e.capacity == 0) continue;
                        int nd = dist[u] + e.cost;
                        if(nd < dist[e.to]) {
                            if(visited[e.to] == 0) {
                                queue[tail++] = e.to;
                                if(tail == vertexCount) tail = 0;
                            } else if(visited[e.to] == 2) {
                                if(--head == -1) head += vertexCount;
                                queue[head] = e.to;
                            }
                            visited[e.to] = 1;
                            parentE[e.to] = idx;
                            parentV[e.to] = u;
                            dist[e.to] = nd;
                        }
                    }
                }
                return visited[dest] != 0;
            }

            struct Item {
                int node, priority;
                Item(int n, int p) : node(n), priority(p) {}
                bool operator<(const Item& o) const {
                    return priority > o.priority;
                }
            };

            bool dijkstraAlg() {
                visited.assign(vertexCount, 0);
                dist.assign(vertexCount, INT_MAX/2);
                parentV.assign(vertexCount, -1);
                parentE.assign(vertexCount, -1);
                fill(dist.begin(), dist.end(), INT_MAX/2);
                priority_queue<Item> pq;
                pq.push(Item(src, 0));
                dist[src] = 0;
                while(!pq.empty()) {
                    Item cur = pq.top();
                    pq.pop();
                    while(dist[cur.node] < cur.priority) {
                        if(pq.empty()) break;
                        cur = pq.top();
                        pq.pop();
                    }
                    if(dist[cur.node] != cur.priority) continue;
                    visited[cur.node] = 2;
                    for(int i = 0; i < graph[cur.node].size(); i++) {
                        Edge e = graph[cur.node][i];
                        if(e.capacity == 0) continue;
                        int reduced = e.cost + dist[cur.node] - dist[e.to];
                        int nd = cur.priority + reduced;
                        if(nd < dist[e.to]) {
                            if(visited[e.to] == 2) return false;
                            pq.push(Item(e.to, nd));
                            dist[e.to] = nd;
                            parentV[e.to] = cur.node;
                            parentE[e.to] = i;
                            visited[e.to] = 1;
                        }
                    }
                }
                return visited[dest] != 0;
            }

            int augmentPath() {
                int flow = INT_MAX;
                int cur = dest;
                while(cur != src) {
                    int prev = parentV[cur], idx = parentE[cur];
                    flow = min(flow, graph[prev][idx].capacity);
                    cur = prev;
                }
                cur = dest;
                while(cur != src) {
                    int prev = parentV[cur], idx = parentE[cur];
                    graph[prev][idx].capacity -= flow;
                    graph[cur][graph[prev][idx].rev].capacity += flow;
                    cur = prev;
                }
                totalFlow += flow;
                return flow;
            }

            void calculateMinCost() {
                buildDistances(false);
                while(SPFA()) {
                    if(dist[dest] >= INT_MAX/2) break;
                    minCost += (ll)dist[dest] * augmentPath();
                }
            }

            void calculateMinCostWithPotential() {
                buildDistances(false);
                while(dijkstraAlg()) {
                    ll m = (ll)dist[dest] + (ll)dist[dest] - (ll)dist[src];
                    if(m >= INT_MAX/2) break;
                    minCost += m * augmentPath();
                    for(int i = 0; i < vertexCount; i++) {
                        if(visited[i] != 0) dist[i] += dist[i] - dist[src];
                    }
                }
            }
        };

        void execute(int testNum, istream& in, ostream& out) {
            int n, m, k, c, d;
            in >> n >> m >> k >> c >> d;
            int maxLayers = n + k;
            int terminal = n * maxLayers + 1;
            FlowNetwork net(terminal + 1, 0, terminal);
            vector<int> occurrences(n + 1, 0), supplies(k + 1, 0);
            for(int i = 1; i <= k; i++) {
                in >> supplies[i];
                occurrences[supplies[i]]++;
            }
            for(int i = 1; i <= n; i++) {
                if(occurrences[i] > 0)
                    net.addConnection(0, i, occurrences[i], 0);
            }
            for(int i = 2; i <= n; i++) {
                for(int layer = 0; layer < maxLayers - 1; layer++) {
                    net.addConnection(layer * n + i, (layer + 1) * n + i, k, c);
                }
            }
            for(int i = 1; i <= m; i++) {
                int u, v;
                in >> u >> v;
                for(int layer = 0; layer < maxLayers - 1; layer++) {
                    for(int p = 1; p <= k; p++) {
                        if(u != 1)
                            net.addConnection(n * layer + u, n * (layer + 1) + v, 1, d * (2 * p - 1) + c);
                        if(v != 1)
                            net.addConnection(n * layer + v, n * (layer + 1) + u, 1, d * (2 * p - 1) + c);
                    }
                }
            }
            for(int layer = 1; layer < maxLayers; layer++) {
                net.addConnection(layer * n + 1, terminal, k, 0);
            }
            net.prepareArrays();
            net.calculateMinCostWithPotential();
            if(net.totalFlow != k)
                out << "BUG" << endl;
            else
                out << net.minCost << endl;
        }
    };

    void launch() {
        Problem p;
        p.execute(1, cin, cout);
    }

    int main() {
        launch();
        return 0;
    }
};

int main() {
    G g;
    g.launch();
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <iomanip>
#include <fstream>
#include <sstream>

using namespace std;

typedef long long ll;

struct Edge {
    int to, flow, rev, cost;
    Edge(int t, int f, int c, int r) : to(t), flow(f), cost(c), rev(r) {}
};

class NetworkFlow {
public:
    vector<vector<Edge>> graph;
    vector<vector<Edge>> mat;
    vector<int> dist;
    int V, src, sink, maxFlow;
    ll minCost;
    const ll INF = (ll)1e15;

    NetworkFlow(int nodes, int s, int t) {
        V = nodes; src = s; sink = t;
        maxFlow = 0; minCost = 0;
        graph.resize(V);
    }

    void addEdge(int u, int v, int cap, int cost) {
        Edge fwd(v, cap, cost, graph[v].size());
        Edge bkw(u, 0, -cost, graph[u].size());
        graph[u].push_back(fwd);
        graph[v].push_back(bkw);
    }

    void finalizeGraph() {
        mat.resize(V);
        for(int i = 0; i < V; i++) {
            mat[i] = graph[i];
            graph[i].clear();
        }
    }

    bool bellmanFord(bool check) {
        dist.assign(V, INT_MAX / 2);
        dist[src] = 0;
        for(int iter = 0; iter < V - 1; iter++) {
            bool updated = false;
            for(int u = 0; u < V; u++) {
                if(dist[u] == INT_MAX/2) continue;
                for(Edge& e : mat[u]) {
                    if(e.flow > 0 && dist[u] + e.cost < dist[e.to]) {
                        dist[e.to] = dist[u] + e.cost;
                        updated = true;
                    }
                }
            }
            if(!updated) break;
        }
        if(check) {
            for(int u = 0; u < V; u++) {
                if(dist[u] == INT_MAX/2) continue;
                for(Edge& e : mat[u]) {
                    if(e.flow > 0 && dist[u] + e.cost < dist[e.to]) return false;
                }
            }
        }
        return true;
    }

    vector<int> parNode, parEdge, visited, distSpfa;
    vector<int> queueSpfa;

    bool spfa() {
        distSpfa.assign(V, INT_MAX/2);
        parNode.assign(V, -1);
        parEdge.assign(V, -1);
        visited.assign(V, 0);
        queueSpfa.resize(V);
        distSpfa[src] = 0;
        int head = 0, tail = 0;
        queueSpfa[tail++] = src;
        while(head != tail) {
            int u = queueSpfa[head++];
            if(head == V) head = 0;
            visited[u] = 2;
            for(int i = 0; i < mat[u].size(); i++) {
                Edge& e = mat[u][i];
                if(e.flow == 0) continue;
                int nd = distSpfa[u] + e.cost;
                if(nd < distSpfa[e.to]) {
                    if(visited[e.to] == 0) {
                        queueSpfa[tail++] = e.to;
                        if(tail == V) tail = 0;
                    } else if(visited[e.to] == 2) {
                        if(--head == -1) head += V;
                        queueSpfa[head] = e.to;
                    }
                    visited[e.to] = 1;
                    parEdge[e.to] = i;
                    parNode[e.to] = u;
                    distSpfa[e.to] = nd;
                }
            }
        }
        return visited[sink] != 0;
    }

    struct NodeDist {
        int node, dist;
        NodeDist(int n, int d) : node(n), dist(d) {}
        bool operator<(const NodeDist& o) const {
            return dist > o.dist;
        }
    };

    bool dijkstra() {
        visited.assign(V, 0);
        distSpfa.assign(V, INT_MAX/2);
        parNode.assign(V, -1);
        parEdge.assign(V, -1);
        fill(distSpfa.begin(), distSpfa.end(), INT_MAX/2);
        distSpfa[src] = 0;
        priority_queue<NodeDist> pq;
        pq.push(NodeDist(src, 0));
        while(!pq.empty()) {
            NodeDist cur = pq.top();
            pq.pop();
            while(distSpfa[cur.node] < cur.dist) {
                if(pq.empty()) return false;
                cur = pq.top();
                pq.pop();
            }
            visited[cur.node] = 2;
            for(int i = 0; i < mat[cur.node].size(); i++) {
                Edge& e = mat[cur.node][i];
                if(e.flow == 0) continue;
                int redCost = e.cost + distSpfa[cur.node] - distSpfa[e.to];
                int nd = cur.dist + redCost;
                if(nd < distSpfa[e.to]) {
                    if(visited[e.to] == 2) return false;
                    pq.push(NodeDist(e.to, nd));
                    distSpfa[e.to] = nd;
                    parNode[e.to] = cur.node;
                    parEdge[e.to] = i;
                    visited[e.to] = 1;
                }
            }
        }
        return visited[sink] != 0;
    }

    int augment() {
        int flow = INT_MAX;
        int v = sink;
        while(v != src) {
            int u = parNode[v], idx = parEdge[v];
            flow = min(flow, mat[u][idx].flow);
            v = u;
        }
        v = sink;
        while(v != src) {
            int u = parNode[v], idx = parEdge[v];
            mat[u][idx].flow -= flow;
            mat[v][mat[u][idx].rev].flow += flow;
            v = u;
        }
        maxFlow += flow;
        return flow;
    }

    void computeFlow() {
        bellmanFord(false);
        while(spfa()) {
            if(distSpfa[sink] >= INT_MAX/2 - 1) break;
            minCost += distSpfa[sink] * augment();
        }
    }

    void computeFlowWithPotential() {
        bellmanFord(false);
        while(dijkstra()) {
            ll m = distSpfa[sink] + distSpfa[sink] - distSpfa[src];
            if(m >= INT_MAX/2LL) break;
            minCost += m * augment();
            for(int i = 0; i < V; i++) {
                if(visited[i] != 0) {
                    distSpfa[i] += distSpfa[i] - distSpfa[src];
                }
            }
        }
    }
};

class Task {
public:
    void run(int test, istream& in, ostream& out) {
        int n, m, k, c, d;
        in >> n >> m >> k >> c >> d;
        int maxLayers = n + k;
        int terminal = n * maxLayers + 1;
        NetworkFlow net(terminal + 1, 0, terminal);
        vector<int> freq(n + 1, 0), items(k + 1);
        for(int i = 1; i <= k; i++) {
            in >> items[i];
            freq[items[i]]++;
        }
        for(int i = 1; i <= n; i++) {
            if(freq[i] > 0)
                net.addEdge(0, i, freq[i], 0);
        }
        for(int i = 2; i <= n; i++) {
            for(int layer = 0; layer < maxLayers - 1; layer++) {
                net.addEdge(layer * n + i, (layer + 1) * n + i, k, c);
            }
        }
        for(int i = 1; i <= m; i++) {
            int u, v;
            in >> u >> v;
            for(int layer = 0; layer < maxLayers - 1; layer++) {
                for(int p = 1; p <= k; p++) {
                    if(u != 1)
                        net.addEdge(layer * n + u, (layer + 1) * n + v, 1, d * (2 * p - 1) + c);
                    if(v != 1)
                        net.addEdge(layer * n + v, (layer + 1) * n + u, 1, d * (2 * p - 1) + c);
                }
            }
        }
        for(int layer = 1; layer < maxLayers; layer++) {
            net.addEdge(layer * n + 1, terminal, k, 0);
        }
        net.finalizeGraph();
        net.computeFlowWithPotential();
        if(net.maxFlow != k)
            out << "BUG" << endl;
        else
            out << net.minCost << endl;
    }
};

