#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstring>
#include <string>
#include <sstream>

using namespace std;

class G {
public:
    class Problem;

    void begin() {
        Problem problem;
        problem.run(1, cin, cout);
    }

    class Problem {
    public:
        class MinCostFlow {
        private:
            struct Edge {
                int to, cap, rev, cost;
                Edge(int t, int c, int w, int r) : to(t), cap(c), cost(w), rev(r) {}
            };

            vector<vector<Edge>> adj;
            vector<vector<Edge>> edgeMatrix;
            vector<int> potential;
            int N, source, sink, flow;
            long long totalCost;
            const int INF = INT_MAX / 2;

            vector<int> prevNode, prevEdge, visited, distArray;
            vector<int> queueBuffer;

        public:
            MinCostFlow(int nodes, int s, int t) {
                N = nodes; source = s; sink = t;
                flow = 0; totalCost = 0;
                adj.resize(N);
                potential.resize(N, 0);
            }

            void addEdge(int u, int v, int capacity, int weight) {
                Edge forward = Edge(v, capacity, weight, adj[v].size());
                Edge backward = Edge(u, 0, -weight, adj[u].size());
                adj[u].push_back(forward);
                adj[v].push_back(backward);
            }

            void packEdges() {
                edgeMatrix.resize(N);
                for(int i = 0; i < N; i++) {
                    edgeMatrix[i] = adj[i];
                    adj[i].clear();
                }
            }

            void initializePotential() {
                fill(potential.begin(), potential.end(), INF);
                potential[source] = 0;
                bool changed = true;
                for(int iter = 0; iter < N && changed; iter++) {
                    changed = false;
                    for(int u = 0; u < N; u++) {
                        if(potential[u] == INF) continue;
                        for(const Edge& e : edgeMatrix[u]) {
                            if(e.cap > 0 && potential[u] + e.cost < potential[e.to]) {
                                potential[e.to] = potential[u] + e.cost;
                                changed = true;
                            }
                        }
                    }
                }
            }

            bool performSPFA() {
                distArray.resize(N);
                prevNode.resize(N);
                prevEdge.resize(N);
                visited.resize(N, 0);
                queueBuffer.resize(N);
                fill(distArray.begin(), distArray.end(), INF);
                distArray[source] = 0;
                int head = 0, tail = 0;
                queueBuffer[tail++] = source;
                while(head != tail) {
                    int u = queueBuffer[head++];
                    if(head == N) head = 0;
                    visited[u] = 2;
                    for(int idx = 0; idx < edgeMatrix[u].size(); idx++) {
                        Edge& e = edgeMatrix[u][idx];
                        if(e.cap == 0) continue;
                        int nd = distArray[u] + e.cost;
                        if(nd < distArray[e.to]) {
                            if(visited[e.to] == 0) {
                                queueBuffer[tail++] = e.to;
                                if(tail == N) tail = 0;
                            } else if(visited[e.to] == 2) {
                                if(--head == -1) head += N;
                                queueBuffer[head] = e.to;
                            }
                            visited[e.to] = 1;
                            prevEdge[e.to] = idx;
                            prevNode[e.to] = u;
                            distArray[e.to] = nd;
                        }
                    }
                }
                return visited[sink] != 0;
            }

            struct P {
                int node, priority;
                P(int n, int p) : node(n), priority(p) {}
                bool operator<(const P& other) const {
                    return priority > other.priority;
                }
            };

            bool dijkstraWithPotential() {
                visited.assign(N, 0);
                distArray.assign(N, INF);
                prevNode.assign(N, 0);
                prevEdge.assign(N, 0);
                fill(distArray.begin(), distArray.end(), INF);
                distArray[source] = 0;
                priority_queue<P> pq;
                pq.push(P(source, 0));
                while(!pq.empty()) {
                    P current = pq.top();
                    pq.pop();
                    while(distArray[current.node] < current.priority) {
                        if(pq.empty()) return false;
                        current = pq.top();
                        pq.pop();
                    }
                    visited[current.node] = 2;
                    for(int i = 0; i < edgeMatrix[current.node].size(); i++) {
                        Edge& e = edgeMatrix[current.node][i];
                        if(e.cap == 0) continue;
                        int reducedCost = e.cost + distArray[current.node] - distArray[e.to];
                        int newDist = current.priority + reducedCost;
                        if(newDist < distArray[e.to]) {
                            if(visited[e.to] == 2) return false;
                            pq.push(P(e.to, newDist));
                            distArray[e.to] = newDist;
                            prevNode[e.to] = current.node;
                            prevEdge[e.to] = i;
                            visited[e.to] = 1;
                        }
                    }
                }
                return visited[sink] != 0;
            }

            int augmentFlow() {
                int pathFlow = INF;
                int node = sink;
                while(node != source) {
                    int parent = prevNode[node], idx = prevEdge[node];
                    pathFlow = min(pathFlow, edgeMatrix[parent][idx].cap);
                    node = parent;
                }
                node = sink;
                while(node != source) {
                    int parent = prevNode[node], idx = prevEdge[node];
                    edgeMatrix[parent][idx].cap -= pathFlow;
                    edgeMatrix[node][edgeMatrix[parent][idx].rev].cap += pathFlow;
                    node = parent;
                }
                flow += pathFlow;
                return pathFlow;
            }

            void runAlgorithm() {
                initializePotential();
                while(performSPFA()) {
                    if(distArray[sink] >= INF - 1) break;
                    totalCost += (long long)distArray[sink] * augmentFlow();
                }
            }

            void runAlgorithmWithPotential() {
                initializePotential();
                while(dijkstraWithPotential()) {
                    long long reducedCost = distArray[sink] + (long long)distArray[sink] - distArray[source];
                    if(reducedCost >= INF) break;
                    totalCost += reducedCost * augmentFlow();
                    for(int i = 0; i < N; i++) {
                        if(visited[i] != 0) {
                            potential[i] += distArray[i] - distArray[source];
                        }
                    }
                }
            }

            int getFlow() { return flow; }
            long long getTotalCost() { return totalCost; }
        };

        void run(int test, istream& in, ostream& out) {
            int n, m, k, c, d;
            in >> n >> m >> k >> c >> d;
            int maxLevels = n + k;
            int sinkNode = n * maxLevels + 1;
            MinCostFlow network(sinkNode + 1, 0, sinkNode);
            vector<int> freq(n + 1, 0), positions(k + 1);
            for(int i = 1; i <= k; i++) {
                in >> positions[i];
                freq[positions[i]]++;
            }
            for(int i = 1; i <= n; i++) {
                if(freq[i] > 0)
                    network.addEdge(0, i, freq[i], 0);
            }
            for(int i = 2; i <= n; i++) {
                for(int level = 0; level < maxLevels - 1; level++) {
                    network.addEdge(level * n + i, (level + 1) * n + i, k, c);
                }
            }
            for(int i = 1; i <= m; i++) {
                int u, v;
                in >> u >> v;
                for(int level = 0; level < maxLevels - 1; level++) {
                    for(int p = 1; p <= k; p++) {
                        if(u != 1)
                            network.addEdge(level * n + u, (level + 1) * n + v, 1, d * (2 * p - 1) + c);
                        if(v != 1)
                            network.addEdge(level * n + v, (level + 1) * n + u, 1, d * (2 * p - 1) + c);
                    }
                }
            }
            for(int level = 1; level < maxLevels; level++) {
                network.addEdge(level * n + 1, sinkNode, k, 0);
            }
            network.packEdges();
            network.runAlgorithmWithPotential();
            if(network.getFlow() != k)
                out << "BUG" << endl;
            else
                out << network.getTotalCost() << endl;
        }
    };
};

int main() {
    G instance;
    instance.begin();
    return 0;
}

