        auto it = lower_bound(primes.begin(), primes.end(), limit);
        int u = it - primes.begin();
        if (u >= (int)primes.size() || primes[u] > limit) u--;
        for (int i = u; i >= 0; i--) {
            dfs1(n / primes[i], i, K, qs, primes, ct);
        }
    }
