    vector<long long> allocated;
    int scale;
    int rscale;
    int mask;
    int size;

    static const long long NG = 0;

    LongHashCounterL() {
        scale = 1 << 2;
        rscale = 1 << 1;
        mask = scale - 1;
        size = 0;
        allocated.resize(scale, NG);
        keys.resize(scale, 0);
    }

    int h(long long x) {
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdLL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53LL;
        x ^= x >> 33;
        return (int)x;
    }

    bool containsKey(long long x) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) return true;
            pos = (pos + 1) & mask;
        }
        return false;
    }

    long long get(long long x) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) return allocated[pos];
            pos = (pos + 1) & mask;
        }
        return NG;
    }

    long long put(long long x, long long v) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) {
                long long oldval = allocated[pos];
                allocated[pos] = v;
                return oldval;
            }
            pos = (pos + 1) & mask;
        }
        if (size == rscale) {
            resizeAndPut(x, v);
        } else {
            keys[pos] = x;
            allocated[pos] = v;
        }
        size++;
        return 0;
    }

    void resizeAndPut(long long x, long long v) {
        int nscale = scale << 1;
        int nrscale = rscale << 1;
        int nmask = nscale - 1;
        vector<long long> nallocated(nscale, NG);
        vector<long long> nkeys(nscale, 0);
        for (int i = next(0); i < scale; i = next(i + 1)) {
            long long y = keys[i];
            int pos = h(y) & nmask;
            while (nallocated[pos] != NG) pos = (pos + 1) & nmask;
            nkeys[pos] = y;
            nallocated[pos] = allocated[i];
        }
        {
            int pos = h(x) & nmask;
            while (nallocated[pos] != NG) pos = (pos + 1) & nmask;
            nkeys[pos] = x;
            nallocated[pos] = v;
        }
        allocated = nallocated;
        keys = nkeys;
        scale = nscale;
        rscale = nrscale;
        mask = nmask;
    }

    int next(int itr) {
        while (itr < scale && allocated[itr] == NG) itr++;
        return itr;
    }
};

class MeisselLehmer2 {
public:
