    LongHashCounterL picache;
    LongHashCounterL phicache;
    bool cachePhi = true;

    vector<vector<int>> cumps;
    vector<int> FP;
    int M;

    int B = 100;

    MeisselLehmer2(long long n) {
        assert(n >= 4);
        picache = LongHashCounterL();
        phicache = LongHashCounterL();

        int s = (int)(sqrt(n) * B);
        cachelimit = s;
        this->primes = sieveEratosthenes(s);
        xcums.resize((s >> 6) + 1, 0);
        isp.resize((s >> 6) + 1, 0);
        for (int p : primes) isp[p >> 6] |= 1LL << p;
        for (int i = 0; i < (int)xcums.size() - 1; i++) {
            xcums[i + 1] = xcums[i] + __builtin_popcountll(isp[i]);
        }

        FP = {2, 3, 5, 7, 11, 13, 17, 19};
        M = FP.size();
        cumps.resize(M);
        vector<bool> b = {true};
        int len = 1;
        for (int i = 0; i < M; i++) {
            len *= FP[i];
            vector<bool> c(len, false);
            for (int j = 0; j < FP[i]; j++) {
                for (int k = 0; k < (int)b.size(); k++) {
                    c[j * b.size() + k] = b[k];
                }
            }
            for (int k = 0; k < len; k += FP[i]) c[k] = false;
            cumps[i].resize(len + 1, 0);
            for (int j = 0; j < len; j++) {
                cumps[i][j + 1] = cumps[i][j] + (c[j] ? 1 : 0);
            }
            FP[i] = len;
            b = c;
        }
    }

    long long sqrtll(long long n) {
        long long i = max(0LL, (long long)sqrt(n) - 2);
        while (i * i <= n) i++;
        return i - 1;
    }

    long long cbrtll(long long n) {
        long long i = max(0LL, (long long)cbrt(n) - 2);
        while (i * i * i <= n) i++;
        return i - 1;
    }

    long long pi(long long x) {
        if (x <= cachelimit) {
            int ix = (int)x;
            return xcums[ix >> 6] + __builtin_popcountll(isp[ix >> 6] << (~ix & 63));
        }
        if (picache.containsKey(x)) return picache.get(x);

        int A = (int)pi(sqrtll(sqrtll(x)));
        long long ret = A + phi(x, A) - P2(x, A) - P3(x, A) - 1;
        picache.put(x, ret);
        return ret;
    }

    long long phi(long long x, int A) {
        if (A > 0 && A - 1 < M) {
            return cumps[A - 1][FP[A - 1]] * (x / FP[A - 1]) + cumps[A - 1][(int)(x % FP[A - 1] + 1)];
        }
        if (A > 0 && x <= (long long)primes[A - 1] * primes[A - 1]) {
            return pi(x) - A + 1;
        }
        long long code = x << 13 | A;
        if (phicache.containsKey(code)) return phicache.get(code);

        long long ret = x;
        for (int i = A - 1; i >= 0; i--) ret -= phi(x / primes[i], i);

        if (cachePhi) phicache.put(code, ret);
        return ret;
    }

    long long P2(long long x, int A) {
        int B = (int)pi(sqrtll(x));
        long long ret = 0;
        for (int i = A; i < B; i++) {
            ret += pi(x / primes[i]);
        }
        ret -= (long long)(B - A) * (B + A - 1) / 2;
        return ret;
    }

    long long P3(long long x, int A) {
        int C = (int)pi(cbrtll(x));
        long long ret = 0;
        for (int i = A; i < C; i++) {
            long long xi = x / primes[i];
            int B = (int)pi(sqrtll(xi));
            for (int j = i; j < B; j++) {
                ret += pi(xi / primes[j]) - j;
            }
        }
