long long solve_case() {
    long long n;
    cin >> n;
    long long ans = 0;
    if (n <= 10) {
        if (n >= 6) ans++;
        if (n >= 8) ans++;
        if (n >= 10) ans++;
        return ans;
    }

    MeisselLehmer2 ml(n / 2);
    for (int i = 0; i < (int)primes.size(); i++) {
        long long plus = ml.pi(n / primes[i]) - (i + 1);
        if (plus <= 0) break;
        ans += plus;
    }

    for (int p : primes) {
        if ((long long)p * p * p <= n) {
            ans++;
        } else {
            break;
        }
    }
    return ans;
