const int MOD = 998244353;

long long modPow(long long a, long long b) {
    long long ans = 1;
    while (b > 0) {
        if ((b & 1) != 0) ans = (ans * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return ans;
}

class InputReader {
public:
    istream& in;

    InputReader(istream& stream) : in(stream) {}

    string next() {
        string token;
        in >> token;
        return token;
    }

    int nextInt() {
        return stoi(next());
    }

    long long nextLong() {
        return stoll(next());
    }

    bool hasNext() {
        return in.peek() != EOF;
    }
};

void solve() {
    InputReader in(cin);
    int n = in.nextInt(), k = in.nextInt(), l = in.nextInt();

    vector<long long> fac(n + 1);
    fac[0] = 1;
    for (int i = 1; i <= n; i++) {
        fac[i] = fac[i - 1] * i % MOD;
    }

    vector<vector<long long>> dp(2 * n + 1, vector<long long>(2 * n + 2, 0));
    dp[0][0] = 1;

    for (int i = 1; i <= 2 * n; i++) {
        for (int j = 0; j <= i; j++) {
            if (j > 0) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
            }
            dp[i][j] = (dp[i][j] + dp[i - 1][j + 1] * (j + 1) % MOD) % MOD;
        }
    }

    long long ans = 0;
    for (int i = k; i <= 2 * n; i++) {
        for (int j = k; j <= n; j++) {
            ans = (ans + dp[i][j] * dp[2 * n - i][j] % MOD * fac[j] % MOD) % MOD;
        }
    }

    long long result = (long long)l * ans % MOD;
    result = result * modPow(dp[2 * n][0], MOD - 2) % MOD;
    result = result * modPow(2 * n + 1, MOD - 2) % MOD;

    cout << result << endl;
}

int main() {
    solve();
    return 0;
}

