                long long term = modMul(matrix[t - 1][c], c);
                term = modMul(term, invTable[2 * n - t]);
                matrix[t][c - 1] = (matrix[t][c - 1] + term) % MOD;
            }

            if (c < upperCurr) {
                long long term = modMul(matrix[t - 1][c], (2 * n - t - c));
                term = modMul(term, invTable[2 * n - t]);
                matrix[t][c + 1] = (matrix[t][c + 1] + term) % MOD;
            }
        }
    }

    long long result = 0;
    for (int t = 0; t < 2 * n; t++) {
        for (int c = k; c <= n; c++) {
            result = (result + matrix[t][c]) % MOD;
        }
    }

    result = modMul(result, l_val);
    result = modMul(result, invTable[2 * n + 1]);
    cout << result << endl;

    return 0;
}

