ll modPow(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

vector<vector<int>> enumFIF(int n, int mod) {
    vector<int> f(n + 1);
    vector<int> invf(n + 1);
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        f[i] = (int)(((long long)f[i - 1] * i) % mod);
    }

    // Compute modular inverse of f[n] using extended Euclidean algorithm
    long long a = f[n];
    long long b = mod;
    long long p = 1, q = 0;
    while (b > 0) {
        long long c = a / b;
        long long d;
        d = a;
        a = b;
        b = d % b;
        d = p;
        p = q;
        q = d - c * q;
    }
    if (p < 0) p += mod;
    invf[n] = (int)p;

    for (int i = n - 1; i >= 0; i--) {
        invf[i] = (int)(((long long)invf[i + 1] * (i + 1)) % mod);
    }

    return {f, invf};
}

ll C(int n, int r, int mod, const vector<vector<int>>& fif) {
    if (n < 0 || r < 0 || r > n) return 0;
    return ((long long)fif[0][n] * fif[1][r] % mod) * fif[1][n - r] % mod;
}

int main() {
