    int mod = MOD;
    vector<vector<int>> fif = enumFIF(10000, mod);

    vector<ll> muls(n + 1, 0);
    for (int i = K; i <= n; i++) {
        ll m = C(n, i, mod, fif);
        for (int j = i; j <= n; j++) {
            ll term = m * C(n - i, n - j, mod, fif) % mod;
            if ((j - i) % 2 == 1) {
                term = mod - term; // subtract
            }
            muls[j] = (muls[j] + term) % mod;
        }
    }

    ll ans = 0;
