        ll term5 = muls[i];

        ll add = term1 * term2 % mod;
        add = add * term3 % mod;
        add = add * term4 % mod;
        add = add * term5 % mod;

        ans = (ans + add) % mod;
    }

    if (ans < 0) ans += mod;
    ans = ans * L % mod;

    cout << ans << endl;

    return 0;
}

