        for (int i = max - 1; i >= 0; i--) {
            invFact[i] = (int)((long long)invFact[i + 1] * (i + 1) % mod);
        }
        return {fact, invFact};
    }

    static int modPow(int base, int exp, int mod) {
        int result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (int)((long long)result * base % mod);
            base = (int)((long long)base * base % mod);
            exp >>= 1;
        }
        return result;
    }

    class InputReader {
    private:
        InputStream* stream;
        vector<char> buf;
        int curChar, numChars;

    public:
        InputReader(InputStream* stream) : stream(stream), buf(1024) {
            curChar = 0;
            numChars = 0;
        }

        int read() {
            if (numChars == -1) throw runtime_error("EOF");
            if (curChar >= numChars) {
                curChar = 0;
                numChars = stream->sgetn(buf.data(), buf.size());
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw runtime_error("Invalid number");
                res = res * 10 + c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sign;
        }

        bool isSpaceChar(int c) { return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1; }
    };

    void run() {
        InputReader in(&cin);
        int n = in.nextInt();
        int K = in.nextInt();
        int L = in.nextInt();

        vector<vector<int>> fif = precomputeFactorials(10000, MOD);
        vector<long long> muls(n + 1, 0);

        for (int i = K; i <= n; i++) {
            long long comb = nCk(n, i, MOD, fif);
            for (int j = i; j <= n; j++) {
                long long term = comb * nCk(n - i, n - j, MOD, fif) % MOD;
                if ((j - i) % 2 == 1) term = (MOD - term) % MOD;
                muls[j] = (muls[j] + term) % MOD;
            }
        }

        long long ans = 0;
        for (int i = K; i <= n; i++) {
            long long term = pow(2, i, MOD)
                    * fif[0][i] % MOD
                    * fif[1][i] % MOD
                    * fif[1][(2LL * i + 1) % MOD] % MOD
                    * muls[i] % MOD;
            ans = (ans + term) % MOD;
        }

        ans = (ans * L) % MOD;
        if (ans < 0) ans += MOD;
        cout << ans << endl;
    }
};

int main() {
    F_v1 solver;
    solver.run();
    return 0;
}

