long long binomial(int n, int k, const vector<int>& fact, const vector<int>& invFact) {
    if (k < 0 || k > n) return 0;
    return ((long long)fact[n] * invFact[k] % MOD) * invFact[n - k] % MOD;
}

class FastReader {
public:
    string line;
    int pos;

    FastReader() : pos(0) {}

    string next() {
        while (pos >= line.size() || line.empty()) {
            getline(cin, line);
            pos = 0;
        }
        while (pos < line.size() && line[pos] == ' ') pos++;
        int start = pos;
        while (pos < line.size() && line[pos] != ' ') pos++;
        return line.substr(start, pos - start);
    }

    int nextInt() {
        return stoi(next());
    }
};

int main() {
    FastReader fr;
    int n = fr.nextInt();
    int K = fr.nextInt();
    int L = fr.nextInt();

    vector<vector<int>> precomputed = computeFactorialArrays(10000);
    vector<int> factorials = precomputed[0];
    vector<int> invFactorials = precomputed[1];

    vector<long long> contributionArr(n + 1, 0);

    for (int i = K; i <= n; i++) {
        long long baseC = binomial(n, i, factorials, invFactorials);
        for (int j = i; j <= n; j++) {
            long long inner = binomial(n - i, n - j, factorials, invFactorials);
            long long product = (baseC * inner) % MOD;
            if (((j - i) & 1) == 1) product = (MOD - product) % MOD;
            contributionArr[j] = (contributionArr[j] + product) % MOD;
        }
    }

    long long ans = 0;
    for (int i = K; i <= n; i++) {
        if (contributionArr[i] == 0) continue;

        long long part1 = modExp(2, i, MOD);
        long long part2 = factorials[i];
        long long part3 = invFactorials[i];
        long long part4 = invFactorials[2 * i + 1];

        long long t = part1 * part3 % MOD;
        t = t * part3 % MOD;
        t = t * part4 % MOD;
        t = t * contributionArr[i] % MOD;

        ans = (ans + t) % MOD;
    }

    ans = ans * L % MOD;
    if (ans < 0) ans += MOD;
    cout << ans << endl;

    return 0;
}

