const long long MOD = 998244353;

class MathUtils {
public:
    static long long extended_gcd(long long a, long long b, long long &x, long long &y) {
        if (a == 0) {
            x = 0;
            y = 1;
            return b;
        }
        long long x1, y1;
        long long gcd = extended_gcd(b % a, a, x1, y1);
        x = y1 - (b / a) * x1;
        y = x1;
        return gcd;
    }

    static long long inverse(long long a, long long mod) {
        long long x, y;
        long long g = extended_gcd(a, mod, x, y);
        if (g != 1) {
            return 0;
        } else {
            x = (x % mod + mod) % mod;
            return x;
        }
    }

    static long long modFraction(long long a, long long b, long long mod) {
        long long invB = inverse(b, mod);
        if (invB == 0) {
            return -1;
        } else {
            return (invB * (a % mod)) % mod;
        }
    }

    static long long mod(long long a, long long mod) {
        a %= mod;
        if (a < 0) a += mod;
        return a;
    }
};

class InputReader {
public:
    istream& reader;
    string buffer;
    size_t pos;

    InputReader(istream& stream) : reader(stream), pos(0) {}

    string next() {
        while (true) {
            if (pos >= buffer.size()) {
                if (!getline(reader, buffer)) {
                    throw runtime_error("EOF");
                }
                pos = 0;
            }
            while (pos < buffer.size() && isspace(buffer[pos])) {
                pos++;
            }
            if (pos >= buffer.size()) continue;
            size_t start = pos;
            while (pos < buffer.size() && !isspace(buffer[pos])) {
                pos++;
            }
            return buffer.substr(start, pos - start);
        }
    }

    int nextInt() {
        return stoi(next());
    }
