            throw runtime_error("Input mismatch exception");
        }
        if (curChar >= numChars) {
            curChar = 0;
            stream.read(buf, sizeof(buf));
            numChars = stream.gcount();
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
