        long long res = 0;
        long long prob = 1;
        for (int i = 0; i <= maxJ; i++) {
            res = (res + dp[k][i] * prob % MOD) % MOD;
            prob = prob * invm % MOD;
        }
        w << res << endl;
    }
};

