/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author svilen.marchev@gmail.com
 */
public class Main {
  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputReader in = new InputReader(inputStream);
    PrintWriter out = new PrintWriter(outputStream);
    TaskF solver = new TaskF();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskF {
    int n;
    char[] s;
    int[] ugliness;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
      n = in.readInt();
      s = in.readString().toCharArray();
      ugliness = new int[n];
      for (int i = 0; i < n; ++i) {
        ugliness[i] = -in.readInt();
      }

      Graph graph = new Graph(1 + 26 + n / 2 + 1);
      for (char c = 'a'; c <= 'z'; ++c) {
        for (int i = 0; i < n / 2; ++i) {
          int cost = 0;
          if (c == s[i]) {
            cost = Math.min(cost, ugliness[i]);
          }
          if (c == s[n - 1 - i]) {
            cost = Math.min(cost, ugliness[n - 1 - i]);
          }
          graph.addFlowWeightedEdge(1 + (c - 'a'), 1 + 26 + i, cost, 1);
        }
      }

      int[] occurs = new int[128];
      for (int i = 0; i < n; ++i) occurs[s[i]]++;
      for (char c = 'a'; c <= 'z'; ++c) {
        graph.addFlowWeightedEdge(0, 1 + (c - 'a'), 0, occurs[c]);
      }

      for (int i = 0; i < n / 2; ++i) {
        graph.addFlowWeightedEdge(1 + 26 + i, 1 + 26 + n / 2, 0, 2);
      }

      Pair<Long, Long> flow = MinCostFlow.minCostMaxFlow(graph, 0, 1 + 26 + n / 2, true, n);
      out.println(-flow.first);
    }

  }

  static class Pair<U, V> implements Comparable<Pair<U, V>> {
    public final U first;
    public final V second;

    public static <U, V> Pair<U, V> makePair(U first, V second) {
      return new Pair<U, V>(first, second);
    }

    private Pair(U first, V second) {
      this.first = first;
      this.second = second;
    }


    public boolean equals(Object o) {
      if (this == o) {
        return true;
      }
      if (o == null || getClass() != o.getClass()) {
        return false;
      }

      Pair pair = (Pair) o;

      return !(first != null ? !first.equals(pair.first) : pair.first != null) &&
          !(second != null ? !second.equals(pair.second) : pair.second != null);
    }


    public int hashCode() {
      int result = first != null ? first.hashCode() : 0;
      result = 31 * result + (second != null ? second.hashCode() : 0);
      return result;
    }


    public String toString() {
      return "(" + first + "," + second + ")";
    }

    @SuppressWarnings({"unchecked"})
    public int compareTo(Pair<U, V> o) {
      int value = ((Comparable<U>) first).compareTo(o.first);
      if (value != 0) {
        return value;
      }
      return ((Comparable<V>) second).compareTo(o.second);
    }

  }

  static class IntegerUtils {
    public static int longCompare(long a, long b) {
      if (a < b) {
        return -1;
      }
      if (a > b) {
        return 1;
      }
      return 0;
    }

  }

  static interface IntStream extends Iterable<Integer>, Comparable<IntStream> {
    public IntIterator intIterator();

    default public Iterator<Integer> iterator() {
      return new Iterator<Integer>() {
        private IntIterator it = intIterator();

        public boolean hasNext() {
          return it.isValid();
        }

        public Integer next() {
          int result = it.value();
          it.advance();
          return result;
        }
      };
    }

    default public int compareTo(IntStream c) {
      IntIterator it = intIterator();
      IntIterator jt = c.intIterator();
      while (it.isValid() && jt.isValid()) {
        int i = it.value();
        int j = jt.value();
        if (i < j) {
          return -1;
        } else if (i > j) {
          return 1;
        }
        it.advance();
