    long long weight(int id) { return !weight.empty() ? weight[id] : 0; }
    long long capacity(int id) { return !capacity.empty() ? capacity[id] : 0; }

    void pushFlow(int id, long long f) {
        if (f == 0) return;
        capacity[id] -= f;
        capacity[id ^ 1] += f;
    }

    bool isSparse() { return vertexCount == 0 || (ll)edgeCount * 20 / vertexCount <= vertexCount; }
};

class MinCostFlow {
private:
    const Graph* g;
    int src, dst;
    vector<ll> phi;
    vector<ll> dist;
    vector<int> prev;
    int n;
    vector<int> visited;
    int visitIdx;

    void fordBellman() {
        fill(phi.begin(), phi.end(), LLONG_MAX);
        phi[src] = 0;
        vector<bool> inQ(n, false);
        vector<int> q(n + 1);
        int head = 0, tail = 0;
        q[tail++] = src;
        inQ[src] = true;
        int steps = 0, maxSteps = 2 * n * n;
        while (head != tail) {
            int u = q[head++];
            if (head == n) head = 0;
            inQ[u] = false;
            for (int e = g->firstOutbound(u); e != -1; e = g->nextOutbound(e)) {
                if (g->capacity(e) == 0) continue;
                int v = g->destination(e);
