    }

    static pll minCostMaxFlow(const Graph& g, int s, int d, bool hasNeg, long long maxF) {
        return MinCostFlow(g, s, d, hasNeg).run(maxF);
    }

    pll run(long long maxF) {
        ll cost = 0, flow = 0;
        while (maxF > 0) {
            dijkstra();
