class MinCostFlow {
private:
    const Graph* g;
    int src, dst;
    vector<ll> phi;
    vector<ll> dist;
    vector<int> prev;
    int n;
    vector<int> visited;
    int visitIdx;

    void fordBellman() {
        fill(phi.begin(), phi.end(), LLONG_MAX);
        phi[src] = 0;
        vector<bool> inQ(n, false);
        vector<int> q(n + 1);
        int head = 0, tail = 0;
        q[tail++] = src;
        inQ[src] = true;
        int steps = 0, maxSteps = 2 * n * n;
        while (head != tail) {
            int u = q[head++];
            if (head == n) head = 0;
            inQ[u] = false;
            for (int e = g->firstOutbound(u); e != -1; e = g->nextOutbound(e)) {
                if (g->capacity(e) == 0) continue;
                int v = g->destination(e);
                ll nd = phi[u] + g->weight(e);
                if (phi[v] > nd) {
                    phi[v] = nd;
                    if (!inQ[v]) {
                        q[tail++] = v;
                        inQ[v] = true;
                        if (tail == n) tail = 0;
                    }
                }
            }
            if (++steps > maxSteps) throw runtime_error("Negative cycle");
