            dd[j] = min(dd[j], dd[i] + ww[h]);
        }
        for (int h = 0; h < m_; h++) {
            int i = ii[h], j = jj[h];
            ww_[h] = ww[h] + dd[i] - dd[j];
        }
        int f = 0;
        while (dijkstra(s, t)) {
            f += trace(s, t);
            for (int h = 0; h < m_; h++) {
                int i = ii[h], j = jj[h];
                if (dd[i] != INF && dd[j] != INF) {
                    ww_[h] += dd[i] - dd[j];
                }
            }
        }
        int cost = 0;
        for (int h = 0; h < m_; h++)
            cost += ww[h] * cc[h << 1 | 1];
        return cost;
    }

