struct Char {
    char chr;
    int val;
    int idx;

    Char(char c, int v, int i) : chr(c), val(v), idx(i) {}
};

bool isAntiPalindrome(const std::vector<char>& chars) {
    int n = chars.size();
    for (int i = 0; i < n/2; i++) {
        if (chars[i] == chars[n - i - 1]) {
            return false;
        }
    }
    return true;
}

void swapChars(std::vector<char>& chars, std::vector<int>& vals, int i, int j) {
    char tmp = chars[i];
    chars[i] = chars[j];
    chars[j] = tmp;

    int tmpVal = vals[i];
    vals[i] = vals[j];
    vals[j] = tmpVal;
}

int main() {
    int n;
    std::cin >> n;
    std::cin.ignore();

    std::string s;
    std::getline(std::cin, s);
    s.erase(0, s.find_first_not_of(" \t\r\n"));
    s.erase(s.find_last_not_of(" \t\r\n") + 1);

    std::vector<char> chars(s.begin(), s.end());

    std::vector<int> vals(n);
    for (int i = 0; i < n; i++) {
        std::cin >> vals[i];
    }
    std::cin.ignore();

    std::vector<Char> wrongChars;
    std::vector<Char> chars1;

    for (int i = 0; i < n / 2; i++) {
        if (vals[i] > vals[n - i - 1]) {
            swapChars(chars, vals, i, n - i - 1);
        }

        Char chr(chars[i], vals[i], i);
        if (chars[i] == chars[n - i - 1]) {
            wrongChars.push_back(chr);
        }
        chars1.push_back(chr);
    }

    std::sort(chars1.begin(), chars1.end(), [](const Char& a, const Char& b) {
        return a.val < b.val;
    });

