    int numChars;

public:
    InputReader(std::istream& stream) : stream(stream), buf(1024), curChar(0), numChars(0) {}

    int read() {
        if (numChars == -1) {
            throw std::runtime_error("Input mismatch exception");
        }
        if (curChar >= numChars) {
            curChar = 0;
            stream.read(buf.data(), buf.size());
            numChars = stream.gcount();
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    int readInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
