                throw std::runtime_error("Input mismatch exception");
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    std::string readString() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        std::string res;
        do {
            if (c >= 0 && c < 128) {
                res += static_cast<char>(c);
