			}
			when[s] = left;

			for (int i = n - 1; i > 0; i--) {
				if (s < k) {
					s += i;
					if (s >= n) {
						s -= n;
					}
				} else {
					s -= i;
					if (s < 0) {
						s += n;
					}
				}
			}

		}

