        std::vector<int> a(n);
        for (int i = 0; i < n; i++) {
            a[i] = i;
        }
        for (int i = n - 1; i > 0; i--) {
            for (int j = 0; j < n; j++) {
                int delta = a[j] < m ? 1 : -1;
                a[j] = (a[j] + n + i * delta) % n;
            }
        }
        return maxDepth(a);
    }

    int maxDepth(const std::vector<int>& p) {
        int n = p.size();
        std::vector<int> used(n, -1);
        int ret = 0;
        for (int i = 0; i < n; i++) {
            int cur = 0;
            int v = i;
            while (used[v] != i) {
                used[v] = i;
                cur++;
                v = p[v];
            }
            ret = std::max(ret, cur);
        }
        return ret;
    }

