                ret = ret * 10 + (b - '0');
            } else {
                if (b != -1 && !isTrash(b)) {
                    throw std::runtime_error("Input mismatch");
                }
                return neg ? -ret : ret;
            }
            b = readByte();
        }
    }

private:
    std::vector<char> buf;
    size_t bufSz = 0, bufPtr = 0;

    int readByte() {
        if (bufSz == -1)
            throw std::runtime_error("Reading past EOF");
        if (bufPtr >= bufSz) {
            bufPtr = 0;
            bufSz = fread(buf.data(), 1, buf.size(), stdin);
            if (bufSz <= 0)
                return -1;
        }
        return buf[bufPtr++];
    }

    bool isTrash(int c) {
        return c < 33 || c > 126;
    }

    int skip() {
        int b;
        while ((b = readByte()) != -1 && isTrash(b))
            ;
        return b;
    }

    std::string nextToken() {
        int b = skip();
        std::string sb;
        while (!isTrash(b)) {
            sb += static_cast<char>(b);
            b = readByte();
        }
        return sb;
    }

    std::string nextString() {
        int b = readByte();
        std::string sb;
        while (!isTrash(b) || b == ' ') {
            sb += static_cast<char>(b);
            b = readByte();
        }
        return sb;
    }

    double nextDouble() {
        return std::stod(nextToken());
    }

    char nextChar() {
        return static_cast<char>(skip());
    }
};

