    void prepareFactorials(int maxN) {
        fact.resize(maxN + 1);
        invFact.resize(maxN + 1);
        fact[0] = 1;
        for (int i = 1; i <= maxN; i++) {
            fact[i] = multiply(fact[i - 1], i);
        }
        invFact[maxN] = modPow(fact[maxN], MOD - 2);
        for (int i = maxN - 1; i >= 0; i--) {
            invFact[i] = multiply(invFact[i + 1], i + 1);
        }
    }

    long long binomial(int n, int r) {
        if (r < 0 || r > n) return 0;
        return multiply(fact[n], multiply(invFact[r], invFact[n - r]));
    }

    long long modularInverse(int x) {
        return multiply(invFact[x], fact[x - 1]);
    }

    long long sum(long long a, long long b) {
        long long res = a + b;
        return res >= MOD ? res - MOD : res;
    }

    long long difference(long long a, long long b) {
        long long res = a - b;
        return res < 0 ? res + MOD : res;
    }

    long long multiply(long long a, long long b) {
        return (a * b) % MOD;
    }

private:
    long long modPow(long long base, long long exp) {
        long long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = multiply(result, base);
            base = multiply(base, base);
            exp >>= 1;
        }
        return result;
    }
};

