        if (r < 0 || r > n) return 0;
        return multiply(factorial[n], multiply(inverseFactorial[r], inverseFactorial[n - r]));
    }

    long long getSmallInverse(int x) {
        return multiply(inverseFactorial[x], factorial[x - 1]);
