    }

    long long multiply(long long a, long long b, long long c) {
        return multiply(multiply(a, b), c);
    }

private:
    long long modularExponentiation(long long base, long long exponent) {
        long long result = 1;
        base %= MOD;
        while (exponent > 0) {
