const long long MOD = 998244353LL;

class Mod998 {
public:
    vector<long long> fact;
    vector<long long> invFact;

    void setup(int maxN) {
        fact.resize(maxN);
        invFact.resize(maxN);
        fact[0] = 1;
        for (int i = 1; i < maxN; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        invFact[maxN - 1] = modPow(fact[maxN - 1], MOD - 2);
        for (int i = maxN - 2; i >= 0; i--) {
            invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
        }
    }

    long long C(int n, int r) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    long long inv(int x) {
        return modPow(x, MOD - 2);
    }

    long long inc(long long a, long long b) {
        a += b;
        return a >= MOD ? a - MOD : a;
    }

    long long dec(long long a, long long b) {
        a -= b;
        return a < 0 ? a + MOD : a;
    }

    long long prod(long long a, long long b) {
        return (a * b) % MOD;
    }

private:
    long long modPow(long long base, long long exp) {
        long long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
};

class Solver {
public:
    Mod998 mod;

    void run(int testNum, istream& in, ostream& out) {
        int n, m;
        in >> n >> m;
        mod.setup(n + m + 10);

        long long totalPhases = 1;
        long long term = 1;
        for (int i = 0; term != 0; i++) {
            long long a = mod.prod(n - i, mod.inv(n + m - i));
            term = mod.prod(term, a);
            totalPhases = mod.inc(totalPhases, term);
        }

        long long ans = 0;
        for (int k = 1; k <= n; k++) {
            long long phases = mod.prod(m + k, mod.inv(k));
            long long expVal = mod.prod(phases, totalPhases);
            long long val = mod.prod(mod.C(n, k), expVal);

            if ((k & 1) == 1) {
                ans = mod.inc(ans, val);
            } else {
                ans = mod.dec(ans, val);
            }
        }

        out << ans << endl;
    }
};

