const long long MOD = 998244353LL;

class CardShuffleProblem {
private:
    vector<long long> fact;
    vector<long long> invFact;

    long long add(long long a, long long b) {
        a += b;
        return a >= MOD ? a - MOD : a;
    }

    long long subtract(long long a, long long b) {
        a -= b;
        return a < 0 ? a + MOD : a;
    }

    long long multiply(long long a, long long b) {
        return (a * b) % MOD;
    }

    long long modPow(long long base, long long exp) {
        long long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    long long modInverse(int x) {
        return modPow(x, MOD - 2);
    }

    long long binomial(int n, int r) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

public:
    void precompute(int limit) {
        fact.resize(limit);
        invFact.resize(limit);
        fact[0] = 1;
        for (int i = 1; i < limit; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        invFact[limit - 1] = modPow(fact[limit - 1], MOD - 2);
        for (int i = limit - 2; i >= 0; i--) {
            invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
        }
    }

    void compute(int testNo, int n, int m) {
        precompute(n + m + 1);

        long long phaseCount = 1;
        long long current = 1;
        for (int i = 0; current != 0; i++) {
            long long term1 = multiply(n - i, modInverse(n + m - i));
            current = multiply(current, term1);
            phaseCount = add(phaseCount, current);
        }

        long long result = 0;
        for (int k = 1; k <= n; k++) {
            long long phases = multiply(m + k, modInverse(k));
            long long expectation = multiply(phases, phaseCount);
            long long contribution = multiply(binomial(n, k), expectation);

            if ((k & 1) == 1)
                result = add(result, contribution);
            else
                result = subtract(result, contribution);
        }

        cout << result << endl;
    }
};

int main() {
    int n, m;
    cin >> n >> m;

    CardShuffleProblem solver;
    solver.compute(1, n, m);

    return 0;
}

