class Mod998;

class Modulo {
protected:
    std::vector<int> factorials;
    std::vector<int> invFactorials;

public:
    Modulo() {
        factorials.push_back(1);
        invFactorials.push_back(1);
    }

    virtual long long modulus() = 0;

    long long add(long long a, long long b) {
        long long sum = a + b;
        return sum < modulus() ? sum : sum - modulus();
    }

    long long subtract(long long a, long long b) {
        long long diff = a - b;
        return diff < 0 ? diff + modulus() : diff;
    }

    long long multiply(long long a, long long b) {
        return (a * b) % modulus();
    }

    long long inverse(long long value) {
        long long g = modulus(), x = 0, y = 1;
        for (long long r = value; r != 0; ) {
            long long q = g / r;
            g %= r;
            long long temp = g;
            g = r;
            r = temp;
            x -= q * y;
            temp = x;
            x = y;
            y = temp;
        }
        long long result = x % modulus();
        return result < 0 ? result + modulus() : result;
    }

    friend class Mod998;
};

class IntBuffer {
private:
    std::vector<int> storage;
    int position = 0;

public:
    IntBuffer() {
        storage.resize(8);
    }

    void push(int value) {
        if (position >= (int)storage.size()) {
            storage.resize(storage.size() * 2);
        }
        storage[position++] = value;
    }

    int size() {
        return position;
    }

    int get(int index) {
        return storage[index];
    }
};

class Mod998 : public Modulo {
public:
    void ensureCapacity(int needed) {
        while ((int)factorials.size() <= needed) {
            int size = factorials.size();
            long long next = multiply(factorials[size - 1], size);
            factorials.push_back((int)next);
        }
        while ((int)invFactorials.size() <= needed) {
            int size = invFactorials.size();
            long long inv = inverse(factorials[size]);
            invFactorials.push_back((int)inv);
        }
    }

    long long getReciprocal(int x) {
        return multiply(invFactorials[x], factorials[x - 1]);
    }

    long long binomial(int n, int r) {
        if (r < 0 || r > n) return 0;
        return multiply(factorials[n], multiply(invFactorials[r], invFactorials[n - r]));
    }

    long long modulus() override {
        return 998244353LL;
    }
};

class InputReader {
private:
    std::string line;
    std::istringstream stream;
    bool hasLine;

public:
    InputReader(std::istream& input) {
        hasLine = false;
    }

    std::string next() {
        if (!hasLine) {
            if (!std::getline(std::cin, line)) {
                throw std::runtime_error("No more input");
            }
            stream.str(line);
            stream.clear();
        }

        std::string token;
        if (!(stream >> token)) {
            hasLine = false;
            return next();
        }
        return token;
    }

    int nextInt() {
        return std::stoi(next());
    }
};

int main() {
    InputReader reader(std::cin);
    int n = reader.nextInt();
    int m = reader.nextInt();

    Mod998 mod;
    mod.ensureCapacity(n + m);

    long long phaseCount = 1;
    long long currentProduct = 1;
    for (int i = 0; currentProduct != 0; i++) {
        currentProduct = mod.multiply(currentProduct, n - i);
        currentProduct = mod.multiply(currentProduct, mod.getReciprocal(n + m - i));
        phaseCount = mod.add(phaseCount, currentProduct);
    }

    long long result = 0;
    for (int k = 1; k <= n; k++) {
        long long phases = mod.multiply(m + k, mod.getReciprocal(k));
        long long term = mod.multiply(mod.binomial(n, k), mod.multiply(phases, phaseCount));
        result = ((k & 1) == 1) ? mod.add(result, term) : mod.subtract(result, term);
    }

    std::cout << result << std::endl;

    return 0;
}

