        r -= offset * total;
        int span = (r - l + 1) / total;
        if (span > 2) {
            r -= (span - 2) * total;
        }
        int diff = a > b ? a - b : 1;

        // Build base pattern
        for (int c = 0; c < cycles; c++) {
            for (int k = 0; k < a - diff; k++) {
