int countDistinctInSegment(int a, int b, int l, int r, const vector<char>& pattern) {
    int period = a + b;
    vector<char> fullPattern(3 * period);

    for (int i = 0; i < 3; i++) {
        vector<char> prefix(a);
        // Generate prefix pattern
        bool used[26] = {false};
        for (int j = i * period; j < (i + 1) * period && j > 0; j++) {
            if (j - 1 >= 0 && j - 1 < (int)fullPattern.size()) {
                used[fullPattern[j-1] - 'a'] = true;
            }
        }

        char current = 'a';
        for (int j = 0; j < a; j++) {
            while (used[current - 'a']) {
                current++;
            }
            prefix[j] = current++;
        }

        // Copy prefix to fullPattern
        copy(prefix.begin(), prefix.end(), fullPattern.begin() + i * period);
        // Fill the rest with pattern[i]
        fill(fullPattern.begin() + i * period + a, fullPattern.begin() + (i + 1) * period, pattern[i]);
    }

    int startOffset = l % period;
    int length = r - l + 1;
    vector<char> window(length);

    // Copy from fullPattern starting at startOffset
    for (int i = 0; i < length; i++) {
        if (startOffset + i < (int)fullPattern.size()) {
            window[i] = fullPattern[startOffset + i];
        } else {
            // If we go beyond fullPattern, we need to wrap around
            // But since we have 3 periods, this shouldn't happen for reasonable inputs
            window[i] = 'a'; // fallback
        }
    }

    bool seen[26] = {false};
    for (char ch : window) {
        if (ch >= 'a' && ch <= 'z') {
            seen[ch - 'a'] = true;
        }
    }

    int count = 0;
    for (int i = 0; i < 26; i++) {
        if (seen[i]) count++;
    }
    return count;
}

