using namespace std;

bool contains(int* arr, int val, int lo, int hi) {
    for (int i = lo; i <= hi; i++) {
        if (arr[i] == val) return true;
    }
    return false;
}

int determine(int a, int b, int l, int r) {
    int span = r - l + 1;
    if (span > 2 * (a + b)) {
        return a <= b ? a + 1 : 2 * a - b;
    }

    int* basePattern = new int[3 * (a + b) + 2];
    memset(basePattern, 0, sizeof(int) * (3 * (a + b) + 2));
    int lastValue = 0;

    // First segment: 1 to a
    for (int i = 1; i <= a; i++) {
        basePattern[i] = i;
        lastValue = i;
    }

    // Second segment: a+1 to a+b
    for (int i = a + 1; i <= a + b; i++) {
        basePattern[i] = lastValue;
    }

    // Third segment: a+b+1 to a+b+a
    for (int i = a + b + 1; i <= a + b + a; i++) {
        int candidate = 1;
        while (contains(basePattern, candidate, a + 1, i - 1)) {
            candidate++;
        }
        basePattern[i] = candidate;
        lastValue = candidate;
    }

    // Fourth segment: a+b+a+1 to a+b+a+b
    for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
        basePattern[i] = lastValue;
    }

    // Fifth segment: repeat
    for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
        basePattern[i] = basePattern[i - (a + b)];
    }

    // Count distinct values in range
    bool* observed = new bool[25];
    memset(observed, false, sizeof(bool) * 25);
    int start = l % (a + b);
    if (start == 0) start = a + b;
    int end = r - l + start;
    if (end < start) end += a + b;

    for (int i = start; i <= end; i++) {
        observed[basePattern[i]] = true;
    }

    int distinctCount = 0;
    for (int i = 1; i <= 24; i++) {
        if (observed[i]) distinctCount++;
    }

    delete[] basePattern;
    delete[] observed;

    return distinctCount;
}

int main() {
    int a, b, l, r;
    cin >> a >> b >> l >> r;
    cout << determine(a, b, l, r) << endl;
    return 0;
}

