            return str;
        } else {
            std::string remaining;
            std::getline(stream, remaining);
            return remaining;
        }
    }
};

void executePattern(std::vector<int>& seq, int a, int b, int r) {
    int period = a + b;
    for (int i = a; i < r; i++) {
        if (i % period < a) {
            std::set<int> used;
            for (int j = i - 1; i - j <= a; j--) {
                used.insert(seq[j]);
            }

            for (int j = 0; i % period != a && i < r; i++, j++) {
                while (used.find(j) != used.end()) {
                    j++;
                }
                used.insert(j);
                seq[i] = j;
            }
        } else {
            seq[i] = seq[i - 1];
        }
    }
}

int getUniqueCount(const std::vector<int>& seq, int l, int r) {
    std::set<int> set;
    for (int i = l; i < r; i++) {
        set.insert(seq[i]);
    }
    return set.size();
}

int main() {
    MyScanner sc(std::cin);
    int a = sc.nextInt();
    int b = sc.nextInt();
    int l = sc.nextInt() - 1;
    int r = sc.nextInt();

    int period = a + b;
    int base = (l / period) * period;
    r -= base;
    l -= base;

    if (r > period * 3) {
        int adjust = (r / period) * period;
        r -= adjust;
        r += period * 3;
    }

    std::vector<int> seq(r);
    for (int i = 0; i < r; i++) seq[i] = i;

    executePattern(seq, a, b, r);
    int result = getUniqueCount(seq, l, r);

    int bound = std::min(a + b, std::min(r, b));
    for (int i = a; i < bound; i++) {
        seq[i] = seq[b];
    }

    executePattern(seq, a, b, r);
    result = std::min(result, getUniqueCount(seq, l, r));

    std::cout << result << std::endl;

    return 0;
}

