                String suffix = buildSuffix(base, a);
                String tail = repeat((char) ('a' + s), b);
                String full = base + mid + suffix + tail;

                int len = full.length();
                Set<Integer> distinct = new HashSet<>();
                for (long i = l % len; i <= r % len; i = (i + 1) % len) {
                    distinct.add(full.charAt((int) i) - 'a');
                    if (i == r % len) break;
                }
                minDistinct = Math.min(minDistinct, distinct.size());
            }
        }

        System.out.println(minDistinct);
    }

    private static String buildBase(int a) {
        return IntStream.range(0, a)
                .mapToObj(i -> String.valueOf((char) ('a' + i)))
                .collect(Collectors.joining());
    }

    private static String repeat(char c, int count) {
        return new String(new char[count]).replace('\0', c);
    }

    private static String buildSuffix(String base, int a) {
        boolean[] used = new boolean[26];
        for (char c : base.toCharArray()) {
            used[c - 'a'] = true;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a; i++) {
            int next = 0;
            while (used[next]) next++;
            sb.append((char) ('a' + next));
            used[next] = true;
        }
        return sb.toString();
    }
}

