public:
    LightScanner(istream& input) : in(&input), buffer(""), pos(0) {}

    string string() {
        if (pos >= buffer.size()) {
            if (!getline(*in, buffer)) {
                throw runtime_error("No more input");
            }
            pos = 0;
        }

        while (pos < buffer.size() && isspace(buffer[pos])) {
            pos++;
