        if (bufferLen == -1) throw std::runtime_error("EOF");
        if (bufferPos >= bufferLen) {
            bufferPos = 0;
            bufferLen = stream.readsome(buffer, sizeof(buffer));
            if (bufferLen <= 0) return -1;
        }
        return buffer[bufferPos++];
    }

    int readInt() {
        int c = read();
