        for (char q = (char)('a' + a); q <= 'z'; q++) {
            std::string s = makeString(a, b, p, q);
            int unique = countUniqueChars(s, l, r);
            best = std::min(best, unique);
        }
    }

    out.printLine(best);
    out.flush();

    return 0;
}

#include <iostream>
