using namespace std;

string createPattern(int a, int b, char p, char q) {
    string sb = "";

    for (int i = 0; i < a; i++) {
        sb += (char)('a' + i);
    }

    for (int i = 0; i < b; i++) {
        sb += p;
    }

    for (int i = 0; i < a; i++) {
        vector<bool> used(26, false);
        int start = b;
        int end = b + a + i;

        for (int j = start; j < end && j < (int)sb.length(); j++) {
            used[sb[j] - 'a'] = true;
        }

        for (int j = 0; j < 26; j++) {
            if (!used[j]) {
                sb += (char)('a' + j);
                break;
            }
        }
    }

    for (int i = 0; i < b; i++) {
        sb += q;
    }

    return sb;
}

int getDistinctCount(string pattern, int l, int r) {
    vector<bool> seen(26, false);
    int len = pattern.length();
    int range = r - l + 1;

    if (range >= 100000) {
        for (int i = 0; i < len; i++) {
            seen[pattern[i] - 'a'] = true;
        }
    } else {
        for (int i = l; i <= r; i++) {
            seen[pattern[i % len] - 'a'] = true;
        }
    }

    int count = 0;
    for (bool b : seen) {
        if (b) count++;
    }
    return count;
}

int main() {
    string line;
    getline(cin, line);

    vector<int> input;
    string num = "";
    for (char c : line) {
        if (c == ' ') {
            if (!num.empty()) {
                input.push_back(stoi(num));
                num = "";
            }
        } else {
            num += c;
        }
    }
    if (!num.empty()) {
        input.push_back(stoi(num));
    }

    int a = input[0];
    int b = input[1];
    int l = input[2] - 1;
    int r = input[3] - 1;

    int minDistinct = 26;

    for (char p = 'a'; p <= 'z'; p++) {
        for (char q = (char)('a' + a); q <= 'z'; q++) {
            string pattern = createPattern(a, b, p, q);
            int distinct = getDistinctCount(pattern, l, r);
            if (distinct < minDistinct) minDistinct = distinct;
        }
    }

    cout << minDistinct << endl;

    return 0;
}

