using namespace std;

class FastScanner {
public:
    BufferedReader br;
    StringTokenizer st;

    FastScanner() : br(), st() {}

    string next() {
        while (!st.hasMoreTokens()) {
            string line;
            if (!getline(cin, line)) {
                break;
            }
            st = StringTokenizer(line);
        }
        return st.nextToken();
    }

    int nextInt() {
        return stoi(next());
    }
};

class StringTokenizer {
private:
    vector<string> tokens;
    size_t pos;

public:
    StringTokenizer(const string& str) : pos(0) {
        stringstream ss(str);
        string token;
        while (ss >> token) {
            tokens.push_back(token);
        }
    }

    bool hasMoreTokens() const {
        return pos < tokens.size();
    }

    string nextToken() {
        if (hasMoreTokens()) {
            return tokens[pos++];
        }
        return "";
    }
};

